export const ASSIST_DOCS_INDEX: readonly AssistDocsSection[] = [
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: '', anchor: '', text: '# Copy & paste elements Duplicate makes another copy right where you are. Copy and paste goes further: it carries an element, with everything inside it, to somewhere else entirely — another screen, a layout, a reusable component, an email template.' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: 'Copy', anchor: '#copy', text: 'Select an element and either: - press Cmd / Ctrl + C , or - open the element\'s ⋮ menu (on the canvas overlay or in the hierarchy) and choose Copy. The whole subtree comes along — a column you built copies with every link inside it. With several elements selected the menu reads Copy selection and takes them all, in document order. If your selection includes both a container and something already inside it, the container wins: you get one copy, not two.' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: 'Paste', anchor: '#paste', text: 'Select where it should go and press Cmd / Ctrl + V , or choose Paste from the same ⋮ menu. The menu item names what\'s waiting — Paste Stack, Paste 3 elements — and is greyed out when nothing has been copied. Where it lands follows the same rule as Add element: - Select a container (a Stack, Section, Container) and the copy goes inside it, at the end. - Select a leaf — a Screen Link, button, icon, image — and the copy goes beside it as the next sibling, because a leaf has no slot to render children in. Everything pasted is selected afterwards, so you can retext or restyle it straight away. Paste is a single undo step.' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: 'Between documents', anchor: '#between-documents', text: 'What you copy stays copied after you navigate. Open a different screen, layout, component or template and paste — the clipboard is still there. This is the fastest way to reuse a structure you have already built and refined. Two things to know: - The copy is a snapshot, not a link. Editing the original later does not change what you pasted. When you want one source of truth across many places, promote it to a reusable component instead. - Elements have to exist where you\'re pasting. A block copied from an email template uses email elements, and pasting it into a site screen is refused with a message naming the element that isn\'t available there. Nothing is half-pasted — the paste either lands completely or not at all.' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: 'Copy & paste vs. Duplicate vs. reusable components', anchor: '#copy--paste-vs-duplicate-vs-reusable-components', text: '| You want | Use | | -- | -- | | Another one right here | Duplicate | | The same structure somewhere else, edited separately from then on | Copy & paste | | One thing that updates everywhere it appears | Reusable component |' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: 'Shortcuts', anchor: '#shortcuts', text: '| Action | Shortcut | | -- | -- | | Copy selection | Cmd / Ctrl + C | | Paste | Cmd / Ctrl + V | | Select every element at the same depth | Cmd / Ctrl + A | These act on elements, not text. While you\'re editing text — in the attributes panel, in a dialog, or directly on the canvas — the shortcuts do the ordinary thing and copy or paste the text instead.' },
  { path: '/building-sites/besigner/copy-paste', title: 'Copy & paste elements', heading: 'Related', anchor: '#related', text: '- Multi-select & multi-drag - Reusable components - The Besigner' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: '', anchor: '', text: '# Drag-and-drop hierarchy Every element on the canvas is a node in a tree. You rearrange that tree by dragging — and you add new elements by dragging them in from the drawer. This page covers all the ins and outs: where you can drag, how drop zones decide placement, why some elements accept children and others don\'t, and what happens when a drop isn\'t allowed.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Where you can drag', anchor: '#where-you-can-drag', text: 'Drag-and-drop works in two places, and they stay in sync: - The hierarchy panel — drag a node up, down, or onto another node to reorder or reparent it. Good for precise moves and for deeply nested trees. - The canvas — grab an element on the live page and drop it where you want. Good for visual, in-context placement. A move made in one place is immediately reflected in the other.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'What a drag does', anchor: '#what-a-drag-does', text: '- Reorder — drag a node between two siblings to change its position in the same parent. - Reparent — drag a node onto a different container to move it into that container. - Add — drag a component from the elements drawer onto the canvas to create a new element at the drop point. Every drag is a single undoable step — press Undo (⌘/Ctrl+Z) to put it back.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Drop zones: edges vs. center', anchor: '#drop-zones-edges-vs-center', text: 'As you drag over an element, the Besigner splits it into drop zones and shows a placement marker for the zone you\'re pointing at. The zone decides where your element lands: - Edges — the thin bands along an element\'s top, bottom, left, and right. Dropping on an edge places your element as a sibling, before (top/left) or after (right/bottom) the element you\'re over — in the same parent. - Center — the large area in the middle. Dropping in the center places your element inside, as a child of that element. The placement marker is the source of truth. A line between elements means "reorder/insert as a sibling here"; a marker within an element means "drop inside as a child." Always glance at the marker before you release.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Containers vs. leaf elements', anchor: '#containers-vs-leaf-elements', text: 'Whether the center zone means "drop inside" depends on the kind of element you\'re over. ### Containers accept children Containers are built to hold other elements: Stack, Box, Section, Card, App Bar, Toolbar, and similar. Dropping onto a container\'s center nests your element inside it. This is how you build structure — a Stack of buttons, a Section full of blocks, and so on. ### Leaf elements don\'t — dropping on one makes a sibling Leaf elements have no slot for child elements. There are three kinds: - Text elements render their content as inline text — a Screen Link, a Button, or a Text element. Their words are their content; there\'s nowhere to nest a child. - Self-closing elements draw themselves and take no children at all — an Image, an Icon, or a Video. - Elements whose content is an attribute look like containers but draw only what their attributes say — a Markdown block (its document is the Content attribute), a List Item Text row (its words are Primary/Secondary), a Reusable Component instance (its content lives in the definition), and a Layout Slot (filled by the screen bound to the layout). Anything nested inside one of these has nowhere to appear on the published page. Dropping onto a leaf places your element as a sibling right after it, inside the leaf\'s parent — never nested inside the leaf. Over a leaf you\'ll only ever see a before/after placement marker, never an "inside" one, so the marker always matches where the element actually lands. :::info Why this matters Aiming at the middle of a small element like a Screen Link used to tuck the new element inside it, where it wouldn\'t render as expected. Now a leaf\'s center reads as "place next to me," which is almost always what you want — and you don\'t have to aim precisely at its edges. The third kind is the ' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Adding a new element', anchor: '#adding-a-new-element', text: 'Insert → New Element (and the toolbar +) adds the component you pick relative to your current selection, following the same container-vs-leaf logic as a drop: - Select a container — a stack, section, or the document itself — and the new element is added inside it. - Select a leaf — anything without a child slot, such as a screen link, button, or icon — and the new element lands as its next sibling in the same container, rather than nested inside it. - With nothing selected, the element is added at the end of the document. You can also drag straight from the elements drawer, which groups components into curated categories (Sections & Blocks first, then Layout, Navigation, Text, and so on). A dragged-in component lands using the same drop-zone and placement rules described above.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'When a drop is rejected', anchor: '#when-a-drop-is-rejected', text: 'Not every element can go everywhere. Two kinds of guardrails apply: - Placement (lineal) rules. Components can declare what they accept as children or require as a parent — a Toolbar belongs in an App Bar, a layout slot accepts only certain content, and so on. If a drop breaks a rule, the Besigner rejects it and tells you why, naming the specific rule, so you can adjust instead of guessing. The same rules run for Insert → New Element, so you can\'t create an arrangement that drag-and-drop would refuse to make. - You can\'t move an element inside itself (or into one of its own descendants). That move is blocked with a clear message. Layout-only components are additionally gated by the view type you\'re editing (a screen vs. a shared layout).' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Moving an element without dragging', anchor: '#moving-an-element-without-dragging', text: 'Dragging isn\'t the only way to move an element between containers. Every element\'s ⋮ menu — on the canvas overlay, and on the hierarchy row — carries four move actions that work by clicking: - Shift up / Shift down — reorder the element among its siblings, without changing its container. - Move out of container — lift the element out of the container it\'s in, landing it directly after that container, one level up. - Move into element above — tuck the element into the sibling directly above it. Used together, these reach anywhere in the tree: move out, shift until the element is sitting next to the container you want, then move into. This is the reliable route in a deeply nested tree, on a long page where the source and destination aren\'t on screen at the same time, or any time a drag is fiddly. Each action is a single undoable step, and each obeys exactly the same rules a drag does — including the leaf rule. An element whose content is an attribute (a Markdown block, a Reusable Component instance, a Layout Slot, a List Item Text) can\'t hold other elements, so Move into element above is greyed out over one, and Move out of container refuses to drop an element into one. When an action is unavailable the Besigner says why rather than moving the element somewhere it would never render.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Multi-drag', anchor: '#multi-drag', text: 'Select several nodes first, then drag any one of them to move the whole selection at once. The group keeps its document order at the destination, and each node is still checked against the placement rules — anything that can\'t legally move is skipped rather than blocking the rest. See Multi-select & multi-drag.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Tips', anchor: '#tips', text: '- Watch the placement marker — it\'s the definitive preview of where the drop lands. - Aim at an edge to place beside an element; aim at the center of a container to place inside it. - Dropping on a leaf always makes a sibling — you don\'t have to be precise about its edges. - Undo any drag you didn\'t mean. - Use the hierarchy panel for precise moves in busy or deeply nested trees.' },
  { path: '/building-sites/besigner/drag-drop-hierarchy', title: 'Drag-and-drop hierarchy', heading: 'Related', anchor: '#related', text: '- Multi-select & multi-drag - The Besigner overview - Inline & rich text editing - Screens & layouts' },
  { path: '/building-sites/besigner/edit-from-the-live-site', title: 'Edit from the live site', heading: '', anchor: '', text: '# Edit from the live site Browsing your published site and spot something to fix? The admin bar connects your console edit access to the live site, so any page you\'re looking at is one click from its screen in the besigner. :::caution Rolling out The admin bar is a release-flagged feature, currently being rolled out — it may not be available on your site yet. Nothing needs configuring; it switches on per-workspace as the rollout proceeds.' },
  { path: '/building-sites/besigner/edit-from-the-live-site', title: 'Edit from the live site', heading: 'Call it up', anchor: '#call-it-up', text: 'On any page of your published site, either: - add ?aglyn-edit to the URL — handy as a shareable habit, or - press Cmd/Ctrl + Shift + E. A small Edit this site pill appears in the bottom-right corner. Visitors never see it — the pill only appears when you ask for it, and the bar itself only renders for accounts that actually hold edit access.' },
  { path: '/building-sites/besigner/edit-from-the-live-site', title: 'Edit from the live site', heading: 'Connect your access', anchor: '#connect-your-access', text: 'Click the pill. Because your published site and the console live on different domains, a small console popup opens to confirm it\'s really you: it checks your console sign-in and your role on this site, then reports "Connected — edit access confirmed" and closes itself. If you\'re not signed in to the console, it says so and waits for you to sign in and try the shortcut again; an account without edit rights gets a plain "No edit access". Edit access means what it does everywhere else: a site admin or editor, or a workspace owner, admin, or editor. Viewers don\'t get a read-only bar — they simply don\'t get one.' },
  { path: '/building-sites/besigner/edit-from-the-live-site', title: 'Edit from the live site', heading: 'The bar', anchor: '#the-bar', text: 'Once connected, a slim dark bar sits along the bottom of the page: - the site name, and the name of the screen serving the current page; - Edit this page — opens the besigner for exactly that screen, in a new tab (shown whenever the page maps to a routed screen); - Open console — the site\'s dashboard; - × hides the bar for the rest of the page view. The bar follows you as you browse — navigate to another page and it re-resolves which screen you\'re on.' },
  { path: '/building-sites/besigner/edit-from-the-live-site', title: 'Edit from the live site', heading: 'Good to know', anchor: '#good-to-know', text: '- The connection lasts for the browser tab (and tokens expire after 30 minutes on their own) — closing the tab forgets it, and the site sets no new cookies. - The bar is a convenience surface only: it never changes what the page serves, and all real editing still happens in the console with your normal permissions.' },
  { path: '/building-sites/besigner/edit-from-the-live-site', title: 'Edit from the live site', heading: 'Related', anchor: '#related', text: '- The Besigner - Publish your first screen - Teams, roles & membership' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: '', anchor: '', text: '# Element catalog These are the built-in elements in the ELEMENTS drawer, grouped by the categories the drawer uses. Every one of them ships with a preset — dropping it gives you an element that already has content in it, not an empty box you have to fill before you can see it. Elements from installed plugins appear under their own groups (Marketplace, Your components) and are not listed here. :::tip Anything on this page can be styled from the Styles panel, targeted by interactions, and made responsive per breakpoint. The attributes below are the element-specific settings in the Attributes panel.' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Layout', anchor: '#layout', text: '| Element | What it\'s for | | --- | --- | | Box | The plain container. No styling of its own — you give it padding, background and borders from the Styles panel. Renders as div, span, p, figure, figcaption, blockquote or pre. For landmarks, use Section instead. | | Section | Grouping inside a semantic HTML element (section, article, aside, nav, header, footer, main) with an accessible label, so the page keeps a meaningful document outline. | | Container | Centres content and caps its maximum width. | | Stack | One-dimensional row or column with a gap. Also the element that carries repeat over a dataset. | | Grid | Responsive 12-column layout. See Grid below. | | Layout slot | Where a bound layout injects the screen\'s own content. | ### Grid Grid does both jobs in one element, matching Material UI\'s current API: - Turn Container on for the row. It gets Spacing, Row spacing, Column spacing and Columns (the row is divided into 12 by default). - Leave Container off for a cell, and give it a Span. Span and Offset are typed as text so one field covers every breakpoint: | You type | You get | | --- | --- | | 6 | Half the row at every size | | auto | Just wide enough for the content | | grow | All the space the other cells don\'t take (Span only) | | xs:12 md:4 | Full width on mobile, a third from md up | Breakpoint keys are xs, sm, md, lg and xl; xs:12, md:4 with commas works too. If part of what you type can\'t be read, the whole value is ignored rather than half-applied — a layout that silently differs from what you typed is worse than one that plainly doesn\'t work.' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Surface', anchor: '#surface', text: '| Element | What it\'s for | | --- | --- | | Paper | A themed surface. Elevation 0–24 raises it with a shadow; the Outlined variant swaps the shadow for a border (and hides the elevation control, which does nothing there). | | Card | A surface for one subject, composed from Card Header (title + subheader), Card Content (the padded body) and Card Actions (the button row). Each piece is its own element, so you can select, style and reorder them. | | Accordion | A header that expands to reveal its details, built from Accordion Summary and Accordion Details. See Accordion below. | ### Accordion Start expanded controls whether visitors arrive with the panel open. On the canvas the panel is always shown open regardless — collapsed details can\'t be selected or styled. Preview and the published site both behave the way you configured it, so what ships is never in doubt. Accordion Summary takes an optional Header links to. Leave it empty and the whole header row toggles the panel, which is what every accordion does by default. Point it at a screen and the row splits in two: the header text becomes a link to that screen, and the chevron beside it becomes the toggle. That split is the only way a header can do both — a link placed inside the toggle button is invalid markup and unreachable by keyboard. It is what lets a mobile drawer offer Product both as a group to open and as a page to visit. The FAQ preset drops three complete panels at once.' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Navigation', anchor: '#navigation', text: '| Element | What it\'s for | | --- | --- | | Screen Link | A link that targets a screen by id, so it survives slug renames. Renders as a button or as a text link. | | App bar / Toolbar | The site header frame. | | Nav menu / Mega menu | Dropdown and full-width navigation menus. | | Drawer / Menu Button | A panel that slides in from the left, right, top or bottom. Open it with a Menu Button or an interaction. Width applies to left/right drawers; top and bottom sheets span the viewport, and the control is hidden for them. The Mobile Nav preset wires a hamburger, a drawer and a desktop link row in one insert. | | Tabs / Tab Panel | A tab strip and its panels. See Tabs below. | | Breadcrumbs | The trail showing where a page sits. Fill it with Screen Links so it survives renames, and leave the current page as plain Typography — linking a page to itself is the classic breadcrumb mistake. Set Collapse above to fold a long trail into an ellipsis. | | Pagination | A page picker. See Pagination below. | | Language switcher / Theme mode switcher | Locale and light/dark controls. | | Table of Contents | An "On this page" list built from the headings of a Markdown element on the same screen. | ### Tabs Type the tab names into Tabs, one per line. Then each Tab Panel child names the tab it belongs to in Shows under tab (capitalisation and surrounding spaces are ignored). Panels are matched by label, not by position, so reordering them in the hierarchy never shuffles your content. The preset ships three tabs with three matching panels, so you only touch the matching if you add a panel yourself. On the canvas every panel is shown stacked, each captioned with the tab it belongs to — a hidden panel can\'t be edited, and a caption with a name you don\'t recognise is a label typo you can see. ' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Text', anchor: '#text', text: '| Element | What it\'s for | | --- | --- | | Typography | One run of text — a headline, a label, a paragraph. The element you edit inline on the canvas. | | Markdown | A whole document, held as markdown source in one element. For policies, terms and anything whose real source is a .md file. See Long documents in markdown. | | Entry Body | A content entry\'s markdown body, on an entry-template screen. |' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Data Display', anchor: '#data-display', text: '| Element | What it\'s for | | --- | --- | | List | A vertical list. Optional sticky Heading, plus Dense and Disable padding. | | List Item | One row, with Divider, Align items, Dense, Disable gutters and Disable padding. | | List Item Text | Primary and secondary text, plus Inset to line the text up with rows that have an icon or avatar. | | Collection entries and friends | Content collections — entry lists, bodies, related posts, share bars. | | Custom HTML | Sanitized markup you supply. |' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Media', anchor: '#media', text: '| Element | What it\'s for | | --- | --- | | Image | An image with fit, size and radius controls, an optional link, and an automatic responsive srcSet for media-library URLs. | | Video | Hosted or embedded video. | | Icon | Any icon from the icon picker. | | Image List / Image List Item | A dense gallery. See Image List below. | ### Image List Pick a Variant: - Standard — a plain grid. - Quilted — tiles can span several columns and rows. Set Column span / Row span on the tiles; only this variant reads them. - Masonry — every image keeps its own aspect ratio. Row height is ignored here (and hidden), because a fixed height would crop exactly what masonry exists to preserve. - Woven — alternating tile sizes. Each tile holds an ordinary Image element, so galleries get the same responsive srcSet and lazy loading as an image anywhere else. Fill in Caption for a caption bar, or leave it blank for no bar at all.' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Forms, Input, Commerce, Members', anchor: '#forms-input-commerce-members', text: 'Forms and fields, buttons and widgets, product grids and cart companions, and the member sign-in/sign-up elements. These are covered with the features they belong to — see Forms, Commerce and Member accounts.' },
  { path: '/building-sites/besigner/element-catalog', title: 'Element catalog', heading: 'Related', anchor: '#related', text: '- The Besigner - Drag-and-drop hierarchy — which elements accept which children - Long documents in markdown — the Markdown and Table of contents elements - Responsive styling - Interactions & custom HTML' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: '', anchor: '', text: '# Interactions & custom HTML' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: 'Fluent interactions', anchor: '#fluent-interactions', text: 'Select any element and use Add interaction — everything configures in one dialog without leaving the besigner: - Trigger: when the element is clicked, hovered, the hover ends, or it scrolls into view. - Frequency: every time (the default — repeatable, for menu and drawer toggles), once per page view, once per session, once per visitor, or with a cooldown. - Actions (stack as many as you need). The basic actions below are pure in-page choreography — available on every plan (see Plan availability): - Show / hide / show-hide an element — pick any other canvas element from a list; no selectors or classes needed. Add the aglyn-hidden class to a target to start it hidden on the live site. Each of these takes an optional Delay (a later show/hide on the same target cancels a pending one — the classic hover grace period) and, for steps that can show, Close on Esc / Close on outside click so a revealed panel dismisses itself like a real menu. - Open / close / open-close a menu — drives a Dropdown or Mega Menu element. The target defaults to the element itself when it is a menu; leave it empty to address the page\'s first menu. A menu opened by When hovered closes itself when the pointer leaves the nav item and its panel. - Open / close / open-close a drawer — drives a Drawer element; leave the target empty to address the page\'s first drawer. - Toggle / append / remove a class — targets this element by default, or any CSS selector. Pair with your theme\'s utility classes for menus, reveals, and state changes. - Make the nav sticky, go to a URL / screen, or show a site alert — navigation and lightweight feedback, no server involved. - The remaining actions are the automations engine (Pro+, metered — see Plan availability): - Open an overlay, show custom HTML, or track an analytics ev' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: 'Plan availability', anchor: '#plan-availability', text: 'Interactions come in two tiers, and the field editor labels the steps that need a higher plan: - Basic interactions — every plan, including Free. Opening and closing menus and drawers, showing and hiding elements, toggling classes, sticky nav, navigation, and site alerts are pure client-side DOM behavior with no server cost. They run everywhere and are never metered — a hover-to-open menu is not a paid feature. - The automations engine — Pro+, metered. Steps that reach the server or a data pipeline — overlays, analytics events, custom JS (Business), and the server steps (workflows, email, datasets, campaigns) — require the actions entitlement and count against your monthly action runs. On a plan without the automations entitlement, an interaction that mixes tiers still runs its basic steps live; the Pro+ steps are simply skipped until you upgrade. See workflows & actions for the full step catalog and metering.' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: 'Pick the target by clicking', anchor: '#pick-the-target-by-clicking', text: 'Any action that points at an element — open a menu, show / hide, open a drawer — lets you choose the target visually: click Pick element, click the element on the canvas, and confirm. No CSS selectors to write, and the picker resolves the stable data-aglyn id under the hood so the target survives edits. A custom selector field is there as a secondary option for advanced cases (a class or attribute selector you maintain yourself). ### Interaction cookbook - Hamburger menu: on any button, When clicked → Open/close a drawer. (The Menu Button element does this without any interaction at all.) - Hover menu: on a Dropdown or Mega Menu element, When hovered → Open a menu at frequency every time. Clicking already toggles every menu with zero configuration; this adds the hover-open, and the menu closes itself when the pointer leaves. - Hover reveal: When hovered → Show an element plus When hover ends → Hide an element, both at frequency every time. - Mega menu from scratch (no Mega Menu element): wrap a trigger button and a panel in one Stack (panel: aglyn-hidden class, position absolute below the trigger). On the wrapper: When hovered → Show the panel, When hover ends → Hide it with a small Delay (say 250ms) so the pointer can travel; add Close on Esc to the show step for keyboard dismissal. The Dropdown Panel preset (Navigation group) inserts exactly this pattern with both interactions pre-wired — see menus & navigation. - Scroll reveal: on a section, When scrolled into view → Append class visible with a CSS transition, frequency once per visitor. - Announcement click-through: When clicked → Track analytics event plus Go to a URL.' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: 'Custom HTML block', anchor: '#custom-html-block', text: 'The Custom HTML block accepts markup and CSS with a strict safety model: - Sanitized by default — scripts, iframes, objects, forms, and inline event handlers (onclick etc.) are stripped on every render. What you paste can style and structure, never execute. - Embed mode for third-party widgets: the raw snippet runs inside a sandboxed iframe with scripts allowed but no access to your site, cookies, or visitor data. Set the iframe height to fit the widget. Prefer first-party blocks where one exists — embeds can\'t participate in theming or interactions.' },
  { path: '/building-sites/besigner/interactions-and-custom-html', title: 'Interactions & custom HTML', heading: 'Related', anchor: '#related', text: '- Walkthrough: build a mega menu with hover interactions - Menus & navigation - Besigner overview - Workflows & actions' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: '', anchor: '', text: '# Live co-editing & unsaved work The besigner is safe to share. When teammates open the same document you see each other — avatars, cursors, and selections — and edits flow between you live. And if a tab crashes or closes with unsaved work, the besigner keeps a local draft and offers it back. This works in every besigner editor: screens, layouts, reusable components, templates, and designed emails. :::info Plan availability Free. Presence, co-editing, conflict protection, and draft recovery are on for every plan — how many teammates can edit is a question of collaborator seats, not of this feature.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'Who\'s here', anchor: '#whos-here', text: 'When someone else has the document open, their avatar appears in the besigner toolbar (up to four; photo or initial, on their assigned color). Hovering explains exactly what presence means here: "«Name» is editing this too — saves are not merged" — and "(in 2 places)" when they have it open twice. If your own account has the document open somewhere else — another tab, or your account signed in on another machine — an amber badge appears beside the avatars warning that nothing merges between your own sessions either: whichever one saves last wins, and it won\'t warn you, because both are you. On the canvas, each collaborator shows up as: - a cursor in their color with their name on a small pill, and - a selection outline around the element they have selected, with their name in a tab above it. Everyone sees the same person in the same color, and the overlays never intercept your clicks.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'Editing together', anchor: '#editing-together', text: 'Edits are shared live, per element: change a heading while a teammate restyles the footer and you both keep your work. What lands in the document: - Different elements — both sets of edits apply. This is the normal case, and it just works. - The same element — last write wins. Co-editing shares changes; it does not merge two versions of one element. - A teammate\'s changes never enter your undo stack — undo rewinds only your own edits. Anyone with edit access to the site (a site admin or editor, or a workspace owner / admin / editor) can co-edit. Viewers see presence but their changes are refused at the door. Live edits are working state, not saves — the document still saves when someone presses Save, and a successful save is what makes the shared state durable.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'When saves collide', anchor: '#when-saves-collide', text: 'Co-editing shares unsaved edits, but saves are still whole-document and are not merged. If someone else saves the document while you\'re editing, the besigner tells you immediately — not twenty minutes later when you press Save: > Someone else saved this screen while you were editing. Saving is paused so their > work is not overwritten — reload to pick up their changes. Nothing you have done > here is lost until you do. The banner has one action — Reload — and that\'s deliberate: there is no "save anyway" that could silently destroy a teammate\'s work. Your canvas keeps everything you\'ve done until you reload, so the recovery is calm: note (or copy) what you need, reload to pick up their version, and reapply. Pressing Save while the banner is up answers with the same message rather than saving. The guard also runs server-side inside a transaction, so even a save racing the conflict by milliseconds is refused, never silently applied.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'Local draft recovery', anchor: '#local-draft-recovery', text: 'The besigner continuously keeps a local draft of your unsaved work in the browser — written about a second after you pause, and flushed when the tab is hidden or closed. If the tab crashes, the machine sleeps at the wrong moment, or you just close without saving, the next time you open that document you\'re offered the work back: > Unsaved changes to this screen from 3 minutes ago were recovered from this > browser. Restoring puts them back on the canvas without saving; you can undo it. - Restore puts the draft back on the canvas — unsaved and undoable, so you can inspect before committing to it. - Discard deletes the draft and keeps the saved document. - Nothing is ever restored automatically; the besigner always asks. - If a teammate saved while your draft was stranded, the offer says so and restoring will not overwrite their work — you\'ll be asked to reload before you can save. Drafts live in this browser only (they don\'t follow you across machines), are kept for up to 7 days, and are deleted the moment a save succeeds. They\'re a crash net, not version history — for named, durable snapshots use versions.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'The Save button always answers', anchor: '#the-save-button-always-answers', text: 'The toolbar\'s save control reads Save when there\'s work to save and Up to date when there isn\'t — and clicking always produces an answer (saving, "Already saved", or the conflict warning), never silence.' },
  { path: '/building-sites/besigner/live-co-editing', title: 'Live co-editing & unsaved work', heading: 'Related', anchor: '#related', text: '- The Besigner - Screens & layouts — versions - Teams, roles & membership' },
  { path: '/building-sites/besigner/long-form-markdown', title: 'Long documents in markdown', heading: '', anchor: '', text: '# Long documents in markdown Some pages aren\'t designed — they\'re written. A privacy policy, terms of service, an acceptable-use page or a staff handbook is a document, and its real source is usually a markdown file somewhere else: a repo, a Drive folder, whatever your lawyer sends back. The Markdown element puts that document on the canvas as one element, holding the source text. Updating the page is one paste. The Table of contents element reads that same text and builds the "On this page" list from its headings, so the list can never fall out of step with the document above it. :::tip Building a page out of one Typography element per paragraph is the alternative, and it costs you the thing that matters most here: you can\'t copy the page back out to compare it with the source file, and every heading you add means hand-editing the contents list too.' },
  { path: '/building-sites/besigner/long-form-markdown', title: 'Long documents in markdown', heading: 'The Markdown element', anchor: '#the-markdown-element', text: 'Drop Markdown from the Text group of the ELEMENTS drawer, then write or paste your document into the Content attribute. Content is a visual editor, not a text box. Headings, bold, italic, links, lists, quotes, images, code blocks and tables all have toolbar buttons, and the shorthands below still work as you type — start a line with ## and it becomes a heading. Pasting from a word processor or a Google Doc keeps its formatting rather than arriving as one flat paragraph. The toolbar\'s Markdown switch shows the raw source instead, for when you want to paste a whole file in one go or check exactly what\'s stored. Both views edit the same text — the element stores markdown either way. Double-click the element on the canvas to get the same editor over the document itself, without going to the attributes panel — the same gesture that edits any other text element in place. What you type is kept as you type it, so Done, pressing Esc, and clicking another element all leave the document saved; use undo (⌘Z) to take an edit back. Text is set for reading rather than for a layout: 17px on a generous line height, in the theme\'s primary text colour, with headings that step up in size on wider screens. You don\'t need to style anything for it to look right. The element draws its Content attribute and nothing else, so it takes no child elements — there\'s no position in a parsed document an element could occupy. Dropping onto it places your element next to the Markdown block rather than inside it, the same way every other leaf element behaves. To put a picture in the document, write it as markdown — — and to put one beside the document, drop an Image as a sibling. ### What the markdown supports | You write | You get | | --- | --- | | ## A heading | A top-level heading — and an anchor a con' },
  { path: '/building-sites/besigner/long-form-markdown', title: 'Long documents in markdown', heading: 'The Table of contents element', anchor: '#the-table-of-contents-element', text: 'Drop Table of contents from the Navigation group. On a page with one Markdown element, that\'s the whole setup — it finds it and lists its headings. | Attribute | What it does | | --- | --- | | Markdown element | Which Markdown element to read. Leave it empty unless the screen has more than one. | | Heading | The label above the list. Defaults to On this page; clear it for no label. | | Levels | List ## and ### headings, or ## only. | Sub-headings are indented under their parents. Each entry is a real link, so it can be copied, opened in a new tab and followed by a crawler — clicking one scrolls the page to the matching heading. ### How it finds the markdown By walking the screen, in reading order — not by looking for anything in the page\'s HTML. That\'s what makes it work everywhere: on the canvas, in Preview and on the published site. - Left empty, it takes the first Markdown element on the screen. - Set to a specific element, it takes that one. - Set to an element that\'s since been deleted, it falls back to the first one. Deleting and re-adding a Markdown element is exactly what re-pasting a document looks like, and a published page with an empty aside is the worse outcome. Put the contents list wherever you like — most often in an aside column beside the document, or above it on narrow screens. It doesn\'t have to be near the Markdown element, or after it.' },
  { path: '/building-sites/besigner/long-form-markdown', title: 'Long documents in markdown', heading: 'Heading links', anchor: '#heading-links', text: 'Every ## and ### heading gets an anchor id built from its own words: - lower-cased, with accents folded to plain letters (Résumé → resume) - anything that isn\'t a letter or a digit becomes a hyphen, and runs of hyphens collapse - leading and trailing hyphens are trimmed So ## Your Rights & Choices is #your-rights-choices, and ### Section 4.2 — Retention is #section-4-2-retention. The rule is deterministic: the same words always produce the same link. Re-pasting an updated document doesn\'t break links people have already shared or bookmarked, as long as the heading still says the same thing. If a document repeats a heading, the second one gets -2, the third -3, and so on in document order — and the numbering skips anything already taken, so a document containing ## Notice twice and ## Notice 2 still ends up with three distinct links. :::note Anchors come from the document\'s own words, so two Markdown elements on one screen with the same headings will produce the same ids twice. On a page like that, give the second document distinct headings — or split it onto its own screen, which is usually what it wanted anyway.' },
  { path: '/building-sites/besigner/long-form-markdown', title: 'Long documents in markdown', heading: 'Related', anchor: '#related', text: '- Element catalog - Text editing — for headlines and short copy, where Typography is the right element - Screens and layouts' },
  { path: '/building-sites/besigner/multi-select', title: 'Multi-select & multi-drag', heading: '', anchor: '', text: '# Multi-select & multi-drag Working element-by-element is slow. The Besigner lets you select multiple nodes — in the hierarchy or on the canvas — and act on them together.' },
  { path: '/building-sites/besigner/multi-select', title: 'Multi-select & multi-drag', heading: 'Select multiple', anchor: '#select-multiple', text: '- On the canvas, add elements to the selection as you click. - In the hierarchy, select multiple nodes the same way. - Selection spans both surfaces — what you pick in the hierarchy is reflected on the canvas and vice versa.' },
  { path: '/building-sites/besigner/multi-select', title: 'Multi-select & multi-drag', heading: 'Move the whole selection', anchor: '#move-the-whole-selection', text: 'Once several nodes are selected, dragging moves the entire selection at once, preserving their arrangement. This is the fast way to reposition a group without grouping them permanently.' },
  { path: '/building-sites/besigner/multi-select', title: 'Multi-select & multi-drag', heading: 'Tips', anchor: '#tips', text: '- Selection overlays render inside the viewport\'s stacking context, so they highlight the right elements without disturbing page scroll. - Combine with drag-and-drop reparenting to move a group into a new parent.' },
  { path: '/building-sites/besigner/multi-select', title: 'Multi-select & multi-drag', heading: 'Related', anchor: '#related', text: '- Drag-and-drop hierarchy - The Besigner' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: '', anchor: '', text: '# The Besigner The Besigner is Aglyn\'s visual editor. You build a screen by placing components on a canvas, arranging them in a hierarchy, and editing content directly on the page. It renders your screen under the real site theme, so what you see matches what publishes. 1. Primary bar — the document switcher, File/Edit/Insert menus, the Publish/Unpublish button, the ƒx functions panel, the version you\'re editing, and notifications. 2. Toolbar — add elements, undo/redo, scheme and device preview, panel toggles, and the Live/Preview/save state on the right. 3. Hierarchy & elements — the node tree of the screen and the drawer of components you can add. 4. Canvas — your screen rendering live under the real site theme; select, drag, and edit text inline. 5. Inspector — info, attributes, and styles for the selected element.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'Preview vs. canvas', anchor: '#preview-vs-canvas', text: 'The canvas is an editing surface: hidden panels expand when you select them, so you can style what you can\'t otherwise reach, and nothing responds to hover the way a visitor would experience it. Preview (in the toolbar) renders the same draft the way the published site will: author-hidden panels start closed, and hover and click interactions actually run — so a mega menu, dropdown, or popup behaves exactly as it will live. Two deliberate differences from the real site: - Links don\'t navigate. You stay on the screen you\'re previewing. - Server-side steps don\'t fire — no analytics events, webhooks, or automations. A preview never writes data or spends quota. Use Preview to check interaction behavior before publishing, and the canvas to edit the parts a visitor would never see open. :::info Plan availability Free. The Besigner is core to building; some components and actions it exposes are plan-gated (noted where relevant).' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'What you can do', anchor: '#what-you-can-do', text: '- Drag-and-drop components from the drawer onto the canvas, and reparent them by dragging in the hierarchy or on the canvas. The drawer and the New Element picker group components into curated categories, with the Sections & Blocks library first — composed, ready-made sections ahead of the primitives. The groups, in order: Sections & Blocks, Layout (boxes, containers, stacks, grids, sections, layout slots), Navigation (app bar, toolbar, screen links, tabs, breadcrumbs, pagination, drawers, language switcher, social links), Text, Forms (forms, fields, search), Input (buttons, switches, widgets), Media (images, video, icons, image lists), Data Display (lists, custom HTML, feeds), Commerce (product grids, cart, checkout companions), Members (sign-in, sign-up, password recovery), Surface (paper, cards, accordions), then any plugin-provided groups such as Marketplace and Your components. Every built-in element is listed in the element catalog. - Multi-select across the hierarchy and canvas, then move the whole selection at once. - Edit text inline — double-click a text-capable element to type directly; opt-in elements support basic rich text. - Bind a layout so the screen renders inside a shared header/footer frame. - Preview color schemes with the artboard light/dark toggle, matching the live site\'s system-driven scheme.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'The canvas', anchor: '#the-canvas', text: 'The canvas shows your screen composed with its theme and, if bound, its layout. Selection overlays highlight the active element without affecting page scroll. When a drop isn\'t allowed, the Besigner explains why — it surfaces the specific placement (lineal) rule that rejected the move, so you\'re never guessing.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'Hierarchy panel', anchor: '#hierarchy-panel', text: 'Every element on the canvas is a node in a tree. The hierarchy panel lets you: - Reorder and reparent nodes by dragging (with a placement marker showing the target slot). - Select multiple nodes and act on them together. - See which nodes are layout-only vs. screen content. - Copy a node and its children and paste them elsewhere — including into a different screen, layout or component. See Copy & paste elements.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'Inline and rich text', anchor: '#inline-and-rich-text', text: '- Double-click any text-capable component to edit its text on the canvas. - Components that opt in support basic rich text (bold, links, and similar). - You can also set a component\'s text from the Text attribute field in the inspector.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'Reusable components', anchor: '#reusable-components', text: 'Promote any subtree into a reusable component, then insert instances of it across screens. Editing the source updates every instance at render time. You can rename, demote, or delete reusable components from the site dashboard. See Reusable components.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'Editing together', anchor: '#editing-together', text: 'Two people can open the same document and edit it live: you see each other\'s avatars in the toolbar, cursors and selections on the canvas, and element-level changes as they happen. Saves are protected against overwriting each other, and unsaved work survives a crash as a local draft. See Live co-editing & unsaved work.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'AI in the canvas', anchor: '#ai-in-the-canvas', text: '- AI copy assist rewrites or generates text for any canvas text prop. - AI Generate Section produces a constrained subtree straight onto the canvas. See AI Assist.' },
  { path: '/building-sites/besigner/overview', title: 'The Besigner', heading: 'Related', anchor: '#related', text: '- Element catalog - Copy & paste elements - Screens & layouts - Bindings & variables - Section & block library' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: '', anchor: '', text: '# Responsive styling & custom CSS' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Style per breakpoint', anchor: '#style-per-breakpoint', text: 'The artboard preview mode now doubles as your styling scope: - Fluid Responsive (default) — style edits apply at every screen size. - XS / SM / MD / LG / XL — edits in the styles panel apply from that breakpoint up, following the mobile-first cascade. Switch to SM – Tablet, change a padding, and phones keep the base value while tablets and up take the new one. A chip at the top of the styles panel always shows the active scope ("Styling: all screen sizes" or "Styling breakpoint: SM"). Values you don\'t touch keep inheriting — opening a panel at a breakpoint never pins anything by itself. Selecting a device also re-renders the canvas at that width: responsive values ({ xs, md }), visibility bands, and breakpoint-driven component layouts all resolve as they will on a real device of that size — the published site is untouched by preview mode.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Box stylers', anchor: '#box-stylers', text: 'The margin/padding stylers are fully interactive: - Pick the fan-out with Side / Axis / All: one side at a time, the vertical or horizontal pair together, or all four sides at once. - Click any side in the box diagram to edit its value inline, or use the per-side fields — each with a unit menu (px, %, em, rem, vh, vw…). - Everything respects the active breakpoint scope.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Style groups', anchor: '#style-groups', text: 'The styles panel organizes every control into accordions, and every field has exactly one home — no custom CSS needed for the common properties: - Flexbox & Grids — the container controls: alignment and direction toggles plus the gap, row-gap, and column-gap fields. - Layout — display variant and float. - Colors — text color, background color, and Background Fill (see gradient backgrounds). Both pickers open on theme color references first (see scheme-scoped colors); a Custom color step reveals the full picker. The two color fields hold a color — a hex, an rgb()/hsl() value, or a theme reference. Paste anything else (a gradient, a url(…)) and the field says so and refuses it, rather than saving a value the browser would silently drop. - Sizing — width, height, and the min/max bounds for both. - Typography — font size, weight, family, line height, letter spacing, text transform, and text decoration. - Borders & Shadows — border shorthand, border color (with your theme palette in the picker), a border field per edge (top, right, bottom, left) for dividers and accent rails, corner radius, outline, and a shadow preset menu (Subtle / Medium / Large / None). The shorthand draws all four edges; use the per-edge fields when you want a rule under a header or a line between columns. - Position & Overflow — position scheme with top/right/bottom/left offsets, z-index, overflow, opacity, and cursor. - Grid & Flex Child — grid template columns/rows, auto-flow, and the per-item controls: grid column/row placement, flex grow, flex shrink, flex basis, and order. Length fields — width, height, the min/max bounds, font size, letter spacing, the position offsets, and flex basis — are a number box plus a unit menu, the same pairing as the box stylers, so you type the number and pick px, %, ' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Gradient backgrounds', anchor: '#gradient-backgrounds', text: 'Background Fill in the Colors group builds a gradient by clicking — no custom CSS. 1. Set Background Fill to Linear gradient (or Radial gradient) — the field opens as that one select. It starts from your theme\'s primary and secondary colors so you see a gradient immediately; Solid color paints no image and hands the element back to the Background Color field above. 2. Set the Angle in degrees for a linear fill — 180 runs top to bottom, 90 left to right. 3. Edit the color stops. Each stop is a color button plus a position in percent. The color button opens the same two-stage picker as every other color field, so a stop can be a theme color (it then follows your palette, in both light and dark) or a literal hex. One gradient can mix the two — bind the ends to Primary and Secondary and drop a literal mid-tone between them. Add stop adds one near the end of the ramp, ready to be positioned; a gradient always keeps at least two, so the remove button greys out at two. Background Fill writes background-image, which paints over the Background Color — so a solid color set there still shows through anywhere the gradient is transparent, and stays as the fallback if you switch the fill back to solid. The first choice in the menu — Default, or Inherited on a component instance — is not the same as Solid color. Default leaves the fill unset; Solid color is a positive "paint no image" (background-image: none). On an ordinary element they look identical, and on a component instance they are the difference between keeping the component\'s gradient and replacing it with your own background color. Like the other color fields, Background Fill is scheme-scoped: theme-color stops adapt on their own, and while the artboard previews dark you can give dark a different gradient outright. A backgr' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Visibility per device band', anchor: '#visibility-per-device-band', text: 'The Visibility accordion hides the selected element on whole device bands — mobile (under 600px), tablet (600–899px), and desktop (900px and up). Bands are range-scoped rather than mobile-first, so hiding one band never changes the element\'s display on the others — the classic "hide the link cluster on mobile, show a menu button instead" swap is two toggles (menus & navigation). On the canvas, bands follow the artboard: select a device in the preview switcher and the matching band applies at that device\'s width — XS shows the mobile band, SM the tablet band, MD and up the desktop band. In Fluid Responsive mode the canvas follows the real browser window instead, so resize the window (or open the published site) to see bands flip.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Scheme-scoped colors', anchor: '#scheme-scoped-colors', text: 'Published sites follow each visitor\'s light/dark scheme (system setting, or their own choice via the theme mode switcher component), so a hardcoded light-mode hex can be unreadable in dark mode. Two tools keep colors correct in both schemes: Theme color references (preferred). Every color picker — text, background, and border color, plus color attributes on components — opens on your site theme\'s palette references first: Primary, Secondary, Background, Surface, Text, Divider, and friends. Each swatch is split to preview its light and dark resolutions, and selecting one stores the reference (e.g. background.paper), not a fixed color — the element automatically re-colors when the site switches schemes. Pick Custom color to reveal the full picker when you really want a fixed value. Per-scheme custom colors. The artboard\'s scheme toggle (the sun/moon button in the toolbar) doubles as a styling scope, exactly like the device preview does for breakpoints: - Light preview (default) — color edits set the element\'s base colors, which both schemes share until dark overrides exist. - Dark preview — the styles panel shows a "Styling: dark scheme" chip, and edits to text, background, and border color become dark-only overrides. Light mode keeps the base values; the canvas shows the dark result as you edit. Only color fields scope to the scheme — spacing, sizing, typography, and layout always apply to both schemes no matter which one you preview. Clearing a color while previewing dark removes the override and falls back to the base color. Scheme overrides compose with breakpoint scoping: previewing dark on the MD – Laptop artboard writes a dark override that applies from MD up.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Custom classes', anchor: '#custom-classes', text: 'Every element accepts Classes (chips input under Classes & custom CSS). They merge into the rendered element, so you can target them from theme styles and from interaction class actions.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Custom CSS (sx)', anchor: '#custom-css-sx', text: 'The Classes & custom CSS section edits the element\'s sx in three modes: - Builder — property + value rows with grouped suggestions (layout, spacing, typography, background, border, effects). - CSS — paste plain declarations (border-radius: 8px;); they parse into the element\'s styles at the active breakpoint scope. - JSS (sx) — the full document as JSON, including responsive objects ({ xs, md }) and nested selectors ("&:hover"), for full control.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Semantic sections & theme mode', anchor: '#semantic-sections--theme-mode', text: '- The Section component groups children inside a real HTML element — section, article, aside, nav, header, footer, main, or div — keeping your page outline meaningful for SEO and assistive tech. - The Theme mode switcher component gives visitors a light/dark/ device-default override that persists across visits.' },
  { path: '/building-sites/besigner/responsive-styling', title: 'Responsive styling & custom CSS', heading: 'Edit JSON for one element', anchor: '#edit-json-for-one-element', text: 'Right-click any element → Edit JSON to edit just that element and its children as JSON (the rest of the screen is untouched). Apply validates component ids and node ids, and the change is undoable.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: '', anchor: '', text: '# Reusable components Build something once — a card, a call-to-action, a footer block — and reuse it everywhere as a reusable component. An instance is not a copy. It grafts the source at render time, so editing the component updates every page that places it. Change a font size once and the whole site follows. :::info Plan availability Starter and above. On Free, promoting an element answers "Reusable components require a Starter plan — see Billing to upgrade." There is no cap on how many components a site can have.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Promote', anchor: '#promote', text: '1. Select the element you want to reuse. The whole subtree comes with it. 2. In the Attributes panel, choose Save as reusable component. 3. Give it a name and an optional description, then Save component. The element you promoted becomes the first instance of the new component, in place. It keeps its position in the page and its element id, so the parent\'s child list, your undo history and the current selection all stay valid. That in-place swap is the point. If promoting left the original behind as ordinary elements, the document that defined the component would be the one place that never tracked it — you would edit the component later and this page alone would silently keep the old copy. :::note Save as reusable component appears only on an element that is not already an instance and is not locked by a shared layout. Elements a layout frames are locked on the screens that use it — open the layout to promote from there.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Insert instances', anchor: '#insert-instances', text: 'Insert instances from Your components in the element drawer, on any screen, layout, template or other component. On the canvas an instance renders its actual content, not a placeholder — what you see is what the page will render, with properties already resolved. The rendered elements are not canvas elements, though: clicking anywhere on an instance selects the instance, which is the only thing there you can select, move or delete. To change what is inside it, open the component.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Properties', anchor: '#properties', text: 'A component doesn\'t have to look identical everywhere. Give it properties and each place you use it supplies its own text, image or link — while the layout and the styling still come from the one component. This is what stops a hero from being rebuilt on every page. Only the words differ. ### Declare them 1. Open the component and choose File ▸ Properties… 2. Add property. Give it a name — headline, say — a type, an optional label for the Attributes panel, and a default. 3. The dialog shows each property\'s token under its name. | Type | Field in Attributes | | -- | -- | | Text | Single-line text | | Long text | Multi-line text | | Image | Image picker | | Link | Screen picker, or an external URL | | Number | Number | | Yes / no | Toggle | A Link property is a screen picker at both ends — in the dialog\'s Default column and in each instance\'s Attributes panel — exactly like a Button\'s own Link to screen field. It stores the screen\'s id, not its address, so the link keeps working when that screen\'s slug or parent changes. Choose External URL or path… for anything that is not one of your screens; a typed address is used verbatim and does not follow a rename. Link properties written before the picker existed hold a typed address. They keep working unchanged — but they are still typed addresses, so pick the screen again if you want them to survive a rename. Property names must start with a letter or underscore and contain only letters, numbers and underscores. A dot is rejected: the Attributes panel names its field for the storage path propValues. , which splits on dots, so hero.title would address a level that does not exist and its value would silently never reach the page. ### Use them Inside the component, put the property\'s token wherever the value belongs: It works in a' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Retrofit duplicated sections', anchor: '#retrofit-duplicated-sections', text: 'If the same section has already been copied onto several pages, converting it is safe and takes one pass: 1. On the page whose wording is correct, promote the section. It becomes an instance and the definition is created from it. 2. Open the component, declare a property for each part that differs between pages, and replace those texts with their tokens. Use the first page\'s wording as each default. 3. Save properties, then publish. 4. On every other page, insert an instance, check it renders, and only then delete the old section. Appending before deleting keeps the page\'s section order intact when the section is the last one. 5. Fill in that page\'s wording on the instance — or leave the fields empty where the copy was already identical. Deleting last is what makes this reversible: at every point the page still has exactly one copy of the section.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Detach', anchor: '#detach', text: 'Detach from component, on an instance, turns it back into ordinary elements with fresh ids — the confirmation reads "Detached — this copy no longer follows the component." Use it when one page needs a variation the shared source shouldn\'t carry. What you get is what the page was showing. The property values set on that instance — and every per-instance style applied to it, on its outer element and on each element inside it — are baked into the copy as ordinary text, images and styles, so the section looks identical before and after; it is simply editable now. Nothing in the copy still points at a property. Detach copies the component\'s published tree — unsaved or unpublished edits sitting in the component\'s working version are not what you get.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Nesting', anchor: '#nesting', text: 'A component can place instances of other components. Expansion runs to a depth of 5, which also bounds a component that accidentally references itself.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Used by', anchor: '#used-by', text: 'A component\'s detail page has a Used by card listing everything that places an instance of it, so deleting one is not a guess. Three places are searched, which is everywhere the renderer expands an instance: - the published version of every screen, - the published version of every layout, - and other reusable components — a component can be placed inside another one, so one used nowhere else can still be very much in use. Unpublished drafts and templates in your library are not searched. If the check fails — a dropped connection, say — the card says so and shows a Try again button. It never reports "nothing uses this" when it could not actually look. If a component is deleted while instances remain, those instances are left untouched rather than emptied: a missing definition never takes a published page down.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Manage', anchor: '#manage', text: 'From the site\'s Components page you can rename, edit the description, open the besigner, or delete a reusable component. The component\'s ID is persisted inside every screen that places it and never changes. You can also give a component its own icon, from the same picker the besigner uses for icon elements — either in the Edit component dialog on the Components page, or on the component\'s detail page. Every instance is then marked with it: in the hierarchy, on the canvas badge, and in the element drawer under Your components. A page assembled from promoted sections becomes readable at a glance. Components without an icon keep the generic package glyph.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Copy & paste vs. reusable components', anchor: '#copy--paste-vs-reusable-components', text: '| You want | Use | | -- | -- | | Another one right here | Duplicate | | The same structure somewhere else, edited separately from then on | Copy & paste | | One thing that updates everywhere it appears | Reusable component |' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Tips', anchor: '#tips', text: '- Reusable components are perfect for anything that repeats across pages — headers, CTAs, contact blocks. - Give a property a default that reads well on its own. A page that sets nothing should still look finished. - Detach when you need a one-off variation that shouldn\'t affect the shared source.' },
  { path: '/building-sites/besigner/reusable-components', title: 'Reusable components', heading: 'Related', anchor: '#related', text: '- Copy & paste elements - The Besigner - Screens & layouts' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: '', anchor: '', text: '# Inline & rich text editing Text is edited where it lives — right on the canvas — so you see the result as you type.' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'Edit inline', anchor: '#edit-inline', text: '- Double-click any text-capable component to edit its text directly on the canvas. - Type, then click away to commit. - A Markdown element opens the full document editor the same way — see Long documents in markdown.' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'Rich text', anchor: '#rich-text', text: 'Components that opt in support basic rich text — formatting like bold and links within the text — so you\'re not limited to plain strings.' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'The Text attribute', anchor: '#the-text-attribute', text: 'Prefer the inspector? Set a component\'s text from its Text attribute field instead of editing on the canvas. This is handy when the text is short or you\'re setting it alongside other attributes.' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'Bindings in text', anchor: '#bindings-in-text', text: 'Text props accept bindings — {{variable}}, {{fn:name(args)}}, and dataset fields — resolved live on the canvas with bound-content markers.' },
  { path: '/building-sites/besigner/text-editing', title: 'Inline & rich text editing', heading: 'Related', anchor: '#related', text: '- The Besigner - Bindings, variables & functions' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: '', anchor: '', text: '# Bindings, Variables & Functions Bindings put live values into your content. Instead of hard-coding text, you reference a variable, a function result, or a dataset field, and Aglyn resolves it when the page renders. :::info Plan availability Free to start, with plan caps on the number of variables, functions, and workflows.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Binding tokens', anchor: '#binding-tokens', text: 'Bindings appear inside text props as tokens: | Token | Resolves to | | --- | --- | | {{name}} | A site variable. | | {{fn:name(args)}} | The result of a function. | | Dataset field bindings | A value from a dataset record. | The Besigner resolves bindings WYSIWYG on the canvas and marks bound content so you can see what\'s dynamic.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Rename-safe id tokens', anchor: '#rename-safe-id-tokens', text: 'Bindings reference variables and functions by id, not by name. That means renaming a variable doesn\'t break anything that uses it. Legacy name-based tokens still resolve via a fallback, and imports are normalized to id form automatically. When you publish, older documents are migrated to id tokens.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Insert a variable', anchor: '#insert-a-variable', text: 'You never have to hand-type token syntax. Every text-capable attribute field in the Besigner (Text, Link URL, Image URL, …) has a small {x} insert button at its end. Click it to open the data picker — a searchable menu grouped by source: | Group | Tokens | When it appears | | --- | --- | --- | | Variables | Your site variables (inserted as rename-safe id tokens) | When the site has variables | | Functions | Your functions, with parameter placeholders | When the site has functions | | Entry | Collection-entry fields — Title, Excerpt, Link URL, Published date, … | Always (hint shows where they resolve) | | Collection | Collection name and slug | Always (resolves on collection pages) | | Dataset item | The fields of the repeated dataset, by display name | Only inside a repeating container | Picking an option inserts the token at your cursor, keeping the text around it — so you can compose values like Read “{{entry.title}}” → or https://example.com/blog/{{entry.slug}} by mixing typed text and inserted placeholders. Pick again to keep concatenating; the cursor lands right after each inserted token. Each variable option shows a live value preview so you can confirm what the binding resolves to before inserting it. Selected text is replaced by the inserted token, and the element-level Insert binding button on text elements opens the same picker (appending to the element text). ### Token pills Placeholders never show up as raw {{...}} syntax while you edit — each one renders as a small colored pill carrying the binding\'s current display name. Variables, functions, entry fields, collection fields, and dataset items each get their own stable color, so a glance tells you what kind of data a pill resolves to. Under the hood the stored value still keeps the rename-safe id token: the' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Typed variables', anchor: '#typed-variables', text: 'Create typed site variables and reference them as {{name}} in any prop. Types keep values consistent across the site.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'No-code functions', anchor: '#no-code-functions', text: 'Build functions in the in-editor function builder with a safe evaluator — no arbitrary code execution. Compose variables and other functions, and call them inline with {{fn:name(args)}}.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Where-used & safety', anchor: '#where-used--safety', text: 'Before you rename or delete a variable or function, run the where-used scan to see every screen and prop that references it, so changes are safe.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Workflows', anchor: '#workflows', text: 'Variables and functions compose into workflows — multi-step logic triggered by site events. See Workflows & actions.' },
  { path: '/building-sites/bindings/overview', title: 'Bindings, Variables & Functions', heading: 'Related', anchor: '#related', text: '- Datasets - The Besigner' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: '', anchor: '', text: '# Connect a domain Move your site from its Aglyn subdomain to a domain you own. It\'s one card, one DNS record, and one button — there\'s no multi-step wizard. :::info Plan availability Starter and above. On Free, the card explains: "Custom domains are included from the Starter plan — see Billing to upgrade."' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'Steps', anchor: '#steps', text: '1. In the site\'s Setup page, open the Custom Domain tab. The card explains: "Point your domain at Aglyn, then verify. A subdomain like www uses a CNAME. A bare apex cannot carry a CNAME, so point it at the same hostname with an ALIAS — or use the A record if your registrar has no ALIAS. Any one of these verifies", and lists the records with your domain filled in, each with a line saying when it\'s the right one. Type a bare apex and the ALIAS line comes first; type a subdomain and the CNAME line does. 2. At your registrar\'s DNS settings, add one of those records — see the quick reference below. 3. Back in Aglyn, type your domain into the Domain field and press Verify & connect. Aglyn checks DNS from public resolvers and, if the record checks out, connects the domain in the same click. 4. On success the card confirms "your-domain.com" connected and shows the domain as a green chip. An apex — connected by ALIAS or by A record, since both are checked the same way — gets an extra note: "Apex verified by the addresses it resolves to." If DNS hasn\'t propagated yet, Verify & connect tells you what it found instead — either the record it saw and what it expected, or that no record exists yet — and asks you to try again in a while. Nothing is saved on a failed verify, so re-running it is always safe.' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'After it connects', anchor: '#after-it-connects', text: 'The chip next to your domain says what it is actually doing. SSL provisions automatically — there is nothing to upload or renew — but it takes a few minutes, and the chip is how you tell "still working on it" from "stuck". | Chip | What it means | What to do | | --- | --- | --- | | your-domain.com — live | Attached, DNS resolves here, certificate issued. | Nothing. | | your-domain.com — issuing certificate | Everything checks out; the certificate is still being issued. | Wait a few minutes and press Check status. Until it finishes the domain may show a security warning. | | your-domain.com — ownership check needed | Your domain is registered to another account on our hosting platform, so it has to be proven yours first. | Add the TXT record the card prints, then press Re-attach. | | your-domain.com — DNS not pointing here | Attached, but the domain no longer resolves to us. | Check the record at your registrar — see troubleshooting. | | your-domain.com — not attached | Saved here, but not attached to the serving platform, so it serves nothing. | Press Retry attachment. If it keeps failing the domain is likely held by another account — contact support with the domain name. | | your-domain.com — attachment pending | Our attach call never landed, and the platform could not be asked just now. | Press Retry attachment. | Three buttons sit next to the chip: - Check status re-reads the live state. A certificate arrives on its own a few minutes later, and this is how you see that it has. - Retry attachment (labeled Re-attach once the domain is healthy) re-runs the platform attachment. Always safe to press. - Disconnect releases the domain — see below. If other DNS records are answering for the same name, the card says so and names them, even when the domain is live. That is wor' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'Your Aglyn subdomain afterwards', anchor: '#your-aglyn-subdomain-afterwards', text: 'Once the domain is connected and serving, your-site.aglyn.app redirects to it — same page, same path, so an old link to your-site.aglyn.app/pricing lands on https://your-domain.com/pricing. That is deliberate. Serving the same pages at two addresses splits your search ranking between them, and lets a search engine pick which one to show. One address keeps the credit on the domain you own. Disconnect the domain and the Aglyn subdomain starts serving again on its own, within a minute or so. The redirect is temporary by design so that reversal always works.' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'Registrar quick reference', anchor: '#registrar-quick-reference', text: 'The exact screen differs by registrar, but you only ever add one record: A subdomain (www.example.com, shop.example.com, …): | Field | Value | | --- | --- | | Type | CNAME | | Name / Host | www (or the subdomain you\'re connecting) | | Value / Target | sites.aglyn.app | | TTL | default is fine | A bare apex (example.com) — first choice: | Field | Value | | --- | --- | | Type | ALIAS (also called ANAME, or "CNAME flattening") | | Name / Host | @ | | Value / Target | sites.aglyn.app | | TTL | default is fine | A bare apex, if your registrar has no ALIAS — fallback: | Field | Value | | --- | --- | | Type | A | | Name / Host | @ | | Value | 216.198.79.1 | | TTL | default is fine | An apex can\'t carry a CNAME (that\'s a DNS rule, not an Aglyn one), which is why it needs one of these two instead. Prefer the ALIAS: it names sites.aglyn.app rather than an address, so your registrar resolves it to wherever Aglyn is serving from at the time, and nothing in your zone has to change if those addresses ever do. The A record is there because plenty of registrars offer no ALIAS/ANAME and no flattening — for those, it is the only way to point an apex, and it verifies exactly the same. Its one cost is that the address is pinned in your zone by hand: keep it in mind if you ever see the domain stop resolving long after it was working. :::note Cloudflare and other proxies CNAME flattening at the apex works, but leave the record DNS only (grey cloud) until verification succeeds — a proxied record resolves to the proxy\'s addresses, not Aglyn\'s. :::tip Want both www and the apex? Aglyn serves one connected domain per site. Connect the one you want as your canonical address, then have your registrar redirect the other to it — most registrars offer domain forwarding for exactly this.' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'One domain per site', anchor: '#one-domain-per-site', text: 'Each site carries a single custom domain, and a domain can only be connected to one site across all of Aglyn — connecting it elsewhere answers "That domain is already connected to another site". Disconnect it from the old site first.' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'Disconnect', anchor: '#disconnect', text: 'Disconnect, next to the connected domain\'s chip, releases the domain immediately — there is no confirmation step — and the Aglyn subdomain resumes serving within a minute or so. Disconnecting requires the site admin role. Aglyn never touches your DNS: the CNAME, ALIAS, or A record at your registrar is yours, so remember to remove or repoint it yourself after disconnecting.' },
  { path: '/building-sites/custom-domains/connect-a-domain', title: 'Connect a domain', heading: 'Related', anchor: '#related', text: '- Troubleshoot verification - Redirects - SEO toolkit' },
  { path: '/building-sites/custom-domains/overview', title: 'Custom Domains', heading: '', anchor: '', text: '# Custom Domains Every site starts on an Aglyn subdomain. When you\'re ready, connect your own domain — a subdomain like www.example.com or the bare apex example.com — self-serve, from the site\'s Setup page. :::info Plan availability Starter and above.' },
  { path: '/building-sites/custom-domains/overview', title: 'Custom Domains', heading: 'Connect a domain', anchor: '#connect-a-domain', text: '1. In Setup, open the Custom Domain tab. 2. Add one DNS record at your registrar — a CNAME to sites.aglyn.app for a subdomain, or an ALIAS/ANAME to the same hostname for a bare apex (an A record where your registrar offers no ALIAS). 3. Type the domain into the Domain field and press Verify & connect. Aglyn checks DNS and connects the domain in the same click; SSL provisions automatically. Each site carries one custom domain, shown as a chip on the card with Re-attach and Disconnect actions beside it. Once it serves, your .aglyn.app subdomain redirects to it, path preserved, so old links keep working. :::tip How-tos - Connect a domain — steps, apex records (ALIAS first, A as the fallback), and what happens after - Troubleshoot verification' },
  { path: '/building-sites/custom-domains/overview', title: 'Custom Domains', heading: 'Related', anchor: '#related', text: '- Getting started: create a site - SEO toolkit' },
  { path: '/building-sites/custom-domains/troubleshooting', title: 'Troubleshoot verification', heading: '', anchor: '', text: '# Troubleshoot verification If Verify & connect won\'t go green, it\'s almost always DNS. Work through these. :::info Plan availability Starter and above.' },
  { path: '/building-sites/custom-domains/troubleshooting', title: 'Troubleshoot verification', heading: 'Checklist', anchor: '#checklist', text: '1. Give it time. DNS changes propagate on a TTL — wait a few minutes and press Verify & connect again. Aglyn resolves your record through public DNS resolvers, so a change your registrar shows as saved can still take a while to be visible. 2. Read the message. A failed verify tells you what it found: either the record it saw and the target it expected, or that no record exists yet. That\'s usually the whole diagnosis. 3. Match the record to the name. - A subdomain (www.example.com) needs a CNAME to sites.aglyn.app. - A bare apex (example.com) needs an ALIAS/ANAME to sites.aglyn.app — an apex cannot carry a CNAME, and Aglyn verifies it by the addresses it resolves to. - If your registrar offers no ALIAS/ANAME, use an A record to 216.198.79.1 instead. It verifies the same way. If an apex that used to work has stopped resolving, check this address is still the one in your zone — an ALIAS never needs that check, which is why it\'s the first choice. 4. Remove conflicting records. Delete any old A/AAAA/CNAME records for the same host that point elsewhere. Two cases bite hardest: - An apex with a wrong CNAME (some DNS hosts allow one) never falls through to the A-record check — remove the CNAME so the A record can be evaluated. - A stale A record left over from a previous host answers alongside your ALIAS and wins unpredictably — delete the old A record outright. 5. Disable proxying temporarily. If your DNS provider proxies traffic (e.g. an orange-cloud toggle), the record resolves to the proxy\'s addresses instead of Aglyn\'s. Turn it off until verification succeeds.' },
  { path: '/building-sites/custom-domains/troubleshooting', title: 'Troubleshoot verification', heading: 'Verified but not serving?', anchor: '#verified-but-not-serving', text: 'Verification and attachment are separate steps under one button, and the chip next to your domain says which one you are waiting on — see the chip table for all of them. The three that come up most: - "— issuing certificate" is not a problem. DNS is right and the domain is attached; the certificate takes a few minutes. Press Check status rather than reconnecting. A security warning in the browser during this window is expected and goes away on its own. - "— ownership check needed" means your domain is registered to another account on our hosting platform. The card prints a TXT record — add it at your registrar exactly as shown, then press Re-attach. Nothing else will release the domain. - "— not attached" means the domain is saved on your site but not on the serving platform. Press Retry attachment. If it keeps returning, the domain is held somewhere else and support needs the domain name to release it. If connecting answers "That domain is already connected to another site", the domain is attached to a different Aglyn site — every domain can serve only one. Disconnect it there first.' },
  { path: '/building-sites/custom-domains/troubleshooting', title: 'Troubleshoot verification', heading: 'The site loads for some people and not others', anchor: '#the-site-loads-for-some-people-and-not-others', text: 'That is almost always two records answering for the same name — typically an A record left behind by a previous host sitting next to a correct ALIAS. DNS hands out one or the other, so it looks fine every time you try it. Aglyn names the offending records: Verify & connect warns about addresses that are not ours, and the card keeps showing them under the chip afterwards, even while the domain is live. Delete them at your registrar; nothing needs reconnecting once they are gone.' },
  { path: '/building-sites/custom-domains/troubleshooting', title: 'Troubleshoot verification', heading: 'Still stuck?', anchor: '#still-stuck', text: 'Confirm the record resolves from your machine (dig www.example.com CNAME or dig example.com A), then press Verify & connect again. Two different checks run, and it helps to know which one you are reading. Verify & connect is the one that decides whether a domain may be connected at all, and it runs only when you press it. Check status asks the serving platform what the domain is doing right now — including whether DNS still points here — so a record you changed after connecting shows up there rather than needing a disconnect and reconnect.' },
  { path: '/building-sites/custom-domains/troubleshooting', title: 'Troubleshoot verification', heading: 'Related', anchor: '#related', text: '- Connect a domain' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: '', anchor: '', text: '# Menus & navigation Real navigation needs more than a row of links. The Navigation group in the element picker ships menu elements with the interactivity built in — no code, no raw JSON: | Element | What it does | | --- | --- | | Dropdown Menu | A nav item that opens a dropdown of links — click-toggles out of the box, interactions do the rest. | | Mega Menu | A SaaS-style wide panel with a free-form slot for columns of links and promos. | | Drawer | A slide-in panel (left or right) with a slot for anything — the mobile menu building block. | | Menu Button | A hamburger icon button that opens/closes a drawer. | | Mobile Nav | A one-insert preset: menu button + drawer + inline desktop links, responsive wiring included. | | Dropdown Panel | A primitive-built hover panel — Stack + Button + hidden panel with the hover interactions pre-wired and editable. | All of them render closed on the live site until the visitor interacts, and the canvas mirrors that: menus show just their trigger and drawers a slim placeholder. Select the element — or anything inside it — and it expands in place so its contents stay selectable and editable; click elsewhere and it collapses again.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'Dropdown menu', anchor: '#dropdown-menu', text: 'Insert Dropdown Menu, set its Label, and drop screen links (or anything else) inside. Its only attribute is Label — how the menu opens is not an attribute: - By default, clicking the nav item toggles the menu. No configuration needed; the menu also closes on outside clicks and Esc . - Everything else is an interaction — e.g. When hovered → Open a menu on the menu element itself gives you a hover menu, and any other element can open, close, or toggle any menu. Menus opened by a hover interaction close themselves once the pointer leaves the nav item and its panel, with a short grace period so the pointer can travel between the two.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'Mega menu', anchor: '#mega-menu', text: 'Insert Mega Menu inside your nav bar. Its panel is a normal canvas slot — the preset starts you with three columns of links, but rows, images, and promo cards all work. Attributes: - Panel width — Fit content, Wide (720px), or Full width (edge-to-edge under the nav item). It opens exactly like the dropdown: click-toggle by default, and the classic SaaS hover behavior is one interaction — on the mega menu element, When hovered → Open a menu (the target defaults to the element itself). Hover-opened panels close on pointer leave automatically.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'Drawer & menu button', anchor: '#drawer--menu-button', text: 'The Drawer slides in from the page edge and holds any canvas children — typically a vertical stack of screen links. It opens three ways: 1. A Menu Button element. Clicking it toggles the page\'s first drawer — no configuration at all (which is why the Mobile Nav preset works with zero wiring). Its only attribute is Accessibility label; how it targets a drawer is not an attribute. 2. An interaction with the Open / Close / Open-close a drawer actions (below) — on the Menu Button itself when a page has several drawers and you need to point it at a specific one, or on any other element. 3. The built-in close button, backdrop click, or Esc — closing is always handled for you. Drawer attributes: Slides in from (left/right) and Width. The canvas renders the drawer inline at its configured width, so its links and headers stay full-size and editable.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'The Mobile Nav preset', anchor: '#the-mobile-nav-preset', text: 'Insert Mobile Nav (Navigation group) into your nav bar\'s toolbar and you get a working responsive pattern immediately: - a Menu Button — hidden on desktop, - an inline link row — hidden on mobile and tablet, - a Drawer with a vertical link stack, already answering the button. Swap the placeholder links for your screens and you\'re done. The show/hide wiring is plain visibility styling, so you can retune the breakpoints per element afterwards.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'The Dropdown Panel preset', anchor: '#the-dropdown-panel-preset', text: 'The menu elements above are purpose-built components. Dropdown Panel is the same result assembled from primitives — insert it and you get: - a wrapper Stack (position: relative) holding - a trigger Button, and - a panel Stack positioned under the trigger, three link columns inside, carrying the aglyn-hidden class so it starts closed on the live site (the canvas still shows it for editing). The difference from hand-building: the hover choreography arrives pre-wired. Inserting the preset creates two real interactions on the wrapper, enabled immediately and listed on its Interactions panel like any you\'d author yourself: 1. When hovered → Show the panel, with Close on Esc and Close on outside click. 2. When hover ends → Hide the panel with a 250ms delay, so the pointer can travel from trigger to panel. Because they\'re ordinary interactions and ordinary elements, everything is editable: restyle the panel, change the delay, swap the trigger for an icon button, or delete one interaction and wire your own. Use it when you want full styling control that the Mega Menu\'s panel attributes don\'t reach — and see the walkthrough\'s from-scratch recipe for the same pattern built by hand.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'Interactions for menus', anchor: '#interactions-for-menus', text: 'The props panel\'s Add interaction system understands menu choreography (interactions guide): - Triggers: When clicked…, When hovered…, When hover ends…, When scrolled into view… - Actions: Show / Hide / Show-hide an element (pick the target from a list of canvas elements), Open / Close / Open-close a menu (drives a Dropdown or Mega Menu; picking defaults to the element itself when it is a menu, or the page\'s first menu), and Open / Close / Open-close a drawer (defaults to the element itself when it is a drawer, or the page\'s first drawer). - Frequency: new interactions default to Every time so toggles keep working; the legacy once per page view and the per-session / per-visitor / cooldown caps are still there for announcements. Three patterns cover most menus: - Hover menu — on the Dropdown/Mega Menu element itself: When hovered → Open a menu. Leaving the nav item and its panel closes it automatically — no hover-ends interaction needed. - Custom hover reveal — on the trigger element: When hovered → Show an element (your panel), plus a second interaction When hover ends → Hide an element. - Custom hamburger — on any button or icon: When clicked → Open/close a drawer (or a menu). :::tip Start hidden To make a show-target start hidden, add the aglyn-hidden class under Styles → Classes & custom CSS. The live site hides it from the very first paint; the canvas keeps it visible so you can keep editing it.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'Responsive visibility', anchor: '#responsive-visibility', text: 'Styles → Visibility hides the selected element on whole device bands: - Hide on mobile (under 600px) - Hide on tablet (600–899px) - Hide on desktop (900px and up) Use it to hide the desktop link cluster on small screens and show a menu button instead. Bands are range-scoped, so hiding one never changes how the element displays on the others. :::note Canvas preview Pick a device in the artboard preview switcher and the canvas renders at that width — bands apply, the Mobile Nav swaps to its menu button, and breakpoint-scoped styles resolve for that device. In Fluid Responsive mode the canvas follows the real browser window instead. See responsive styling for how breakpoint-scoped styles behave on the canvas.' },
  { path: '/building-sites/menus-and-navigation/overview', title: 'Menus & navigation', heading: 'Related', anchor: '#related', text: '- Walkthrough: build a mega menu with hover interactions - Interactions & custom HTML - Responsive styling & custom CSS - Screens & layouts' },
  { path: '/building-sites/multilingual/add-a-locale', title: 'Add a locale', heading: '', anchor: '', text: '# Add a locale Publish your site in another language by adding a locale variant. :::info Plan availability Paid. This is multilingual v1.' },
  { path: '/building-sites/multilingual/add-a-locale', title: 'Add a locale', heading: 'Steps', anchor: '#steps', text: '1. Add a locale (e.g. es, fr) to your site. 2. Aglyn creates locale variants of your content, sharing the same structure as your default language. 3. Translate the screens\' text for that locale. 4. Publish. Aglyn emits hreflang tags so search engines serve the right language to each visitor.' },
  { path: '/building-sites/multilingual/add-a-locale', title: 'Add a locale', heading: 'Tips', anchor: '#tips', text: '- Keep structure identical across locales — translate the words, not the layout. - Add a language switcher so visitors can choose their language.' },
  { path: '/building-sites/multilingual/add-a-locale', title: 'Add a locale', heading: 'Related', anchor: '#related', text: '- Language switcher - SEO toolkit' },
  { path: '/building-sites/multilingual/language-switcher', title: 'Add a language switcher', heading: '', anchor: '', text: '# Add a language switcher Once you\'ve added a locale, give visitors a language switcher so they can pick their language. :::info Plan availability Paid.' },
  { path: '/building-sites/multilingual/language-switcher', title: 'Add a language switcher', heading: 'Steps', anchor: '#steps', text: '1. Add the language switcher to a screen or your shared layout (so it appears site-wide). 2. It lists your active locales and links each visitor to the matching variant of the current page. 3. Publish.' },
  { path: '/building-sites/multilingual/language-switcher', title: 'Add a language switcher', heading: 'Tips', anchor: '#tips', text: '- Put the switcher in your layout header/footer so it\'s available on every page. - Pair it with hreflang (emitted automatically) so both people and search engines land on the right language.' },
  { path: '/building-sites/multilingual/language-switcher', title: 'Add a language switcher', heading: 'Related', anchor: '#related', text: '- Add a locale' },
  { path: '/building-sites/multilingual/overview', title: 'Multilingual', heading: '', anchor: '', text: '# Multilingual Reach a wider audience by publishing your site in more than one language. :::info Plan availability Paid. Multilingual is available on paid tiers.' },
  { path: '/building-sites/multilingual/overview', title: 'Multilingual', heading: 'Locale variants', anchor: '#locale-variants', text: 'Create locale variants of your content so each language has its own version, while sharing the same structure.' },
  { path: '/building-sites/multilingual/overview', title: 'Multilingual', heading: 'hreflang & discovery', anchor: '#hreflang--discovery', text: 'Aglyn emits hreflang tags so search engines serve the right language to the right visitor.' },
  { path: '/building-sites/multilingual/overview', title: 'Multilingual', heading: 'Language switcher', anchor: '#language-switcher', text: 'Add a language switcher so visitors can move between locales themselves. :::tip How-tos - Add a locale - Add a language switcher This is multilingual v1.' },
  { path: '/building-sites/multilingual/overview', title: 'Multilingual', heading: 'Related', anchor: '#related', text: '- SEO toolkit - Screens & layouts' },
  { path: '/building-sites/redirects/create-a-redirect', title: 'Create a redirect', heading: '', anchor: '', text: '# Create a redirect Send an old or alternate URL to the right screen. :::info Plan availability Paid.' },
  { path: '/building-sites/redirects/create-a-redirect', title: 'Create a redirect', heading: 'Add a rule', anchor: '#add-a-rule', text: '1. Open the redirect manager page. 2. Enter the source path (the URL to redirect) and the destination. 3. Save. The rule is validated on save, with chain-loop and screen-collision checks so it can\'t loop or shadow a real screen. The published site enforces redirect rules during route resolution, so the redirect takes effect on the live site immediately.' },
  { path: '/building-sites/redirects/create-a-redirect', title: 'Create a redirect', heading: 'Read hit metrics', anchor: '#read-hit-metrics', text: 'Each rule tracks sampled hit metrics. Use them to: - Confirm a redirect is actually being used. - Find rules with zero hits that you can safely delete.' },
  { path: '/building-sites/redirects/create-a-redirect', title: 'Create a redirect', heading: 'Related', anchor: '#related', text: '- Migration patterns - Redirects overview' },
  { path: '/building-sites/redirects/migration-patterns', title: 'Migration patterns', heading: '', anchor: '', text: '# Migration patterns Redirects earn their keep during change. Here are the patterns you\'ll reach for most. :::info Plan availability Paid.' },
  { path: '/building-sites/redirects/migration-patterns', title: 'Migration patterns', heading: 'Renamed a screen', anchor: '#renamed-a-screen', text: 'When you change a screen\'s slug, add a redirect from the old path to the new one so existing links and search results keep working.' },
  { path: '/building-sites/redirects/migration-patterns', title: 'Migration patterns', heading: 'Consolidated pages', anchor: '#consolidated-pages', text: 'Merging two pages into one? Redirect the retired path to the survivor. The screen-collision check keeps you from redirecting a path that\'s still a live screen.' },
  { path: '/building-sites/redirects/migration-patterns', title: 'Migration patterns', heading: 'Moved a site into Aglyn', anchor: '#moved-a-site-into-aglyn', text: 'Recreate your highest-traffic old URLs as redirects to their new Aglyn screens. Use the hit metrics to spot old URLs you missed — if a rule is getting traffic, people still rely on it.' },
  { path: '/building-sites/redirects/migration-patterns', title: 'Migration patterns', heading: 'Avoiding loops', anchor: '#avoiding-loops', text: 'The chain-loop check blocks redirects that would send visitors in circles (A→B→A). If a save is rejected, look for an existing rule that already redirects your destination.' },
  { path: '/building-sites/redirects/migration-patterns', title: 'Migration patterns', heading: 'Related', anchor: '#related', text: '- Create a redirect - Screens & layouts' },
  { path: '/building-sites/redirects/overview', title: 'Redirects', heading: '', anchor: '', text: '# Redirects The redirect manager sends old or alternate URLs to the right place — essential when you rename screens or migrate a site. :::info Plan availability Paid. The redirect manager is a paid feature.' },
  { path: '/building-sites/redirects/overview', title: 'Redirects', heading: 'Manage redirects', anchor: '#manage-redirects', text: '- Create, edit, and delete redirect rules from the redirect manager page. - Rules are validated on save, with chain-loop and screen-collision checks so a redirect can\'t send visitors in circles or shadow a real screen. - The published site enforces redirect rules during route resolution.' },
  { path: '/building-sites/redirects/overview', title: 'Redirects', heading: 'Metrics', anchor: '#metrics', text: 'Each rule tracks hit metrics (sampled), so you can see which redirects are actually used and prune the ones that aren\'t.' },
  { path: '/building-sites/redirects/overview', title: 'Redirects', heading: 'Match modes (v2)', anchor: '#match-modes-v2', text: 'Rules match one of three ways: - Exact path — the original mode; /old-page only. - Path prefix — /blog catches /blog and everything under it (/blog/post-1), but not /blogging. - Regular expression — anchored to the whole path, with capture groups substituted into the destination: pattern /product/(\\d+) and destination /products/item-$1 sends /product/42 to /products/item-42. Invalid patterns are rejected at save and can never take the site down. When several rules match, the lowest priority number fires first. Use the inline tester at the bottom of the redirects card to paste a path and see exactly which rule (if any) catches it — it runs the same matcher the live site uses. :::tip How-tos - Create a redirect - Migration patterns' },
  { path: '/building-sites/redirects/overview', title: 'Redirects', heading: 'Related', anchor: '#related', text: '- Screens & layouts - Site protection & error pages' },
  { path: '/building-sites/screens-and-layouts/overview', title: 'Screens & Layouts', heading: '', anchor: '', text: '# Screens & Layouts Screens are your pages; layouts are the shared frames they render inside. Together they define your site\'s structure, URLs, and reusable chrome. The screen hierarchy maps directly to your URL paths: :::info Plan availability Free for core screens and layouts. Higher tiers raise caps on screens, versions, and reusable components.' },
  { path: '/building-sites/screens-and-layouts/overview', title: 'Screens & Layouts', heading: 'What counts against your screen allowance', anchor: '#what-counts-against-your-screen-allowance', text: 'Your plan\'s screen limit counts the screens that are pages of your site — the ones a visitor can reach at an address of their own. Some screens you design are not pages, and those don\'t count: | Screen | Counts? | Why | | --- | --- | --- | | A page you publish at a slug | Yes | It has a URL of its own. | | A collection\'s list template | Yes | /{collection} renders that exact screen. | | A collection\'s entry template | No | One screen composes every entry; it has no address of its own. | | An error screen you\'ve assigned | No | It renders on addresses that matched nothing. | | An email you design | No | It\'s sent, never served at a URL. | | A screen you\'ve deleted | No | Deleting frees the slot straight away. | The rule behind the table is one question: does the screen occupy a URL of its own? So an error screen that is also still published at its own address — say a 404 screen you published at /404 while designing it — is a page, and it counts until you remove that address. The Error pages card tells you when that\'s the case and offers the one-click Remove address; the screen carries on rendering for its status code afterwards.' },
  { path: '/building-sites/screens-and-layouts/overview', title: 'Screens & Layouts', heading: 'Screens & routing', anchor: '#screens--routing', text: '- Each screen has a title and a URL slug. Aglyn normalizes slugs and keeps a site routing map. - Screens form a hierarchy: pick a parent and the child inherits a nested path (/services/pricing). Changing a slug or parent cascades safe rewrites across the map, with cycle guards so you can\'t create a loop. - Reorder the hierarchy with drag-and-drop in the screens list. - The screens list shows each screen\'s Published date, and the screen\'s detail page shows Date published. Both stay empty until the screen goes live, and clear again if you unpublish it (including a scheduled unpublish) — so the column tells you what\'s live, not what exists.' },
  { path: '/building-sites/screens-and-layouts/overview', title: 'Screens & Layouts', heading: 'Layouts', anchor: '#layouts', text: 'A layout is a shared frame (header, nav, footer) with a slot where screen content renders. Bind a screen to a layout in the Besigner and the layout chrome wraps the screen both in the editor and on the published site. Layouts have their own versions and admin converters, just like screens. ### Nested layouts A layout can render inside another layout. Set Renders inside on a layout\'s detail page and its chrome is wrapped by the outer layout\'s, exactly as a screen is wrapped by its own — so site-wide furniture can live in one place while a section keeps a more specific frame around it. A screen inherits the whole chain: bind it to the inner layout and it renders inside that, which renders inside the outer one, up to five layouts deep. A layout can never sit inside itself, or inside a layout already nested within it — that would be a loop with no outermost frame to render. The picker only offers layouts that are legal choices, so you cannot select one by mistake. ### Used by A layout\'s detail page has a Used by card listing everything that renders inside it, so you can see what a change or a deletion would reach: - screens bound to it, published or not, and - layouts nested inside it — deleting the outer one unwraps every screen underneath those too. A layout used by neither is genuinely unused.' },
  { path: '/building-sites/screens-and-layouts/overview', title: 'Screens & Layouts', heading: 'Reusable components', anchor: '#reusable-components', text: 'Promote a subtree into a reusable component and insert instances anywhere. Instances graft the source at render time, so one edit updates them all. Manage (rename / demote / delete) reusable components from the site dashboard.' },
  { path: '/building-sites/screens-and-layouts/overview', title: 'Screens & Layouts', heading: 'Versions & scheduled publishing', anchor: '#versions--scheduled-publishing', text: 'Screens, layouts, and reusable components all keep versions — open the version name in the besigner\'s app bar to see the Versions dialog, with each version\'s created/updated times and a Published chip on the live one. - New version saves a named snapshot of the current saved document (prefilled "Copy of …" — rename it to something meaningful). - Open switches the besigner to that version. Viewing an old version never publishes it. - Publish on any row makes that version the live one — which is also how you roll back: publishing an older version moves the live pointer, destroys nothing, and is symmetrical, so rolling forward again is the same click. - Schedule publishes a version automatically at a chosen future time; the row then shows a "Publishes …" chip you can clear to cancel. - Delete versions you no longer need — the published version can\'t be deleted, and the one you have open must be closed first. Plan gating, enforced where you click: - Creating versions requires Pro or above — on a lower tier the editor answers "Versioning requires a Pro plan — see Billing to upgrade" instead of opening the name dialog. - Scheduled publishing requires Business or above. - A version is snapshotted from the saved document, so the editor asks you to save the canvas first rather than silently capturing (or losing) unsaved edits. - If a scheduled publish comes due on a plan that no longer includes scheduling — after a downgrade, say — it is skipped and shown as skipped on the screen\'s page, never silently dropped, so you can dismiss it or upgrade and reschedule.' },
  { path: '/building-sites/screens-and-layouts/overview', title: 'Screens & Layouts', heading: 'Error & maintenance screens', anchor: '#error--maintenance-screens', text: 'You can design custom 404 / 401 / 403 / 503 screens and turn on maintenance mode. See Site protection & error pages.' },
  { path: '/building-sites/screens-and-layouts/overview', title: 'Screens & Layouts', heading: 'Related', anchor: '#related', text: '- The Besigner - Bindings & variables - SEO toolkit' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: '', anchor: '', text: '# SEO Toolkit The SEO toolkit helps your pages rank and share well. Set metadata per screen, and Aglyn emits the right tags, sitemap, and structured data automatically. :::info Plan availability Free for core SEO fields; richer structured data ships for published sites.' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Per-screen SEO', anchor: '#per-screen-seo', text: 'Every screen\'s detail page has an SEO card with three fields: - Search title — up to 60 characters, published exactly as you type it. - Search description — up to 155 characters, the meta description. - Social image — the picture shown when the page is shared. Press Choose image to pick one from your media library (or the organization\'s shared library); Clear puts the site default back. Fill them in and press Save SEO — it saves independently of the canvas, so you can update metadata without touching the design. The published site emits these into the page head, deduping descriptions so you never get conflicting tags. The social image is a media pick, not a URL you type. That is deliberate: a picked asset is stored by identity, so moving it into a folder or replacing it with a new version keeps every card that references it working. Anything you leave blank falls back sensibly: the description falls back to the screen\'s own description and then the site\'s, and the social image to the site-wide one. ### How a page title is built A search title you write is the whole title — nothing is appended to it. That is what lets you keep every page inside the 60 characters a search result shows, and say the brand once rather than twice. A page with no search title of its own is titled from its name — the screen\'s display name, a blog post\'s headline, a collection\'s name — joined to the site Title with your Separator: | Page | Rendered title | | --- | --- | | Search title About Aglyn — one platform for the open web | About Aglyn — one platform for the open web | | Screen named Contact, no search title | Contact – Acme Widgets | | Neither | Acme Widgets | Your brand still travels with every share regardless: the site title is published as og:sitename on every page. ### Site-wide defa' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Search engine visibility', anchor: '#search-engine-visibility', text: 'You decide what search engines are allowed to index, at two levels. ### The whole site Setup → SEO → Search engines has a Discourage search engines from indexing this site switch. Turn it on while you stage a launch — the site stays live and anyone with a link can still reach it, but: - robots.txt refuses every crawler (Disallow: /) and names no sitemap - sitemap.xml is served empty (valid but with no URLs, so search consoles read "nothing here" rather than an error they retry) - every page carries a noindex robots meta tag — links are still followed, but the page is not listed While it is on, a warning banner follows you through the console on every page of that site. That is deliberate — a site missing from Google weeks after launch is almost always this switch, left on and forgotten. Turning it off restores everything within about a minute. Search engines take longer: re-indexing a site is their schedule, not yours, so allow days. :::caution robots.txt and noindex answer different questions. Disallow asks a crawler not to fetch a page; noindex asks it not to list one. Aglyn sends both, because a page linked from somewhere else can be listed without ever being fetched — and a crawler that obeys the disallow never sees the noindex that would have stopped it. ### A single page Use the page\'s own Visibility, in Page Access on the screen\'s detail page. Only Public pages are offered to search engines. Unlisted, Password protected and Members only pages are all kept out of search results and out of the sitemap, while staying reachable to whoever has the link or the credentials. Use the site-wide switch while nothing is ready, and per-screen Unlisted once you\'re launching page by page — the switch also covers pages you haven\'t created yet, which per-screen visibility cannot.' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Sitemap & robots', anchor: '#sitemap--robots', text: 'Aglyn generates sitemap.xml and robots.txt for your site automatically, so search engines can crawl your site correctly. The sitemap always names your site by its real address (your custom domain when you have one), and includes: - every published screen whose visibility is Public — template screens (blog list/ entry templates, product page templates) are excluded, since their real URLs are the entries and products they render; - your product and catalog collection URLs, once a product-page or collection-page template is set; - your content collections — each collection\'s list URL and its published entries. A scheduled entry joins the sitemap once its publish time passes. The sitemap is cached for a few minutes, and every publish refreshes it immediately — so a freshly published page never waits on the cache.' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Social cards', anchor: '#social-cards', text: 'Every published page emits Open Graph and Twitter metadata: title, description, canonical URL, site name, and — once an image is set — og:image with its og:image:width and og:image:height. Which image a page uses is decided in this order: 1. the entry\'s cover image, for a blog or collection entry; 2. the screen\'s own social image, from its SEO panel; 3. the site default, from Setup → SEO; 4. nothing. The first three make the page share as a large card (twitter:card: summarylargeimage). Only the fourth falls back to the small image-less summary card, which is why setting a site default is worth doing once. Size. 1200×630 is the size every network crops well. Aglyn reads the real dimensions off the media record and publishes them, so previews reserve the right shape before the image finishes loading — it does not assume a size, so a different ratio is described honestly rather than stretched. Addresses. Card images are always published as absolute URLs on your site\'s own domain (your custom domain when you have one). A crawler fetches the image without a page to resolve a relative path against, so a relative address is a blank card.' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Structured data', anchor: '#structured-data', text: 'Published sites emit JSON-LD for blogs, the site, and breadcrumbs, giving search engines rich context about your content.' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Analytics integration', anchor: '#analytics-integration', text: 'Add your Google Analytics ID to track traffic alongside Aglyn\'s built-in analytics.' },
  { path: '/building-sites/seo/overview', title: 'SEO Toolkit', heading: 'Related', anchor: '#related', text: '- Analytics - Content collections & blog' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: '', anchor: '', text: '# Design custom error screens When something goes wrong, visitors should still see your site. Design custom error screens for each status.' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: 'The error screens', anchor: '#the-error-screens', text: '| Status | Picker label | When it shows | | --- | --- | --- | | 404 | 404 · Not found | The URL doesn\'t match any screen. | | 401 | 401 · Members only | A members-only screen, requested by a signed-out visitor. | | 403 | 403 · Forbidden | Reserved for future access rules — nothing serves it yet. | | 503 | 503 · Maintenance | Shown on every page while maintenance mode is on. |' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: 'Design one', anchor: '#design-one', text: '1. Create a screen for the status, in Screens, and design it in the Besigner like any other screen — add your header/layout, a helpful message, and a link home. 2. Assign it. Go to Setup and scroll to the Error pages card. Each status has its own picker — 404 · Not found, 401 · Members only, 403 · Forbidden, 503 · Maintenance — listing every screen on the site. Choose your screen in the matching picker. Step 2 is the one that\'s easy to miss: designing a screen does not make it an error page on its own. Until it\'s picked in the Error pages card, the status still renders Aglyn\'s Built-in default, which is what every picker is set to until you change it. Assigned error screens are automatically kept out of search results, so a 404 page can\'t itself turn up in a search.' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: 'Error screens are free', anchor: '#error-screens-are-free', text: 'An assigned error screen doesn\'t count against your plan\'s screen allowance. Nothing about it is a page of your site: it renders on addresses that matched nothing, so it has no URL of its own — the same reason a collection\'s entry template doesn\'t count. See what counts against your screen allowance. There\'s one thing to know, and it\'s the reason you don\'t need to publish the screen at all: :::tip Don\'t give it an address An error screen that is also published at its own address — a 404 screen you published at /404 so you could preview it, say — is a page, so it counts like any other page until you remove that address. If you\'ve already published one, the Error pages card says so and offers Remove address. Removing it frees the allowance slot and the screen carries on rendering for its status code, which is the only place it was ever meant to appear.' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: 'Tips', anchor: '#tips', text: '- Put a search box or navigation on your 404 so visitors can recover. - Keep the 503 lightweight — it shows when the site is under maintenance.' },
  { path: '/building-sites/site-protection/error-screens', title: 'Design custom error screens', heading: 'Related', anchor: '#related', text: '- Maintenance mode - Password-protect a screen' },
  { path: '/building-sites/site-protection/maintenance-mode', title: 'Maintenance mode', heading: '', anchor: '', text: '# Maintenance mode Need to pause your live site while you make changes? Maintenance mode serves your designed 503 screen to visitors until you switch it back.' },
  { path: '/building-sites/site-protection/maintenance-mode', title: 'Maintenance mode', heading: 'Turn it on', anchor: '#turn-it-on', text: '1. Open Setup for the site and scroll to the Error pages card — the same card that assigns your error screens. It sits below the site details, logo and business details. 2. Switch on Maintenance mode — show the 503 screen on every page. It confirms with "Maintenance mode on — visitors see the 503 screen". 3. Visitors now see your 503 error screen on every path. 4. When you\'re done, switch it back off and the site returns. If you haven\'t assigned a 503 · Maintenance screen, maintenance mode still works — but visitors get Aglyn\'s plain built-in notice ("This site is undergoing maintenance. Please check back shortly.") rather than anything on-brand. Design and assign the 503 first.' },
  { path: '/building-sites/site-protection/maintenance-mode', title: 'Maintenance mode', heading: 'Tips', anchor: '#tips', text: '- Design the 503 screen first (see custom error screens) so maintenance mode shows something on-brand. - Tell visitors when you\'ll be back — a simple line on the 503 goes a long way.' },
  { path: '/building-sites/site-protection/maintenance-mode', title: 'Maintenance mode', heading: 'Related', anchor: '#related', text: '- Design custom error screens' },
  { path: '/building-sites/site-protection/overview', title: 'Site Protection & Error Pages', heading: '', anchor: '', text: '# Site Protection & Error Pages Control who can see your pages and what visitors see when something\'s not available. :::info Plan availability Included on every plan. Per-screen visibility, page passwords, custom error screens and maintenance mode are not tier-gated.' },
  { path: '/building-sites/site-protection/overview', title: 'Site Protection & Error Pages', heading: 'Where these controls live', anchor: '#where-these-controls-live', text: 'The three features on this page are set in two different places, and neither is the screens list: | What you want | Where it is | | --- | --- | | A screen\'s visibility (public, unlisted, password, members-only) and its page password | The Page Access card on that screen\'s own page | | Error screens for 404 / 401 / 403 / 503 | The Error pages card in Setup | | Maintenance mode | The same Error pages card in Setup |' },
  { path: '/building-sites/site-protection/overview', title: 'Site Protection & Error Pages', heading: 'Per-screen passwords', anchor: '#per-screen-passwords', text: 'Protect individual screens with a password, so only people with the code can view them. You can also set a custom not-found screen for missing pages.' },
  { path: '/building-sites/site-protection/overview', title: 'Site Protection & Error Pages', heading: 'Custom error screens', anchor: '#custom-error-screens', text: 'Design your own 404 / 401 / 403 / 503 screens in the Besigner, so error pages match your brand instead of showing a generic message.' },
  { path: '/building-sites/site-protection/overview', title: 'Site Protection & Error Pages', heading: 'Maintenance mode', anchor: '#maintenance-mode', text: 'Flip your site into maintenance mode to show a designed 503 while you work, then switch it back when you\'re ready. :::tip How-tos - Password-protect a screen - Design custom error screens - Maintenance mode' },
  { path: '/building-sites/site-protection/overview', title: 'Site Protection & Error Pages', heading: 'Related', anchor: '#related', text: '- Screens & layouts - Redirects' },
  { path: '/building-sites/site-protection/password-a-screen', title: 'Password-protect a screen', heading: '', anchor: '', text: '# Password-protect a screen Lock a single screen behind a password — useful for drafts, client previews, or gated content, without setting up full membership.' },
  { path: '/building-sites/site-protection/password-a-screen', title: 'Password-protect a screen', heading: 'Steps', anchor: '#steps', text: '1. Open Screens and click the screen you want to protect. The screens list has no visibility column — the control is on the screen\'s own page. 2. Find the Page Access card and set Visibility to Password protected. 3. A Page password field appears. Type the password and click Save. Once one is set, the field reads "A password is set — save a new one to change it." 4. Publish. Visitors are prompted for the password before they can view the screen. The other visibility options on the same card are Public (anyone with the link, listed in navigation and offered to search engines), Unlisted (reachable by URL only, kept out of search results and the sitemap), and Members only. Password-protected and unlisted screens are both kept out of search results. Password attempts are limited to 10 per minute per screen, per visitor address, so the password can\'t be guessed by brute force. Someone who trips it is asked to wait a moment and try again. The limit counts per address, so a shared office connection tripping it won\'t lock out anyone else — but if a whole team is unlocking the same screen at once, expect the occasional retry prompt.' },
  { path: '/building-sites/site-protection/password-a-screen', title: 'Password-protect a screen', heading: 'Password vs. members-only', anchor: '#password-vs-members-only', text: '| Password | Members-only | | --- | --- | | One shared secret | Individual accounts | | No sign-up needed | Visitors sign in / sign up | | Best for one-off gating | Best for ongoing member areas | For account-based access, use a members-only area instead.' },
  { path: '/building-sites/site-protection/password-a-screen', title: 'Password-protect a screen', heading: 'Related', anchor: '#related', text: '- Custom error screens - Members-only areas' },
  { path: '/building-sites/site-search/add-search', title: 'Add search to your site', heading: '', anchor: '', text: '# Add search to your site Adding search is a matter of placing one element. The search page and matcher are built in. :::info Plan availability Included on every plan.' },
  { path: '/building-sites/site-search/add-search', title: 'Add search to your site', heading: 'Steps', anchor: '#steps', text: '1. In the Besigner, open the elements drawer and add the Search Box (under Forms) to a screen — or to your shared layout so it appears site-wide. 2. Optionally set the box\'s Placeholder text in the Attributes panel. 3. Publish. Submitting the box sends visitors to your site\'s /search page with their query. That\'s the whole setup — there\'s no search setting to switch on and no index to build.' },
  { path: '/building-sites/site-search/add-search', title: 'Add search to your site', heading: 'Tips', anchor: '#tips', text: '- Put the Search Box in your header layout so it\'s reachable from every page. - Search covers dataset records and blog entries, so well-structured content and clear titles make results more useful. - Dataset records only surface when a published screen repeats over that dataset — build a listing screen for anything you want to be findable.' },
  { path: '/building-sites/site-search/add-search', title: 'Add search to your site', heading: 'Related', anchor: '#related', text: '- Site search overview - Datasets & dynamic content' },
  { path: '/building-sites/site-search/overview', title: 'Site Search', heading: '', anchor: '', text: '# Site Search Give visitors a Search Box to find content across your site. Aglyn ships a built-in search page — there\'s nothing to configure, enable, or index. :::info Plan availability Included on every plan, free tiers too.' },
  { path: '/building-sites/site-search/overview', title: 'Site Search', heading: 'How it works', anchor: '#how-it-works', text: 'The Search Box element is a simple form: a visitor types a query and submits it to your site\'s built-in /search page, which renders the matching results. There\'s no JavaScript and no external search service — the page reads your published content directly when the visitor searches.' },
  { path: '/building-sites/site-search/overview', title: 'Site Search', heading: 'What it searches', anchor: '#what-it-searches', text: 'A search matches the query as a case-insensitive substring across three kinds of content: - Screens — the screen\'s name, description, and SEO title and description. - Blog & collection entries — published entries\' title, excerpt, and body (see collections). - Dataset records — a record\'s dataset values. A record only appears in results when a published screen repeats over that dataset, so the result can link to a real page. Results are listed in that order (screens, then entries, then records), up to 50 matches. There\'s no relevance ranking — matching is a straight substring test — so clear titles and descriptions make results more useful. The /search results page is excluded from search engines, and search is a reserved screen slug.' },
  { path: '/building-sites/site-search/overview', title: 'Site Search', heading: 'Configure it', anchor: '#configure-it', text: 'The Search Box exposes one setting — its Placeholder text. There are no scope, result-limit, or styling options; the box inherits your site theme. :::tip How-tos - Add search to your site' },
  { path: '/building-sites/site-search/overview', title: 'Site Search', heading: 'Related', anchor: '#related', text: '- Datasets & dynamic content - SEO toolkit' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: '', anchor: '', text: '# Build a blog Aglyn\'s blog is built on collections — a collection holds your entries, and its pages are first-class designed pages: the list at /{collection} and each entry at /{collection}/{entry} render through your site\'s theme and shared layout, and can be fully designed in the besigner via template screens. :::info Plan availability Free to start; content features scale with your tier.' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: '1. Create a collection', anchor: '#1-create-a-collection', text: 'In Content, create a collection for your posts. Manage entries from the console. ### Delete a collection Delete collection sits in the Collections & Entries toolbar, beside Categories and New entry, and acts on the collection currently picked in the Collection dropdown. It is a site admin action: if your role on this site is editor or viewer the button is not there at all, and an org role on its own does not grant it — the check reads your role on this site. Ask a site admin, or have one raise your role in Members. Aglyn refuses the delete while anything still depends on the collection, and the dialog tells you which of these it is before you can type anything: - A template screen still points at it. The message names the screen and which picker holds it — "Blog" is still the source for "Blog index" (list template). Set that collection\'s List template screen or Entry template screen back to the built-in option first. Deleting it while a published page renders from it would leave that page with nothing to draw. - It still has entries. The message gives the count — "Blog" still has 12 entries. Delete them from the entries table first, one at a time; deleting a collection never removes published entries for you. Once nothing depends on it, type the collection\'s display name exactly — the name, not the slug, and capitalisation counts — and confirm. Deleting removes the collection, its category list, and its template pointers. Your screens are not deleted (they keep their design and simply stop being template screens) and nothing in the media library is touched. The /{collection} and /{collection}/{entry} routes stop resolving on the live site within about a minute; there is no publish step. :::warning No undo There is no trash and no restore. A deleted collection comes back' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: '2. Write entries', anchor: '#2-write-entries', text: 'Add rich blog entries with images, a live preview, and scheduling so posts publish at the right time. Each entry carries, besides the title, excerpt, cover image, and markdown body: - Category — a single bucket (e.g. Guides) used for filtering and related posts, picked from the collection\'s category list (see below), never typed free-form. - Tags — comma-separated labels (e.g. nextjs, seo). - Author — the entry\'s byline; falls back to the site name when blank. - SEO title / SEO description — search & social overrides; they fall back to the title and excerpt when blank. ### Scheduling Each entry row has a Schedule button. Pick a Publish at time (the past is refused) and confirm — the entry\'s status chip reads scheduled with the local time, and "the entry goes live once the time passes (applied on the next site refresh)", exactly as the dialog says: no manual step, and its status flips to published on its own. A scheduled entry joins the sitemap and RSS feed at the same moment. Publish/Unpublish on the row toggle an entry immediately, and View opens the live URL once it\'s published. ### Categories Categories are managed per collection — open Categories next to the template pickers (or Manage categories… inside the entry editor) to add, rename, or delete them. Entries reference a category by a stable id, so renaming a category updates every post instantly without touching a single entry — the display name is resolved at render time wherever it appears (entry pages, meta lines, related posts, RSS, JSON-LD). Deleting a category leaves its entries uncategorized until they are reassigned. A collection holds up to 50 categories. Posts written before category lookup existed keep rendering their old free-typed category; the entry editor flags them so you can migrate each post to ' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: '3. Design the pages with template screens', anchor: '#3-design-the-pages-with-template-screens', text: 'Each collection has two template pickers in Content: - List template screen — renders /{collection}. Drop the Collection Entries block on it: its children repeat once per published entry, with {{entry.}} tokens substituted per entry. The default card ships title, date, excerpt, and a Read more link, so dropping it in works instantly. - Entry template screen — renders /{collection}/{entry}. Use {{entry.}} bindings and the Entry Body block, which renders the entry\'s markdown as themed headings, paragraphs, lists, links, and images. Template screens go through the normal published pipeline — site theme, shared layout, reusable components, variables — exactly like any other screen (the same mechanism as commerce product/collection templates). ### Blog blocks Besides Collection Entries and Entry Body, three entry-page blocks are available in the block library: - Entry Meta — an author · date · category line plus tag chips, with an optional round avatar in front of it. On an entry template it fills itself in from the entry being rendered, so drop it on and it works; each part can be hidden with its Show switch. Typing into Author / Date / Category / Tags overrides what it would have shown — including the {{entry.author}} / {{entry.date}} / {{entry.category}} / {{entry.tags}} bindings, which still work and are still what the block\'s preset seeds. Date format picks how the published date reads — Site default (8/9/2026), Month and year (Aug 2026), Short date, Long date or ISO. It applies to the date the block fills in for itself; a date you typed in by hand is left exactly as typed. Avatar takes any image from the media library (usually your brand mark) and renders it 36px and round; blank shows no avatar. The avatar is chosen on the block, not per author — entries carry an auth' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: '4. Publish & syndicate', anchor: '#4-publish--syndicate', text: 'Publish the collection. Blog pages join the site\'s sitemap automatically, and each entry\'s uses its SEO title/description (falling back to title/excerpt) and its cover image as the social card. Aglyn also generates an RSS feed per collection, at: e.g. https://acme.com/blog/rss.xml. This is the URL to link — it names no site, so it keeps working if you connect a custom domain later, and it is the one to put behind a "Subscribe" link. The same feed answers on the explicit form, if you need to point at another site\'s: host accepts your site\'s platform origin (acme.aglyn.app), your custom domain (acme.com), or the bare subdomain (acme), and collection is the collection\'s slug. Items carry the entry\'s title, link, publish date, excerpt, and its category and tags as feed categories, newest first. Link it from your own footer or share it with aggregators — feed readers don\'t discover it automatically yet.' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: 'Tips', anchor: '#tips', text: '- Schedule entries ahead of time and let Aglyn publish them for you. - Pair the blog with the SEO toolkit — entries emit JSON-LD for rich results.' },
  { path: '/building-sites/site-templates/build-a-blog', title: 'Build a blog', heading: 'Related', anchor: '#related', text: '- Save a template - Datasets & dynamic content - SEO toolkit' },
  { path: '/building-sites/site-templates/overview', title: 'Templates, Blocks & Content', heading: '', anchor: '', text: '# Templates, Blocks & Content Build faster by starting from something. Aglyn gives you site templates, a section & block library, and a blog with content collections. :::info Plan availability Free to use the starter gallery and block library. Some templates and content features scale with your tier.' },
  { path: '/building-sites/site-templates/overview', title: 'Templates, Blocks & Content', heading: 'Site templates & starter gallery', anchor: '#site-templates--starter-gallery', text: '- Spin up a new site from the starter template gallery, which instantiates published screens for you. Starters are copied into your site\'s own template library, so you can edit and version them like any other template. - Save a site as a template from Setup → Site template, which publishes it to the marketplace — see save & share a template. Browsing and installing marketplace templates happens in the Start from a template picker, opened by the Templates button on the Screens, Layouts and Components lists.' },
  { path: '/building-sites/site-templates/overview', title: 'Templates, Blocks & Content', heading: 'Section & block library', anchor: '#section--block-library', text: 'Drop in pre-built sections and blocks from the library instead of assembling every page from primitives — a fast way to build common layouts. The library is a first-class group in the Besigner: open INSERT → New Element (or the components drawer) and the Sections & Blocks category sits at the top of the list, ahead of the primitive element groups. Every entry inserts a ready-made subtree with sensible props — drop it in, then edit text and styles in place. The library ships these sections: | Block | What it inserts | | --- | --- | | Nav Bar | App bar + toolbar with brand text and three screen links, in page flow (switch its Position attribute to Sticky for a pinned header) | | Hero | Centered headline, tagline, and call-to-action button | | Feature Grid | Three selling-point columns that wrap on small screens | | Image + Text | Image beside a heading, paragraph, and link button | | Testimonials | Three customer quote cards | | Pricing Table | Three plan columns with features and plan buttons | | FAQ | Question-and-answer list with a heading | | Call to Action | Accent-colored band with a heading and button | | Contact Section | Heading plus a working name/email/message form | | Announcement Bar | Accent strip with a message and link | | Image Gallery | Three-across image row | | Footer | Semantic with brand, screen links, social icons, and copyright | Blocks are ordinary elements once inserted — nothing is locked. Screen links resolve against your site\'s screens (pick targets in the link\'s attributes), the contact form submits like any form, and social icons appear once you add profile URLs.' },
  { path: '/building-sites/site-templates/overview', title: 'Templates, Blocks & Content', heading: 'Content collections & blog', anchor: '#content-collections--blog', text: '- Create collections managed in the console. - Publish a blog with rich entries (images, preview, scheduling) and an RSS feed. - Use entry-template screens with {{entry.}} bindings to render each collection item. :::tip How-tos - Build a blog - Save & share a template' },
  { path: '/building-sites/site-templates/overview', title: 'Templates, Blocks & Content', heading: 'Related', anchor: '#related', text: '- The Besigner - Datasets & dynamic content - SEO toolkit' },
  { path: '/building-sites/site-templates/save-a-template', title: 'Save & share a template', heading: '', anchor: '', text: '# Save & share a template Turn a site you\'ve built into a template others can start from — or start your own site from the marketplace gallery. :::info Plan availability Free to use the starter gallery; sharing scales with your tier.' },
  { path: '/building-sites/site-templates/save-a-template', title: 'Save & share a template', heading: 'Start from a template', anchor: '#start-from-a-template', text: 'Open the starter template gallery and install a template. It lands in your templates library as one page template per page — publishing nothing until you choose which pages you want. Aglyn\'s own starter templates still create their pages straight away, since you pick those when a site is empty. ### Where to find it Templates sits next to the create button on three lists, and each one offers templates of its own kind: | List | What the picker offers | | --- | --- | | Screens | Page templates, plus Aglyn\'s starter sites and marketplace templates | | Layouts | Layout templates | | Components | Component templates | Starter sites and marketplace templates are whole-site page bundles, so they appear only on Screens — a layout or component picker would have nothing to do with them. Use the filter icon in the dialog\'s header to search by name, description or category.' },
  { path: '/building-sites/site-templates/save-a-template', title: 'Save & share a template', heading: 'Save your site as a template', anchor: '#save-your-site-as-a-template', text: 'Saving a whole site is not done from the screens list — it lives in Setup. 1. Open Setup for the site and find the Site template card, under the basic details. 2. Click Publish as template. 3. Fill in Template name, Description, Category (e.g. Portfolio, Restaurant) and Price (USD, 0 = free), then publish. This captures every published screen plus the theme, and publishes it to the marketplace — so it is a share, not a private snapshot. Re-publishing bumps the version. Add a preview image afterwards from Manage → Marketplace. ### Saving a single page instead To reuse one page rather than a whole site, use the ⋮ row menu on the Screens list and choose Save as template. Layouts and Components have the same row action. These save into your own templates library and are not published anywhere until you publish them separately.' },
  { path: '/building-sites/site-templates/save-a-template', title: 'Save & share a template', heading: 'Tips', anchor: '#tips', text: '- Templates are a fast way to reuse a proven layout across client sites. - Combine with the section & block library for page-level reuse without a whole template.' },
  { path: '/building-sites/site-templates/save-a-template', title: 'Save & share a template', heading: 'Related', anchor: '#related', text: '- Build a blog - Templates, blocks & content' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: '', anchor: '', text: '# Your templates library Templates are saved starting points. A template is inert: nothing in your library is on your live site until you deliberately use it. That is the whole point of the library — it means installing something from the marketplace can never publish pages to a site you are running. Find it at Templates in a site\'s navigation, alongside Screens, Layouts and Components — the three things a template can produce.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'The three kinds', anchor: '#the-three-kinds', text: '| Kind | What it holds | What you get from it | | --- | --- | --- | | Page | A screen\'s content | A new screen, unpublished | | Component | An element tree | A reusable component, or a drop onto a screen | | Layout | Page chrome — header, footer, navigation | A new shared layout |' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Installing from the marketplace', anchor: '#installing-from-the-marketplace', text: 'Installing a marketplace template adds it to your library and publishes nothing. A site template arrives as one page template per page it contains, so you choose which of them you actually want, and when. This is deliberate: browsing and installing should never be able to change a site that real people are looking at. If the template was designed around a particular theme, that theme travels with it rather than being applied to your site.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Saving something as a template', anchor: '#saving-something-as-a-template', text: 'Look for Save as template: - Screens list — saves the page\'s published content - Layouts list — saves the layout, including its content slot - Components list — saves the component definition A page template captures the published version of a screen. If a screen has never been published there is nothing to capture, and Aglyn will tell you to publish it first rather than saving an empty template that fails later. The original is never touched. Saving a template copies it.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Using a template', anchor: '#using-a-template', text: 'Use creates something new from the template — the template itself stays in your library, so you can use it as many times as you like. - A page template asks for a name and an address, then creates the page and publishes it. If the address is already taken, Aglyn adds a number rather than overwriting the page that\'s there. - Component and layout templates just create the component or layout; there is no address to pick. If a template defines placeholders, you\'ll be asked to fill them in first — the values are substituted into the content as it\'s created. A template might use {{who}} in its copy and ask you for "Who". Nothing you create is linked back to the template afterwards. Editing a page will never change the template, and updating a template will never change pages you already made.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Where a template came from', anchor: '#where-a-template-came-from', text: 'Every template shows a badge: - Saved here — you created it on this site - Marketplace — installed from a marketplace listing, with its version - Starter — one of Aglyn\'s first-party starter templates That badge is set by Aglyn, not by whoever made the template, so a listing cannot claim to be something it is not.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'First-party starters', anchor: '#first-party-starters', text: 'Aglyn\'s starter sites (Landing Page, Business, Portfolio, the two Shop starters) are ordinary templates in your library — not a separate, locked-down kind. Every site gets its own copy, so you can open a starter in the besigner, edit it, keep versions of it, and use it to create pages exactly like a template you saved yourself. They carry the Starter badge, and they don\'t count against your plan\'s template allowance. A multi-page starter arrives as one template per page (the Shop starters are five), and Start from a template still shows them grouped as one card that creates all of the pages at once. Your Templates list groups them the same way: one row per starter, labelled with its page count, and its actions act on all of those pages — Use creates every page, and Delete removes every page. Open the row to see the pages individually; each one is an ordinary template you can edit, use or delete on its own from there. Because your copy is yours, editing a starter is safe: Aglyn will not overwrite it later. Delete one you don\'t want and it stays deleted.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Templates are per-site', anchor: '#templates-are-per-site', text: 'A template lives on the site you saved it to. That keeps a template next to the screens, layouts and components it was built from. Marketplace plugins and add-ons work differently: those install once for the whole organization and apply to every site, and a site can override the organization\'s choice for itself.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Deleting', anchor: '#deleting', text: 'Deleting a template removes it from your library. Anything you already created from it is unaffected — a page made from a template is a normal page, with no ongoing link back to it.' },
  { path: '/building-sites/site-templates/templates-library', title: 'Your templates library', heading: 'Related', anchor: '#related', text: '- Save & share a template — publishing a whole site as a template for other organizations to install' },
  { path: '/building-sites/theme-builder/edit-your-theme', title: 'Edit your theme', heading: '', anchor: '', text: '# Edit your theme Your theme controls how the whole site looks — applied consistently across every screen and previewed live as you edit. :::info Plan availability Free.' },
  { path: '/building-sites/theme-builder/edit-your-theme', title: 'Edit your theme', heading: 'Open the editor', anchor: '#open-the-editor', text: 'Go to Setup → Theme editor. Changes render in a live preview so you see them immediately.' },
  { path: '/building-sites/theme-builder/edit-your-theme', title: 'Edit your theme', heading: 'Set colors and fonts', anchor: '#set-colors-and-fonts', text: '- Choose your palette and typography. - Fonts load through a Google Fonts URL builder. - Configure both light and dark schemes — published sites apply the visitor\'s system scheme automatically.' },
  { path: '/building-sites/theme-builder/edit-your-theme', title: 'Edit your theme', heading: 'It follows you into the Besigner', anchor: '#it-follows-you-into-the-besigner', text: 'The theme you set here is supplied to the Besigner canvas, so what you design previews under the real site theme in both light and dark. Your palette also powers the Besigner\'s color pickers: every color field offers your theme\'s colors as references first (Primary, Background, Surface, Text…), each swatch previewing its light and dark resolutions. Elements colored by reference re-color automatically when you adjust the theme — or when the visitor\'s scheme flips. See scheme-scoped colors.' },
  { path: '/building-sites/theme-builder/edit-your-theme', title: 'Edit your theme', heading: 'Tips', anchor: '#tips', text: '- Set both schemes — a site that only looks right in light mode breaks for dark-mode visitors. - Prefer theme color references over fixed hex values when styling elements; references adapt per scheme, fixed colors don\'t (though the Besigner can scope custom colors per scheme too). - The theme also styles screen previews and published pages, so there\'s one source of truth.' },
  { path: '/building-sites/theme-builder/edit-your-theme', title: 'Edit your theme', heading: 'Related', anchor: '#related', text: '- The Besigner - Screens & layouts' },
  { path: '/building-sites/theme-builder/overview', title: 'Theme Builder', heading: '', anchor: '', text: '# Theme Builder The theme builder controls how your whole site looks — colors, fonts, and light/dark schemes — applied consistently across every screen. :::info Plan availability Free. Theming is core to every site.' },
  { path: '/building-sites/theme-builder/overview', title: 'Theme Builder', heading: 'Edit your theme', anchor: '#edit-your-theme', text: '- Open the theme editor under Setup. - Set your palette and typography; changes render in a live preview. - Configure both light and dark schemes — published sites apply the visitor\'s scheme automatically. - Fonts load via a Google Fonts URL builder. The theme you set here is supplied to the Besigner canvas too, so previews match the live site. :::tip How-tos - Edit your theme' },
  { path: '/building-sites/theme-builder/overview', title: 'Theme Builder', heading: 'Related', anchor: '#related', text: '- The Besigner - Screens & layouts' },
  { path: '/commerce-and-bookings/bookings/overview', title: 'Bookings & Scheduling', heading: '', anchor: '', text: '# Bookings & Scheduling Bookings turn your site into a scheduling tool: define services, publish your availability, and let visitors book time — with optional payment and automatic reminders. :::info Plan availability Paid. Paid bookings use Stripe; reminder emails are included.' },
  { path: '/commerce-and-bookings/bookings/overview', title: 'Bookings & Scheduling', heading: 'Set up bookings', anchor: '#set-up-bookings', text: '1. Define services (what can be booked, duration, price). 2. Configure availability — the windows when slots are offered. 3. Add the booking widget to a screen as a canvas element.' },
  { path: '/commerce-and-bookings/bookings/overview', title: 'Bookings & Scheduling', heading: 'Taking bookings', anchor: '#taking-bookings', text: '- Visitors pick a slot through the booking widget; the booking API records it. - For paid services, Stripe collects payment and a slot hold prevents double-booking during checkout. - Reminder emails go out automatically ahead of the appointment.' },
  { path: '/commerce-and-bookings/bookings/overview', title: 'Bookings & Scheduling', heading: 'Manage', anchor: '#manage', text: 'Use the console bookings page to see and manage upcoming appointments.' },
  { path: '/commerce-and-bookings/bookings/overview', title: 'Bookings & Scheduling', heading: 'Related', anchor: '#related', text: '- Commerce - Events calendar - Email campaigns' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: '', anchor: '', text: '# Product catalog The catalog (AGL-276) is the foundation of Aglyn commerce: every storefront block, checkout, and order line points back at these documents.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Products, options, and variants', anchor: '#products-options-and-variants', text: 'A product is what you manage; a variant is what a customer actually buys. Products define up to 3 options (like Size or Color, each with up to 25 values), and the products hub expands them into a variants matrix — up to 100 variants per product, each with its own SKU, barcode, price, compare-at price, weight, image, and inventory count. - Types: physical (shippable), digital (delivered as downloads), or service. - Status: draft (invisible to visitors), active, or archived. - Pricing: a variant with a compare-at price above its price shows a sale badge on storefront blocks. - Inventory: leave blank for untracked, 0 means sold out — the same semantics the original product block used. Stock is not tracked on a digital or service subscription-only product: nothing decrements it, on the first charge or on any renewal, so the field is disabled there. A physical subscription tracks normally — every paid cycle decrements one unit per box shipped — and Both — buyer chooses keeps tracking on the one-time sales. Products created with the earlier single-price product block are lifted into this model automatically as a single default variant — nothing breaks and no migration step is needed.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Billing modes and subscriptions', anchor: '#billing-modes-and-subscriptions', text: 'Each product\'s Billing setting picks how buyers pay: - One-time purchase (default) — a normal order. - Monthly / Yearly subscription — buyers subscribe instead of buying once; the product page prices as $X/mo or $X/yr, the buy button reads Subscribe, and an optional free trial (in days) can precede the first charge. An active subscription is what members-only content checks. - Both — buyer chooses — the product page shows a one-time / subscribe toggle (same price either way, at the interval you pick) and defaults to one-time. The choice is validated server-side against the product: a one-time sale here is a plain order, while the subscribe choice creates a recurring subscription exactly like a subscription-only product. Selling subscriptions (including the subscribe side of Both) requires a plan with storefront subscriptions (Business and above). Subscription billing applies to the product page\'s direct checkout — cart checkouts always charge one-time. Whether a subscription moves stock follows the product\'s Type. A physical subscription decrements one unit per paid cycle — the first charge and every renewal each create an order on the Subscription channel and take the box off the shelf, so the stock field stays live and low-stock alerts apply. A digital or service subscription never moves stock, and the stock field is disabled there; any number already saved is kept and shown, but it does not cap subscribers and will not change on its own. A saved 0 still stops new subscribers, so clear it (Clear stock on the notice in the editor) if that is not what you want. On a Both product the stock field stays live, because the one-time sales do decrement it.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Categories and tags', anchor: '#categories-and-tags', text: 'Categories are hierarchical (each may have a parent) and slugged for URLs. Tags are free-form labels. Both drive storefront filtering and smart collections.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Collections', anchor: '#collections', text: 'Collections group products for landing pages and storefront blocks: - Manual collections are an ordered, hand-picked list. - Smart collections define rules — match by tag, category, price, name, or product type, with all or any semantics — and membership updates automatically as products change. Draft and archived products never appear.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Slugs', anchor: '#slugs', text: 'Products, categories, and collections each have a host-unique slug used in storefront URLs (/products/{slug}, /collections/{slug}). Slugs are lowercase letters, numbers, and dashes.' },
  { path: '/commerce-and-bookings/commerce/catalog', title: 'Product catalog', heading: 'Related', anchor: '#related', text: '- Commerce overview - SEO — products emit structured data and join the sitemap automatically.' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: '', anchor: '', text: '# Commerce Aglyn commerce sells from your own Stripe account: buyers pay you directly, and Aglyn collects a per-sale platform fee set by your plan (see Billing & plans — higher plans reduce fees to 0%). :::info Plan availability Paid. Starter sells up to 100 products (2% physical / 7% digital fee); Pro and Business raise limits and remove fees.' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Products hub', anchor: '#products-hub', text: 'The Products page is the catalog manager: - Products with up to 3 options and 100 variants each — per-variant SKU, barcode, price, compare-at (sale badge), weight, and stock. See Product catalog. - Categories & collections — a category tree plus manual and smart (rule-based) collections with a live match preview. - CSV import/export in the Shopify column dialect, with a dry-run report — switching from Shopify is a file upload. - Payments — Stripe Connect onboarding status and your plan\'s fee ladder.' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Inventory', anchor: '#inventory', text: '- Per-variant stock; blank = untracked, 0 = sold out. - Oversell policy per product: stop selling or allow backorders. - Low-stock alerts notify managers once per threshold crossing. - Adjustment history with reason codes (sale, restock, correction…). - Locations split stock across warehouses/storefronts (plan-capped); adjustments and POS sales bucket per location.' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Orders', anchor: '#orders', text: 'Every paid checkout becomes an order with a sequential number, line-item snapshots, totals, and a timeline: - Statuses: pending → paid → fulfilled (or partially) → delivered, with cancel/refund exits guarded by a status machine. - Fulfill with tracking, print packing slips, add internal notes. - Refunds (full or partial) go through Stripe and reverse the platform fee; site-admin only. - Chargebacks are shown apart from refunds. When a shopper disputes a charge with their bank, the order gets a Chargeback open badge and the list warns you with the date Stripe needs your evidence by — answer it in the Stripe dashboard, because an unanswered dispute is decided for the shopper. If the dispute is lost the money is reversed, the order reads Charged back rather than Refunded, and the buyer loses the downloads, membership and verified-purchase review a refund would have withdrawn. A dispute you win reverses nothing. Filter the list by Disputes to find either. - Draft orders: build an order in the console and send the buyer a payment link (Shopify parity). Requires an active plan with commerce — see the note below. ### If a dispute is lost, the money comes back out of your payout {#a-lost-dispute} Worth knowing before it happens, because it is money leaving an account you already received it into: - The sale was paid out to you at the time of the charge. When a dispute is lost, that payout is reversed — the amount is pulled back from your connected Stripe account, not absorbed by Aglyn. - The full sale amount comes back, not the amount after our commission. On a $100 sale you received $95 and Aglyn kept $5; a lost dispute pulls back the whole $100, because that is what the shopper\'s bank took. This is the same treatment Shopify, Etsy, eBay, PayPal and Square apply to a chargebac' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Shipping & taxes', anchor: '#shipping--taxes', text: '- Shipping zones own countries (\'\' = rest of world); rates are flat, free-over-subtotal, or subtotal/weight tiers; optional local pickup. - Taxes: manual per-region rates (state beats country, VAT-style inclusive pricing supported) or Stripe Tax automatic calculation; products can be tax-exempt. ### Destination coverage Checkout collects a shipping address for six countries — United States, Canada, United Kingdom, Australia, Germany and France — and charges the rate that destination resolves to. It will not charge a rate belonging to another zone, so the zones you save decide what checkout can do: - A destination no rate reaches is refused. The shopper is told the store does not ship there, rather than being posted a parcel you priced nothing for. The Coverage line under Shipping settings names those countries as you edit, and offers to add a rest-of-world zone. - Rates that differ by destination make checkout ask. The cart and product page reveal a "Ship to" selector before they can price one. A single zone, or a single rest-of-world zone, asks the shopper nothing. - No rates at all is a valid setup, not a gap: the store charges no shipping and refuses nobody. - Payment links price a parcel too. A draft order you invoice a customer for charges the same rates, collects the same address, and asks you the same "Ships to" question in the draft dialog when your rates differ by destination. - In-person sales charge no shipping. A register has no destination to price against — cash, card and room-folio sales all settle at the counter — so a POS sale is items and tax. Raise a draft order for anything you post. A zone that names a country hides the rest-of-world zone for it — so a "Europe" zone with no rates on it refuses Europe even when a zone exists. Cover a destination by p' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Dropshipping', anchor: '#dropshipping', text: 'Assign a supplier to a product and paid orders route automatically — by email and/or HMAC-signed webhook — with a token link the supplier uses to post tracking back, which fulfills the order. Pro plan and above.' },
  { path: '/commerce-and-bookings/commerce/overview', title: 'Commerce', heading: 'Related', anchor: '#related', text: '- Product catalog - Billing & plans - Bookings & scheduling' },
  { path: '/commerce-and-bookings/commerce/pos-and-reservations', title: 'POS & reservations', heading: '', anchor: '', text: '# POS & reservations :::info Plan availability POS requires Pro or above. The number of registers a site can run at once follows your plan — Pro 1, Business 2, Advanced 5 — plus any $89/mo register seats you\'ve assigned to that site. A seat is bought once for the workspace and then placed on one site, so buying one does not raise the limit everywhere; see Assigning register seats. Opening more browser tabs does not give you more registers; each sale runs through a register you\'ve created.' },
  { path: '/commerce-and-bookings/commerce/pos-and-reservations', title: 'POS & reservations', heading: 'Registers', anchor: '#registers', text: 'Create your registers under Commerce → Settings → POS registers — one per till or device that takes in-person payments. Give each a name (and, if you use inventory locations, the location it sells from). Every POS sale is tagged with its register so you can reconcile end-of-day takings per till. Your plan caps how many registers you can run; add more with the register add-on in Billing. If you downgrade below your register count, the extra registers (newest first) stop taking payments and show Over plan limit until you remove them or upgrade again — none are deleted.' },
  { path: '/commerce-and-bookings/commerce/pos-and-reservations', title: 'POS & reservations', heading: 'The register', anchor: '#the-register', text: 'Open /{site}/pos in the console for a touch-first register. Pick which register you\'re on at the top of the panel (skipped automatically when you have only one): - Product grid — tap to add; products with variants show quick chips. - Barcode scanners — any keyboard-wedge scanner works: it types the code into the search box and presses Enter, which adds the exact SKU/barcode match. No drivers or pairing needed. - Payments — cash (with change calculation), card via QR (the customer scans and pays on their phone; the sale completes automatically), or charge to room for checked-in reservation guests. Stripe Terminal readers can replace the QR step later without changing the flow. - Receipts print through the browser\'s print dialog — any receipt printer with a system print driver works. Set the paper size to your roll width once and the browser remembers it. POS sales create normal orders tagged pos, decrement the same inventory as your online store (per location if you use locations), and appear in the orders list under the channel filter. ### When something disconnects - If the QR payment page fails to load, cancel and retake the payment — pending card sales never decrement stock until paid. - Cash sales need no network round-trip beyond saving the order; if the console loses connection entirely, note sales on paper and enter them when back online (an offline queue is on the roadmap).' },
  { path: '/commerce-and-bookings/commerce/pos-and-reservations', title: 'POS & reservations', heading: 'Reservations', anchor: '#reservations', text: 'For stays (cabins, rooms, rentals): 1. Add resources on the Products page — nightly rate, weekend multiplier, minimum nights, deposit percent, and free-cancellation window. 2. Drop the Reservation widget on any screen in the besigner and point it at the resource id. Guests pick dates, see a live quote, and pay the deposit (or full amount) at checkout. 3. Manage stays from the Reservations card: check in, check out (with a folio summary if the guest charged store purchases to the room), walk-ins, no-shows, and cancellations. :::info Deposits need a plan with commerce Taking a reservation deposit is a sale, and it is checked against your plan at the moment a guest tries to pay — not just when you added the widget. On a plan without commerce the widget still renders but checkout answers "Reservations are not enabled". Enabling the plugin is your switch; including commerce is your plan\'s. See downgrading.' },
  { path: '/commerce-and-bookings/commerce/pos-and-reservations', title: 'POS & reservations', heading: 'Related', anchor: '#related', text: '- Commerce overview - Product catalog' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: '', anchor: '', text: '# Glossary & naming conventions Aglyn\'s vocabulary grew through a couple of migrations, so several words name the same thing at different layers. This page is the canonical map (codified in AGL-443). For definitions of every product term — screens, nodes, plugins, workflows, and the rest — see the Term reference; this page is specifically the ruling on the four contested words.' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: 'The hierarchy', anchor: '#the-hierarchy', text: '' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: 'Organization (org)', anchor: '#organization-org', text: 'The entity. One subscription, one members roster (owner / admin / editor / viewer), one isolation boundary in Firestore (orgs/{orgId}), one plugin switchboard (enabledPlugins), org-scoped shared data (datasets, contacts, media, installs). Every current API, type, and permission is org-named: AglynOrganization, resolveOrgPermissions, getOrgForHost, the console\'s /org/ section. Rule: new code that touches the entity says org.' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: 'Workspace', anchor: '#workspace', text: 'The same entity, in the user\'s language. "Your workspace" is what we call an organization in UI copy and user docs — Slack-style, including the {slug}.aglyn.com workspace subdomain. It intentionally never names a collection or a type. Rule: workspace appears in UI copy and docs only, never in code identifiers.' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: 'Tenant', anchor: '#tenant', text: 'Two meanings — this is the word to be careful with: 1. The published-site runtime (current, correct use): apps/tenant is the app that renders customers\' live sites, and the shared @aglyn/tenant- libraries serve that side of the platform. "Multi-tenant" in architecture prose uses this sense: the org is the tenancy boundary. 2. A historic alias for the org\'s billing doc (now removed): before the organizations migration, billing lived at tenants/{uid}. The collection is retired and, as of AGL-444, so are the alias identifiers — AglynTenant is now AglynOrgBilling, useCurrentTenant() is useCurrentOrg() (returning org), the plugin-page tenant prop is org, and the Tenant permission/entitlement types are Org. The persisted strings went in AGL-445, while the platform was still pre-launch: Stripe billing metadata is keyed orgId, host docs carry only orgId/memberRoles, and the users.{uid}.tenants map is gone. No tenant-spelled data remains to migrate. Rule: "tenant" means the site runtime, full stop. Code that means the entity says org and types it AglynOrgBilling.' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: 'Tenant vs. host — not the same thing', anchor: '#tenant-vs-host--not-the-same-thing', text: 'These are the two most-confused terms because both relate to published sites: - A host is one site: hosts/{hostId}, with its own domain or subdomain, screens, media, and member-role projection. An organization owns many hosts ("3 of 15 sites"). In UI copy a host is called a site. - The tenant app is the runtime that serves every host: one Next.js deployment that resolves the incoming hostname to a host doc (hostIndex), loads that host\'s org, and renders its published screens. So: an org (workspace) owns hosts (sites); the tenant app serves them. A request to bakery.example.com is resolved to a host, whose org decides plugins/entitlements, rendered by the tenant app.' },
  { path: '/concepts/glossary', title: 'Glossary & naming conventions', heading: 'Quick reference', anchor: '#quick-reference', text: '| Term | Layer | Names in code | Use for new work | | --- | --- | --- | --- | | Organization / org | Data model, APIs, permissions | orgs/{orgId}, AglynOrganization, resolveOrg | ✅ the entity | | Workspace | UX / docs | — (copy only) | ✅ user-facing copy | | Tenant (runtime) | Published-site side | apps/tenant, @aglyn/tenant- | ✅ that side of the platform | | Tenant (billing alias) | Removed (AGL-444/445) | none — identifiers and persisted strings are both gone | ❌ don\'t reintroduce | | Host / site | One published site | hosts/{hostId}, AglynHost | ✅ host in code, "site" in copy |' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: '', anchor: '', text: '# Term reference Every term you\'ll meet in Aglyn, defined in a sentence or three, with links to the page that covers it in depth. For the rules about which word to use where (org vs. workspace vs. tenant vs. host), see the Glossary & naming conventions — this page is the vocabulary, that page is the ruling. Jump to a group: Platform & accounts · Sites & content · The node tree · Besigner (the editor) · Plugins & marketplace · Data & logic · Automation & marketing · Commerce · Billing & plans Every term below is a heading, so the table of contents on the right lists them all alphabetically within each group.' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Platform & accounts', anchor: '#platform--accounts', text: '### Organization (org) The account entity: one subscription, one team roster, one plugin switchboard, one data-isolation boundary. Everything you own in Aglyn — sites, datasets, media, installs — belongs to an organization. In code and APIs this is always org. → Glossary, Teams & roles ### Workspace The same entity as an organization, in the product\'s user-facing language — "your workspace", including the {slug}.aglyn.com workspace URL. Workspace never names anything in code; it\'s the word the UI uses for your org. → Glossary ### Tenant The published-site runtime: the single deployment that takes any incoming domain, resolves it to one of your sites, and renders its published screens. "Tenant" always means this serving side of the platform — it is not another word for organization. → Glossary, Architecture & multi-tenancy ### Host One site, as the data model sees it: its subdomain or custom domain, its screens and layouts, its media, its member-role projection. An organization owns many hosts. In UI copy a host is called a site. → Glossary ### Site The user-facing word for a host — what you create, design, and publish. "3 of 15 sites" on your dashboard is counting hosts. → Create a site ### Console The builder application where you sign in and do everything: manage your workspace, design screens in the Besigner, configure plugins, view billing. → Console tour ### Staff console The internal, staff-only area of the console (organizations directory, release flags, plugin review queue, audit log). Invisible without the staff claim. → Staff console ### Member A person on an organization\'s roster, holding one of the built-in role tiers — admin, editor, or viewer — org-wide or scoped to specific sites. → Teams & roles ### Custom role An owner-defined named permission set that ' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Sites & content', anchor: '#sites--content', text: '### Screen One page of a site: a slug, publish state, and a designed node tree. Screens can nest (parent/child slugs) and can bind to a shared layout. → Screens & layouts ### Layout Shared site chrome — app bar, footer, navigation — designed once and rendered around every screen bound to it. → Screens & layouts ### Slug A screen\'s URL segment. Nested screens compose their ancestors\' slugs into the full path. → Screens & layouts ### Version An immutable snapshot of a screen\'s (or layout\'s) node tree. You edit a draft version; publishing points the live site at a version. Scheduled publishing flips the pointer at a set time. → Publish your first screen ### Redirect A rule that forwards one path to another on your published site — for migrations, renamed pages, or vanity URLs. → Redirects ### Error screens Designable screens served for 404/401/403/503 instead of a generic error page. → Error screens ### Maintenance mode A host-level switch that serves the designed 503 screen on every path while you work. → Maintenance mode ### Locale A language your site serves (e.g. en, es). Multilingual sites pick a default locale and can render a language switcher. → Multilingual ### Site template A snapshot of screens, layouts, and content that can be applied to a new site — yours to save and reuse, or installed from the marketplace. → Site templates ### Theme The site-wide design system — palette, typography, spacing, component styling — edited in the theme builder and applied to every screen. → Theme builder ### Custom domain Your own domain attached to a site in place of the default subdomain, with guided DNS verification. → Custom domains ### Subdomain The default address every site gets on the platform\'s serving domain, before (or alongside) a custom domain. → Custom domains' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'The node tree', anchor: '#the-node-tree', text: 'The rendering model shared by the editor and the published site. Every designed screen is a tree of nodes; the renderer walks it with a family of components named like the parts of a tree. ### Node The atom of a design: { $id, componentId, props, sx, nodes }. Each node names the registered component that renders it, carries its props and styling, and lists its child node ids. A screen version stores its whole design as a map of nodes. → Besigner overview ### Tree The node hierarchy of one screen or layout — what you see in the Besigner\'s hierarchy panel and what the renderer walks to produce the page. → Drag-and-drop hierarchy ### Tree root The renderer\'s entry point: takes the root node and mounts the walk, letting hosts (the editor, the published site) swap in their own trunk, stem, branch, or leaf implementations. ### Trunk The first hop of the walk — renders the root node through the current stem. The editor substitutes its own trunk to add design-time behavior without touching the production renderer. ### Stem The per-node resolver: looks up a node\'s componentId in the component registry and renders it, recursing into the node\'s children. ### Branch Renders a node\'s children in order — the fan-out step between a parent node and its child stems. ### Leaf The terminal wrapper that actually mounts a node\'s registered component with its resolved props. Each leaf tags its DOM with the node id, which is what the editor\'s selection and drag-and-drop hang on to. ### Component A registered, renderable building block (button, section, product card…) a node can reference by componentId. Component ids are persisted in screen documents, so they are never renamed. → Besigner overview ### Component bundle A named set of components a plugin registers together for the canvas — the ' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Besigner (the editor)', anchor: '#besigner-the-editor', text: '### Besigner Aglyn\'s visual designer — the editor where you build screens, layouts, and designed emails by composing the node tree on a live canvas. → Besigner overview ### Canvas The live design surface inside the Besigner: your screen rendering for real, with selection, drag-and-drop, and inline text editing layered on top. → Besigner overview ### Hierarchy panel The tree view of the current screen\'s nodes — select, reorder, and reparent from the structure instead of the canvas. → Drag-and-drop hierarchy ### Drawer The Besigner\'s component palette: registered components, presets, and installed marketplace components, ready to drag onto the canvas. → Besigner overview ### Binding A token in designed content that resolves to live data at render time — dataset fields, variables, page context. → Bindings' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Plugins & marketplace', anchor: '#plugins--marketplace', text: '### Plugin A self-contained feature package that extends the console, the Besigner canvas, the published site, or the server APIs — without touching core code. First-party features and marketplace submissions use the same system. → Plugins overview ### Add-on The user-facing word for optional capability on top of your plan — installed plugins and purchasable extras, managed from the Marketplace (Installed tab). → Plugins overview ### Surface The part of the product a plugin registers into: the console client, the site (canvas + published pages), or the server tiers. A plugin declares which surfaces it provides. → Plugin manifest ### Console extension Everything a plugin adds to the console shell — nav items and pages, dashboard cards, settings sections, widgets, providers. → Extension points ### Widget A plugin component rendered into a named shell zone (dashboard footer, org settings, listing detail…). → Injection zones ### Injection zone A named slot in the console shell that plugin widgets can target. The guaranteed zones are a typed catalog; custom zones are open strings. → Injection zones ### Plugin manifest The generated loader table mapping plugin ids to their import entry points per app — the only sanctioned place plugins are referenced by the apps. → Manifest & envs ### Enabled plugins The per-organization switchboard deciding which plugins load for a workspace. Enablement, plan entitlement, and release flags gate together. → Plugins overview ### Feature flag A plugin\'s plan-entitlement gate: the extension names the flag, and the shell only serves it when the org\'s plan (or overrides) grants it. → Billing & plans ### Release flag A staff-controlled rollout switch (off / staff / percentage / on) evaluated per workspace — how features ship dark and roll out gradu' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Data & logic', anchor: '#data--logic', text: '### Dataset A structured, org-scoped data collection with a typed schema — the backing store for dynamic content, forms, and commerce. → Datasets ### Record One row of a dataset. → Datasets ### Field One typed column of a dataset\'s schema. Plugins can register custom field types that ride on the built-in storage types. → Model builder ### Relation A link between datasets (reference fields), letting records point at records. → Relations ### Contact A person captured into your workspace\'s audience — from forms, commerce, or manual entry. → Contacts ### Segment A saved filter over contacts, used to target campaigns and automations. → Contacts ### Media library Per-site uploaded assets with folders, tags, CDN delivery, and generated variants. → Media ### Variable A named site-level value (text, number, toggle) referenced from bindings and logic — change it once, it updates everywhere it\'s used. → Bindings ### Function (fx) A site-level computed expression — inputs, conditions, and operations that produce a value bindings can consume. Edited from the Besigner\'s ƒx panel and the Logic page. → Bindings ### Form A designed input block on a published page whose submissions flow into the forms pipeline (and from there to contacts, workflows, and notifications). → Forms' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Automation & marketing', anchor: '#automation--marketing', text: '### Event Something that happened on a site or in the workspace — a form submission, an order, a booking — that automations and workflows can react to. → Workflows & actions ### Workflow A configured sequence of actions that runs when its trigger event fires, with run logs to audit each execution. → Build a workflow ### Action One step inside a workflow — send an email, call a webhook, update a record. → Actions builder ### Automation Client-side reactive behavior on the published site (show, hide, trigger on visitor activity), configured in the marketing tools and executed by the site runtime. → Marketing overlays ### Overlay Site-wide attention elements — the announcement bar (persistent top strip) and the popup (triggered by delay, scroll, or exit intent, with optional email capture). → Marketing overlays ### Experiment An A/B test on a screen: visitors are assigned variants and engagement is tracked so a winner can be promoted. → Marketing overlays ### Email campaign A one-off or automated email send to contacts or a segment, with delivery and engagement tracking. → Email campaigns ### Designed email An email document built in the Besigner — the same node tree, rendered to email-safe markup. → Designed emails ### Merge tag A personalization token in an email or overlay ("first name", "order total") resolved per recipient at send time. → Email campaigns' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Commerce', anchor: '#commerce', text: '### Commerce The commerce plugin family: catalog, storefront components, cart and checkout, orders, discounts, and analytics. → Commerce ### Product A sellable catalog item — physical, digital, or service — with variants, pricing, and inventory. → Catalog ### Order A completed purchase with its line items, payment state, and fulfillment history. → Commerce ### POS Point of sale — in-person checkout from the console against the same catalog and inventory. → POS & reservations ### Booking A scheduled appointment or reservation taken through the bookings plugin\'s services, availability, and slots. → Bookings' },
  { path: '/concepts/term-reference', title: 'Term reference', heading: 'Billing & plans', anchor: '#billing--plans', text: '### Plan The subscription tier an organization is on. Entitlements resolve from the plan at read time; workspaces without a plan run dark-launch (ungated). → Billing & plans ### Entitlement A capability or limit granted by the plan — feature switches and quotas — optionally overridden per organization by staff. → Billing & plans ### Quota A numeric entitlement (sites, datasets, storage) checked at the point of use, with warnings as you approach the limit. → Billing & plans ### Seat A team-member allowance. Plans include seats; addon seats can be purchased up to a per-plan maximum. → Teams & roles ### Metered usage Consumption billed monthly in arrears (storage, delivery) with a live estimate shown before it lands on an invoice. → Billing & plans' },
  { path: '/content-and-data/contacts/overview', title: 'Contacts CRM', heading: '', anchor: '', text: '# Contacts CRM The Contacts CRM is a single list of the people who interact with your site. Aglyn builds it automatically from everything they do, so you always have an up-to-date view of your audience. :::caution Rolling out The Contacts page in the console isn\'t available yet — it\'s a release-flagged feature being finished for Contacts CRM v1, so there\'s no Contacts tab in your workspace and nothing to switch on. Capture is already running, though. Contacts are ingested from forms, member sign-ups, orders and bookings today, and you can read them over the REST API in the meantime — nothing is lost while you wait. Audience-band overage is not billed while the page is unavailable.' },
  { path: '/content-and-data/contacts/overview', title: 'Contacts CRM', heading: 'Unified ingestion', anchor: '#unified-ingestion', text: 'Contacts are ingested from across your site: - Form submissions - Site members (sign-ups) - Orders from commerce - Bookings from scheduling Duplicate signals from the same person are unified into one contact. Every tier includes an audience band — a number of contacts. Only the Free tier\'s band is a hard limit; paid tiers never drop a record, and growth past the band meters as overage. That overage is not billed while the Contacts page is unavailable. See Billing & plans.' },
  { path: '/content-and-data/contacts/overview', title: 'Contacts CRM', heading: 'The contacts page', anchor: '#the-contacts-page', text: 'Once the page is switched on, it will let you: - Browse the list of contacts. - Open a profile drawer to see a contact\'s details and history. - Add tags and notes. - Export to CSV.' },
  { path: '/content-and-data/contacts/overview', title: 'Contacts CRM', heading: 'Segments', anchor: '#segments', text: 'Group contacts into segments — reusable audiences you can target directly in email campaigns.' },
  { path: '/content-and-data/contacts/overview', title: 'Contacts CRM', heading: 'Related', anchor: '#related', text: '- Email campaigns - Forms & lead capture' },
  { path: '/content-and-data/datasets/import-export', title: 'Import & export', heading: '', anchor: '', text: '# Import & export Datasets round-trip through CSV and JSON, so you can edit data in bulk elsewhere and bring it back. :::info Plan availability Starter and above (datasets need the data store).' },
  { path: '/content-and-data/datasets/import-export', title: 'Import & export', heading: 'Export', anchor: '#export', text: 'Export a dataset\'s records to CSV or JSON — useful for backups, bulk edits in a spreadsheet, or moving data into another tool.' },
  { path: '/content-and-data/datasets/import-export', title: 'Import & export', heading: 'Import', anchor: '#import', text: 'Import CSV or JSON back into a dataset. Imports are validated against the model on the way in, so malformed rows are caught rather than silently corrupting your data. ### Upsert on a key field Pick a "Match on field" in the import dialog to de-duplicate: rows whose key value (say, an email) matches an existing record update it in place instead of appending a duplicate, and repeated keys within the same file collapse to the last row. Only genuinely new rows count against your record limit.' },
  { path: '/content-and-data/datasets/import-export', title: 'Import & export', heading: 'Tips', anchor: '#tips', text: '- Export first to get the exact column shape, edit that file, then re-import. - Keep reference fields pointing at valid record ids so relations survive the round-trip.' },
  { path: '/content-and-data/datasets/import-export', title: 'Import & export', heading: 'Related', anchor: '#related', text: '- Build a data model - Relations' },
  { path: '/content-and-data/datasets/model-builder', title: 'Build a data model', heading: '', anchor: '', text: '# Build a data model A model is the shape of a dataset — its fields and their types. Records are validated against it, so your data stays clean. :::info Plan availability Starter and above. Free plans have no data store; add-ons raise the dataset cap.' },
  { path: '/content-and-data/datasets/model-builder', title: 'Build a data model', heading: 'Define the model', anchor: '#define-the-model', text: '1. In Data, create a dataset and open the schema dialog. 2. Add typed fields — text, number, date, reference, and more. 3. Save. The model is stored on the dataset, and records are validated against it on the way in. ### Display name vs reference ID Every field has two names: - Display name — the human label shown in the record editor, table headers, and anywhere the field appears. Rename it any time. - Reference ID — the stable key used in bindings ({{item.referenceid}}), form field mappings, and CSV import/export. When you create a field, the Reference ID auto-fills from the display name (for example, Roast preference → roastpreference). Edit it in the same dialog to set your own — handy when you want a short, code-friendly key that differs from the label. Once the field is created the ID is fixed: records, bindings, and forms all point at it, so it can\'t change without orphaning that data. Pick it deliberately, then rename the display name freely afterward.' },
  { path: '/content-and-data/datasets/model-builder', title: 'Build a data model', heading: 'Edit records', anchor: '#edit-records', text: 'Open the typed document editor to add and edit records. Each field renders the input for its type (a date picker for dates, a number field for numbers, and so on), which keeps data consistent.' },
  { path: '/content-and-data/datasets/model-builder', title: 'Build a data model', heading: 'Tips', anchor: '#tips', text: '- Model the data first, then bind it — a clean model makes repeatable components and bindings straightforward. - Give fields a description in the schema dialog — it appears as a hint in the record editor, as a tooltip on table headers, and under the field\'s name in the schema dialog itself. See naming & describing fields. - Use a reference field to link records; see relations.' },
  { path: '/content-and-data/datasets/model-builder', title: 'Build a data model', heading: 'Related', anchor: '#related', text: '- Relations - Import & export - Datasets overview' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: '', anchor: '', text: '# Datasets & Dynamic Content Datasets are your structured content: a typed model plus the records that fill it. Screens read from datasets to render dynamic, repeatable content, and forms write new records back in. Datasets belong to your organization, not to a single site — every site in the organization shares the same collections. Manage them from the organization Data page (next to Media in the organization tabs), or from any site\'s Data page; both edit the same data. Dataset limits, storage, and add-ons are billed at the organization level. :::info Plan availability Starter and above. Free plans have no data store; higher tiers raise the dataset and record caps, and extra-dataset add-ons are available.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Model builder', anchor: '#model-builder', text: 'Define a model in the schema dialog with typed fields (text, number, date, reference, and more). The model is stored on the dataset itself, and records are validated against it on every server-side write.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Typed documents', anchor: '#typed-documents', text: 'Edit records in the typed document editor — each field renders the right input for its type, so data stays clean.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Relations', anchor: '#relations', text: 'Fields can reference other records, including many-to-many relations, letting you model real structures (posts ↔ authors, products ↔ categories).' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Query layer', anchor: '#query-layer', text: 'A dataset query layer powers both the editor and screen bindings, so the same data is available to design-time previews and the live site.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Repeatable components', anchor: '#repeatable-components', text: 'Bind a component over a dataset to repeat it per record — a list, grid, or gallery driven by your data. The Besigner shows a repeat badge so you know a component is data-driven.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Who a dataset is shared with', anchor: '#who-a-dataset-is-shared-with', text: 'Datasets belong to the workspace, not to a single site, so one dataset can drive pages on every site you run. When that isn\'t what you want, the Sharing control on each dataset decides which sites can see it: - All sites — everyone in the workspace, on every site. The default, and what every existing dataset already uses. - This site only — the dataset is usable on one site and invisible everywhere else. - Selected sites… — pick the sites that share it, up to 30. This matters most for agencies. If you run three internal sites alongside twelve client sites, your rate card can be shared with the internal three and stay invisible to the clients — including to the client collaborators you have invited, who will not see it in the Data page, the pickers, or anywhere else. Sharing is enforced on the server, not just in the console. A site cannot render a dataset it hasn\'t been shared with even if a page explicitly asks for it by name. A few consequences worth knowing: - Narrowing sharing can empty a live page. If a published page repeats over a dataset and you remove that site, the page renders with no rows. The console warns before saving a change that takes a site\'s access away. - Reference fields need both sides. A reference from one dataset to another only resolves on sites that can see both, so the target\'s sharing has to cover the source\'s. - Limits are workspace-wide. Your dataset and record allowances count everything the workspace owns, whether or not you can see it all. Sharing decides visibility, not billing. - Deleting is a workspace action. A dataset shared with more than one site can\'t be deleted from a single site\'s Data page — narrow its sharing instead, or delete it from the workspace Data page.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Import & export', anchor: '#import--export', text: 'Datasets round-trip via CSV and JSON: export your records, edit them elsewhere, and re-import with validation on the way in. A whole-site export includes the datasets and media that site can see, and nothing else — an agency exporting a client site gets that client\'s data only. On restore, everything comes back shared with the site you restored into, not with whatever it was shared with before. Widen it afterwards if you meant to share it. That direction is deliberate: a bundle can be restored into a different site or a different workspace entirely, and quietly re-publishing one client\'s data across another\'s sites would be far worse than an extra click.' },
  { path: '/content-and-data/datasets/overview', title: 'Datasets & Dynamic Content', heading: 'Related', anchor: '#related', text: '- Forms & lead capture - Bindings, variables & functions - Content collections & blog' },
  { path: '/content-and-data/datasets/relations', title: 'Relations', heading: '', anchor: '', text: '# Relations Real data is connected — posts have authors, products have categories. Relations let a record reference other records. :::info Plan availability Pro.' },
  { path: '/content-and-data/datasets/relations', title: 'Relations', heading: 'Reference fields', anchor: '#reference-fields', text: 'Add a reference field to a model to point at records in another dataset (or the same one). For example, a post can reference its author.' },
  { path: '/content-and-data/datasets/relations', title: 'Relations', heading: 'Many-to-many', anchor: '#many-to-many', text: 'Relations support many-to-many, so a record can link to several others and vice versa — a product in many categories, each category holding many products.' },
  { path: '/content-and-data/datasets/relations', title: 'Relations', heading: 'Using relations', anchor: '#using-relations', text: 'The dataset query layer resolves related records for both the editor and screen bindings, so you can render a record together with the things it links to.' },
  { path: '/content-and-data/datasets/relations', title: 'Relations', heading: 'Tips', anchor: '#tips', text: '- Point references at a stable model — renaming fields is safe, but restructuring a related model affects everything that references it.' },
  { path: '/content-and-data/datasets/relations', title: 'Relations', heading: 'Related', anchor: '#related', text: '- Build a data model - Import & export' },
  { path: '/content-and-data/events/overview', title: 'Events Calendar', heading: '', anchor: '', text: '# Events Calendar The Events Calendar is a schedule your workspace edits in the console and your visitors read on the site. Each event carries a time, a place, an organizer, a description and a cover image, and stays invisible until you publish it. :::info Plan availability Add-on. The Event Calendar is a $9/mo add-on that covers the whole workspace on any paid plan — buy it on Billing → Add-ons (see Add-ons). Until it\'s enabled the Events page explains the add-on, and the Event List element renders nothing on your site.' },
  { path: '/content-and-data/events/overview', title: 'Events Calendar', heading: 'Manage events', anchor: '#manage-events', text: 'The console Events page lists your site\'s events, newest start first. Add event opens the editor; each event has: - Title — required. - Starts and Ends — a start time is required; leaving the end blank (or setting it before the start) gives the event one hour. - Location and Organizer — both optional, and both shown next to the date. - Cover image URL — optional thumbnail, shown beside the event. - Description — optional detail paragraph. Set published / Set to draft flips an event\'s status, shown as a chip in the list. Delete removes an event from your site. :::note Drafts never leave the console The public listing filters to published events on the server, so a draft is never sent to a visitor\'s browser — it\'s a safe place to stage next month\'s schedule.' },
  { path: '/content-and-data/events/overview', title: 'Events Calendar', heading: 'Show events on a screen', anchor: '#show-events-on-a-screen', text: 'Events reach visitors through the Event List canvas element (Data display category) — drop it on any screen in the Besigner and set: - Heading — a title above the list; empty hides it. - Show — Upcoming (default) or Past events. - Max items — how many to render (default 10). Upcoming lists the next events by start time; past lists the most recent first. The list is served through the public events API and cached briefly at the CDN, so a newly published event can take about a minute to appear.' },
  { path: '/content-and-data/events/overview', title: 'Events Calendar', heading: 'Search engines', anchor: '#search-engines', text: 'Every rendered event emits schema.org Event JSON-LD — name, start and end, place, organizer, description and image — so search engines can show your events as rich results. Nothing to configure; see SEO for the rest of your site\'s structured data.' },
  { path: '/content-and-data/events/overview', title: 'Events Calendar', heading: 'Related', anchor: '#related', text: '- Add-ons - Bookings & scheduling - SEO & structured data' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: '', anchor: '', text: '# Forms & Lead Capture Forms let visitors send you information — contact requests, sign-ups, lead capture. Submissions land in your inbox and can flow straight into a dataset and your contacts CRM. :::info Plan availability Free for basic forms and the inbox. Higher tiers raise submission and dataset caps.' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'Build a form', anchor: '#build-a-form', text: '1. Drop form components onto a screen in the Besigner (fields, submit button). 2. Configure the fields and the submit behavior. 3. Publish — the form posts to Aglyn\'s submit API. :::note Per-visitor rate limit Submissions are capped at 10 per minute per site, per visitor address. A visitor over the limit gets a short retry delay, not a permanent block. It\'s per address, so one spammer can\'t lock out everyone else — but bulk-importing through your own public form will trip it. Use datasets for imports instead. That per-address limit is one of several protections in front of your form — see Spam and abuse protection. ### Monthly allowance per plan Each tier includes a monthly form-submission allowance, counted per site: | Plan | Submissions / month | | --- | --- | | Free | 20 | | Starter | 200 | | Pro | 1,000 | | Business | 10,000 | | Scale | 50,000 | | Advanced | 100,000 | | Agency & Enterprise | Unlimited | On Free, that allowance is a hard wall: at the cap, further submissions are declined — the visitor sees the form\'s error message rather than a fake success. On every paid tier it is a band, not a wall: submissions past the included count keep working and bill as metered overage, the same way storage and API requests do, because a dropped submission is a lost lead. Either way the count resets with the calendar month (UTC), and the billing page\'s usage meters warn you at 80% before you get there. Unlimited on Agency and Enterprise means exactly that about the plan: nothing meters your submission volume and nothing cuts you off for buying too small a tier. It is not a promise that the endpoint will take any number of requests from anyone — every site, on every plan, sits under the anti-abuse ceiling below. A single submission can carry up to 20 fields and about 10 KB of' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'Spam and abuse protection', anchor: '#spam-and-abuse-protection', text: 'A published form is a public endpoint on the open internet — that is the point of it. Three things stand in front of it, and none of them asks your visitors to prove they are human: - A honeypot field. Every Aglyn form carries an input that humans never see and never fill. A bot that fills it in gets an ordinary-looking success and nothing is stored — it learns nothing and keeps wasting its time. - A per-address rate limit. The 10-per-minute limit above, enforced across all of our servers rather than per instance, so it still holds when traffic is spread out. - A per-site monthly ceiling. Below. There is deliberately no CAPTCHA and no attestation check on the submit endpoint. A challenge in front of a lead-capture form is paid for by every real visitor so that a bot doesn\'t get through, and it costs conversions. Whether that trade is the right one is an open question we have not settled — see Trust & security for the same statement from the reviewer\'s side. Until it changes, the ceiling is what bounds the damage. ### The per-site monthly ceiling Separate from your plan allowance, each site has a monthly ceiling on how many submissions the endpoint will accept at all. It is abuse containment, not a quota: you are not metered against it, it is not something to plan capacity around, and no legitimate site reaches it. It sits at ten times your plan\'s included allowance, or 5,000, whichever is larger — and at 1,000,000 on the unlimited tiers — so it is always far above the volume you actually bought. If a site does cross it: - Further submissions are refused for the rest of the calendar month, and a refused submission is not billed. It is turned away before the billing counter moves, so a flood cannot add anything to your invoice — not even the part that was refused. - Nothi' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'Field types', anchor: '#field-types', text: 'Each Form Field has a type that controls what visitors see and what is submitted: | Type | Visitor sees | Submitted value | | --- | --- | --- | | Text (default) | Single-line input | The text | | Email | Email input | The address | | Multiline | Multi-row text area | The text | | Dropdown | Select menu | The chosen option | | Radio choice | One radio button per option | The chosen option | | Checkboxes | One checkbox per option | All ticked options, joined with , | | Star rating | Five stars | The number of stars (e.g. 4) | Dropdown, radio, and checkbox fields take their choices from the field\'s Options setting — enter one choice per line (or separate them with commas). Blank entries are ignored. The Required? switch works per type: a required checkbox group needs at least one box ticked. ### Labels and placeholders Every field has a Label — the visible name of the input, and the one screen readers announce. A field can also carry a Placeholder: a grey example inside the empty input, such as you@company.com or "Tell us about your setup". Set one and the label moves above the box so both are readable at once; leave it empty and the label keeps its floating behaviour. A placeholder is a hint, never a substitute for the label — it vanishes the moment a visitor starts typing, and a field labelled only by its placeholder is unusable with a screen reader. Text, email, and multiline fields show it inside the input; a dropdown displays it until a choice is made; radio, checkbox, and rating fields ignore it. Clearing the setting removes the hint. ### Example: a quick survey Build a feedback survey with four fields: 1. A Star rating field named satisfaction, labeled "How satisfied are you?". 2. A Radio choice field named visit-frequency with options First time, Monthly, Weekly. 3' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'After submit', anchor: '#after-submit', text: 'The form\'s After submit setting controls what a successful submission does: | Outcome | What the visitor sees | | --- | --- | | Show the success message (default) | The form is replaced by your Success message | | Redirect the visitor | The browser navigates to a screen you pick (rename-safe — slug changes never break it) or, with no screen picked, to a Redirect URL (a same-site path like /thanks or an https URL; anything else is ignored) | | Reveal a hidden element | An element you pick from the canvas — hidden on the published page until then — appears in place of the form | For the reveal outcome, drop the follow-up content (a thank-you block, a download link, an embedded video) anywhere on the screen, then select it as the Element to reveal. It stays hidden for visitors until the form is submitted; in the Besigner it stays visible so you can keep editing it. If a redirect target can\'t be resolved (the screen was deleted, the URL was rejected), the form falls back to the success message. ### Example: grow an email list from a signup form Combine an outcome with a conditional automation: 1. Add a Checkboxes field named subscribe with one option, Yes, keep me posted. 2. Set After submit to Redirect the visitor and pick your /thanks screen. 3. On the Workflows page, add an action on formSubmission with the condition "A field is not empty" → subscribe and the step Enroll in a list, picking your email audience. Visitors who tick the box are added to the list (and can be targeted by email campaigns); everyone lands on the thank-you page. Need a finer net? Conditions chain with AND/OR — e.g. enroll only when subscribe is ticked and plan equals Pro, or when either of two topic boxes is ticked.' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'Where submissions go', anchor: '#where-submissions-go', text: '- Inbox — every submission is captured; open it in the console\'s mail reader dialog. - Datasets — bind a form to a dataset (Write to dataset on the Form element) and each submission is also appended as a record. The inbox always gets its copy. - Contacts — form submissions are one of the ingestion sources that build your contacts list. ### The inbox The site\'s Inbox page collects everything visitors send, in three tabs — Submissions, Members & leads, and Campaigns. On the Form Submissions table: - Unread submissions are bold with a New chip; site managers also get an in-app notification per submission. - Click a row to read it — every field the visitor filled, labeled — and it\'s marked read; Mark unread puts it back. - Delete removes a submission permanently (it asks first). Each row shows which Form it came from — that\'s the Form element\'s Form name attribute, so name your forms distinctly ("Contact", "Newsletter", "Survey") and the inbox stays sorted at a glance.' },
  { path: '/content-and-data/forms/overview', title: 'Forms & Lead Capture', heading: 'Related', anchor: '#related', text: '- Datasets & dynamic content - Contacts CRM - Email campaigns' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: '', anchor: '', text: '# Media Library & CDN The media library stores your images, video, and files, keeps them organized, and serves them quickly. Media plugs into components like Image and Video and into the theme\'s favicon. :::info Plan availability Free with storage quotas. CDN delivery with WebP variants is a paid-tier feature; large video uploads and higher storage are gated by plan.' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Organize', anchor: '#organize', text: '- Arrange media in a folder hierarchy. Folders appear as cards in the grid (folders first, before files) as well as in a side rail — open one to browse into it, and use the breadcrumb to step back out. - Drag and drop to reorganize: drag a file (or a whole selection) onto a folder to move it in, drag a folder onto another to nest it, or drop onto a breadcrumb to move items up and out. Nesting depth and name-collision rules are enforced automatically. - Move to folder… shows the full path, not just the folder name — Blog / Covers and Press / Covers are two different destinations and the menu says so. The same paths appear in the detail drawer\'s Folder field. - Big moves are safe to interrupt. Moving a large selection relocates the stored objects one at a time, so the library keeps working through it and tells you how far it has got. If it cannot finish everything, it reports the real split — Moved 7 of 19 — 12 could not be moved — and leaves the files that did not move selected, so clicking Move again picks up exactly where it stopped. Nothing is lost either way: a file is only ever in one folder, its URL keeps working, and a repeat move of a file that already arrived does nothing. - Filter by type, date, and size, search, and sort the library. - Search covers everything you authored, not just file names — alt text, description, tags, folder name and your own custom metadata values are all searchable. Results update as you type, and ✕ (or Esc) clears the box. - Wildcards: mock--noshadow.png matches a whole family of files. is any run of characters, ? is exactly one, and a wildcard pattern matches the whole value. - Search one field: tag:hero, name:logo, alt:product, desc:landing, folder:brand, or a custom field by key — meta.campaign:spring. Combine them with plain words' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Upload', anchor: '#upload', text: '- Upload images, video (MP4, WebM, QuickTime), PDFs, ZIP archives and documents (Word, Excel, PowerPoint, CSV, RTF, plain text, Markdown and JSON). Click Upload media, or drag files straight from your desktop onto the library — dropped files land in the folder you have open. - Documents and archives are stored and served exactly as you uploaded them — nothing is opened, extracted or converted. Macro-enabled Office files (.docm, .xlsm, .pptm) are not accepted. - Rename, replace the file behind an asset, and edit images in place. Replace is available from the asset\'s details drawer and straight from the card\'s overflow menu. ### Size and plan limits | Upload | Cap | Plan | | --- | --- | --- | | Images | 15 MB per file | Every plan | | PDFs | 25 MB per file | Pro and above | | Documents (Word, Excel, CSV, RTF, text, Markdown, JSON) | 25 MB per file | Pro and above | | Presentations (PowerPoint) | 50 MB per file | Pro and above | | ZIP archives | 50 MB per file | Pro and above | | Video | 200 MB per file | Pro and above | Any file over 3 MB automatically uses signed-URL uploads, so big files go straight to storage without tying up the console. Folders nest up to 5 levels deep. :::note SVG uploads are cleaned An SVG is a document, not just a picture — it can carry scripts, event handlers and references to other sites. Uploaded SVGs have all of that stripped, and the delivery URL serves them under a policy that blocks scripting outright. Your marks and logos render exactly as before; a decorative SVG that relied on embedded script or on pulling an image from another domain will render without those parts. Storage is metered per site against your plan (Free 250 MB, Starter 2 GB, Pro 10 GB, Business 50 GB, Scale 75 GB, Advanced 100 GB, Agency 200 GB, Enterprise unlimited) — the' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Deliver over CDN', anchor: '#deliver-over-cdn', text: 'Paid tiers serve media via a CDN with automatic WebP variants, so images load fast and cache well. ### URLs are stable A media URL is keyed to the asset, not to its bytes or its location. That means the link you copied stays correct when you: - Replace the file — every screen, layout, and content entry that embeds it serves the new image immediately, with no re-linking. - Move it between folders — organizing your library never breaks a live page. So replacing a logo across a whole site is one upload, not a hunt for every reference. Links copied before this behavior shipped keep working too. ### Page elements point at the asset, not at a link When you place an image with Browse media, the element records which asset you chose rather than a link to it. You never have to copy or paste a path, and the element keeps working through folder moves, file replacements, and any future change to how we deliver media. Copy URL is still there for pasting a link somewhere outside Aglyn. You can also type any external image URL into the field by hand — useful for hotlinking an image hosted elsewhere. Images placed before this shipped keep rendering exactly as they did. When a visitor saves a delivered file, it keeps the asset\'s original filename and extension, even though the URL itself doesn\'t carry one.' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Who an asset is shared with', anchor: '#who-an-asset-is-shared-with', text: 'Workspace media is shared across every site by default. The Shared with control narrows that, with the same three choices as datasets — All sites, This site only, or Selected sites…. You\'ll find it in three places: - on a single asset, in its details drawer; - on a selection — tick several files and use Shared with… in the toolbar; - on a folder, from its ⋮ menu, which offers to apply the same sharing to the files inside it and its subfolders (it names the count, so you know what you\'re about to change). A folder applies its sharing when you save it — files keep their own setting afterwards, so moving a file into a "Client A" folder later does not re-share it. Narrowing a file that sites are already using names those sites first and asks you to confirm. Only workspace owners and admins can change sharing. A new folder starts shared with All sites, so it appears everywhere the moment you create it — or with the site you were working in, if your workspace has been set to make new resources site-scoped by default. If the Shared with dialog ever opens on "Not shared with any site", that folder or file has no sharing stored at all: it is hidden from every site, and any file inside it turns up under No folder there. Pick a value and save to fix it. In the media picker\'s Organization (shared) tab, a site sees only the assets it may use. An agency\'s internal artwork stays out of the client sites\' pickers entirely. :::warning Sharing controls discovery, not secrecy Sharing decides which sites may find and use an asset, and stops the CDN serving a restricted asset to a site it isn\'t shared with. It does not make the bytes secret: anyone holding a delivered media URL can still fetch it, because that URL is public and cacheable by design — that is what makes the CDN fast. Treat an ' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Private files', anchor: '#private-files', text: 'Private is a separate switch from sharing, and it answers a different question: | | Question it answers | | -- | -- | | Shared with | Which of your sites may use this file? | | Private | May anyone fetch these bytes at all? | A private file: - has no public URL — the normal media link does not exist for it, - cannot be placed on a page; the picker refuses it and says why, - is viewable and downloadable in the console by people who can already see it, through a temporary link that stops working after about fifteen minutes. That expiry is the point. A normal media URL, once shared, works forever and there\'s no way to take it back. A private file\'s link dies on its own, so a link pasted somewhere it shouldn\'t have been is a short problem instead of a permanent one. Use Private for things that aren\'t website assets: a signed contract, unreleased artwork, an embargoed announcement, anything with personal data in it. Don\'t use it to keep an image off one particular site — that\'s what sharing is for, and marking it private will just stop the image working everywhere. To publish a private file later, turn Private off. It gets a normal URL from that moment on.' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Components', anchor: '#components', text: '- Image — place and bind images from the library. - Video — embed uploaded video. - Favicon picker — choose the site favicon from your media. Everywhere you pick media — the Image and Video components, the logo and favicon pickers, and the organization logo field — the same media picker opens, with This site and Organization (shared) tabs so you can pull from either library without leaving the dialog.' },
  { path: '/content-and-data/media/overview', title: 'Media Library & CDN', heading: 'Related', anchor: '#related', text: '- Bindings - SEO toolkit (Open Graph & Twitter images)' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: '', anchor: '', text: '# Building feature plugins Aglyn features that add both console surface and site components ship as a single library (AGL-277) — never merged into the core mui plugin, which stays purely component and theme definitions for the Besigner and hosts. Plugins live directly under libs/plugins/{feature} (moved out of the old .../ui/ nesting in AGL-395) and publish as @aglyn/plugins-{feature}. A plugin keeps its Besigner component, its console page, and both registration functions in the one lib — the console half is a separate registerConsole() export, so the shell can register nav + pages at app load without pulling in the Besigner canvas bundle. Sharing app hooks. A relocated console page can\'t import console-app hooks. Genuinely reusable ones move into a shared lib the plugin can import — e.g. useFirestoreCollection, useFirestoreDoc, and useHostOrgId now live in @aglyn/tenant-feature-instance, and HubTabs in @aglyn/shared-ui-next (the app keeps thin re-export shims). Reaching app-only UI (media browser). Some app UI can\'t move — the media library is coupled to the org/session context. Instead of importing it, a plugin consumes it through a context: MediaPickerContext / useMediaPicker() in @aglyn/aglyn exposes pickMedia(): Promise<PickedMedia | null>. The shell mounts the app\'s ConsoleMediaPickerProvider (which owns the real dialog) around every plugin page, so a plugin component just calls pickMedia() and gets the chosen asset — see the commerce product editor. This is the escape hatch for the dependency cascade a naive promotion would hit.' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'The UI half', anchor: '#the-ui-half', text: 'Build a bundle with defineUiFeatureBundle from @aglyn/aglyn (the plugin-manager registration API, AGL-415) and register it the same way the mui bundle registers itself. The bundle automatically declares a dependency on the mui bundle, so primitives and theming load first. :::warning Component and bundle ids are persisted componentId and pluginId are stored in screen documents. Never rename them — when a component moves between bundles, keep the old ids resolving (the mui plugin\'s legacy-id aliases are the precedent).' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'The console half', anchor: '#the-console-half', text: 'Export a ConsoleExtension and register it at console startup. The console shell renders the nav items and their pages from the registry — and applies the featureFlag entitlement gate itself, so an extension can\'t bypass plans. A feature plugin adds a menu item to the host app bar and a new page without editing any core console file (AGL-394). A nav item that carries a Component becomes a full page: the shell\'s generic host route (apps/console/app/(app)/[hostId]/[pluginSlug]/page.tsx) mounts it under the active host, wires the breadcrumb/header, resolves the featureFlag entitlement, and passes it in as entitled. The page component receives ConsolePluginPageProps — { hostId, entitled, org } — so it stays free of console-app hooks. org is the resolved org billing doc the shell already loaded, so the page can run its own checkEntitlement/checkQuota (e.g. per-plan limits) without the app\'s org/session hooks: ### How the shell consumes the registry 1. apps/console/constants/register-console-plugins.ts calls each plugin\'s registerConsole() at import time; app imports it so the registry is populated before any nav renders. This registers only the console half — never the Besigner canvas bundle — so plugin canvas code stays out of the general console bundle. 2. hostNavTabItems splices listConsoleNavItems() into the host tab strip. Nav gating is unchanged: an item\'s navTabId maps to a release flag, so staff still preview flagged-off surfaces. The strip itself is built by useSecondaryNav() from the current route and rendered once by app/(app)/layout.tsx — a plugin never passes tabs to a page, and pages have no nav props to set (AGL-754/755). 3. The generic [hostId]/[pluginSlug] route resolves the page with resolveConsolePluginPage(\'/\'+slug), renders it inside DashboardLayout under' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'Loading: org-gated and dynamic (AGL-417)', anchor: '#loading-org-gated-and-dynamic-agl-417', text: 'Apps never import @aglyn/plugins-. plugins.config.json maps plugin ids to packages and register entry points; tools/scripts/generate-plugin-manifests.mjs emits the per-app loader manifests (plugins..generated.ts) — the ONLY sanctioned plugin references outside libs/plugins (an nx scope:app boundary rule enforces this). At runtime the core plugin loader activates the plugins in org.enabledPlugins (AGL-416, org settings → Plugins): console surfaces behind the providers gate, site/canvas surfaces behind the editor/tenant suspense gates, API handlers lazily on first dispatch with a per-request org gate (a disabled plugin\'s API 404s for that workspace). Each first-party plugin is additionally release-flagged (AGL-422, FirstPartyPlugin.releaseFlag): a flag staff turn off in the console Feature Flags page subtracts the plugin from every workspace\'s effective set — nav, editor, published sites, and API — with the usual staff preview bypass. Register a flag for any new plugin (registry + Remote Config template + the catalog entry).' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'Extending beyond pages: slots, providers, runtimes, hooks (AGL-418/419)', anchor: '#extending-beyond-pages-slots-providers-runtimes-hooks-agl-418419', text: '- Widgets — ConsoleExtension.widgets render into named shell slots via the app\'s PluginWidgetSlot. The guaranteed zones (and the props each receives) are the exported CONSOLEWIDGETSLOTS catalog (AGL-433): hostActivity, commerceGlance, orgData, besignerFunctions, marketplaceListing, orgAddons, dashboardFooter, orgSettings, hostSettings, and the staff-only adminOrgDetail. - Providers — ConsoleExtension.providers mount around every console page (e.g. marketplace\'s AI-assist provider). - Site runtimes — registerSiteRuntime components run on every rendered tenant page (marketing\'s overlays/experiments/automations), reading back the props their server enricher wrote. - Site-page hooks — /server entries register redirect resolvers, page resolvers (commerce PDP/PLP), and enrichers into the tenant loader. - Billing webhook hooks — registerBillingWebhookHandler receives the platform Stripe events (commerce orders, booking payments, marketplace purchases live in their plugins). - Permissions (AGL-435) — registerPluginPermissions([{key, label, defaults: {admin, editor, viewer}}]) contributes role-resolved keys: they ride every resolved permission set (ConsolePluginPageProps. permissions, API-side resolution), and custom roles override them key-by-key. Reference adopter: commerce\'s managePos. - Scheduled jobs (AGL-435) — registerPluginJob({pluginId, name, intervalMinutes, handler}) on the /server surface; the deployment\'s scheduler POSTs /api/plugins/run-jobs (shared PLUGINJOBSSECRET header, 501 when unconfigured) and due jobs run with error isolation. Keep handlers idempotent and bounded. Reference adopter: bookings\' expire-stale-holds. - Custom field types (AGL-434) — registerCustomFieldType({name, pluginId, label, baseType, Input, validate}) adds a named field type to the dataset' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'Remote bundles: the trusted realm tier (AGL-420)', anchor: '#remote-bundles-the-trusted-realm-tier-agl-420', text: 'Marketplace plugins normally run sandboxed in the cross-origin PluginFrame. Listings a staff member has reviewed and signed (trust: \'realm\' + an Ed25519 signature over the bundle\'s sha256 on the version doc) instead load INTO the app realm and use every registry above — first-party-grade extensions installed per workspace, no repo change. - Build with tools/plugin-loader/realm/rollup.config.mjs: your react, react/jsx-runtime, and @aglyn/aglyn imports compile to lookups on globalThis.AGLYNPLUGINHOST (the app\'s own singletons), so the emitted bundle imports nothing. Export register(host) for client surfaces; registerApi() for server handlers. - Publish through the marketplace pipeline, install (pins {version, sha256}), then staff grant trust via POST /api/admin/sign-plugin. - The console loads an org\'s realm installs before the shell renders; published sites load them post-hydration (additive runtimes — first paint never waits on a marketplace CDN). Every load verifies the sha256 pin and the platform signature and fails closed; revocations is the hard kill switch. - Server handler bundles are additionally gated by PLUGINREMOTESERVER=enabled + a per-deploy PLUGINREMOTESERVERBUNDLES allowlist, default off everywhere. Full trust chain, env matrix, and walkthrough: docs/PLUGINLOADING.md in the repo; a runnable demo lives at tools/plugin-loader/realm/demo.' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'The server half (API routes)', anchor: '#the-server-half-api-routes', text: 'A feature\'s server logic — Next.js API routes backed by firebase-admin — moves into its plugin the same way, through the API-route registry (AGL-396), the server counterpart to the ConsoleExtension registry. Each Next app ships one catch-all dispatcher that imports a server-only registration module (registerPluginApis()) and resolves the request path against the registry. Both apps are on the App Router (app/api/[...pluginApi]/route.ts, AGL-408/410); the same PluginApiHandler runs unchanged in either. The dispatcher runs the handler through the runLegacyHandler adapter (@aglyn/aglyn/server, AGL-407), which bridges the Web Request/Response to the framework-light (req,res) contract: Named API routes win over the catch-all, so URLs are preserved: to migrate /api/events/list, delete the named route file and register the handler — the dispatcher serves the same URL. Import the plugin\'s /server entry only from the dispatcher\'s registration module (server code); the client barrel must never pull it in, or firebase-admin leaks into the browser bundle. Reference: libs/plugins/events-calendar/src/lib/server.ts. Both Next apps carry a dispatcher. The tenant (site-facing) app registers via registerTenantPluginApis; the console (authoring) app has its own dispatcher + registerConsolePluginApis, and plugins expose a separate registerConsoleApi() for console-only handlers (staff/merchant ops, cron jobs) so each app registers only what it serves. A migrated route keeps its /api/... URL in whichever app owned it. Raw-body routes. On the App Router a handler reads the raw body directly (request.text()/arrayBuffer()), so webhooks (Stripe billing/webhook, Svix email/events) and size-capped uploads need no bodyParser config — the old Pages Router export const config exceptions are gone; byt' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'Project setup', anchor: '#project-setup', text: 'Scaffold a new first-party plugin instead of hand-copying one (AGL-425): That generates the complete libs/plugins/my-plugin library (correctly tagged, with register entries per surface and a passing spec), registers it in plugins.config.json + the tsconfig aliases, re-runs the manifest codegen, and prints the two manual follow-ups (catalog entry + release flag). Marketplace/marketplace authors start from tools/plugin-loader/realm/template instead — a standalone npm package that builds a host-ABI realm bundle. Conventions the scaffold already applies: - Tag new plugin libs with exactly ["aglyn:addons"] — nothing else (AGL-409). This single tag is a plugin\'s whole module-boundary identity: as a dependency target no core scope\'s allowlist reaches it, so nx lint rejects any core lib importing @aglyn/plugins- (the app can run without the plugin). As a source, the aglyn:addons rule still lets a plugin import any lib and other plugins. Do NOT add scope:lib/scope:aglyn back — that reopens the hole (every lib carries scope:lib). - Plugins are wired in only through the generated loader manifests (plugins.config.json → plugins..generated.ts, AGL-417); core libs and app feature code must never import a plugin. - Plugin libs may import @aglyn/plugins-mui for primitives; nothing may import a feature plugin from @aglyn/plugins-mui (that direction is the anti-pattern this rule exists to stop).' },
  { path: '/developers/plugins/building-feature-plugins', title: 'Building feature plugins', heading: 'Reference implementations', anchor: '#reference-implementations', text: '- Events calendar (libs/plugins/events-calendar) — the reference: its whole console page lives in the plugin (AGL-313/394). - Bookings (libs/plugins/bookings) — the second full extraction (AGL-395): the booking canvas component moved out of plugins-mui and the bookings manager out of the app; the page reads plan limits via the org prop + checkQuota. - Redirects (libs/plugins/redirects) — a console-only plugin (AGL-395): redirects enforce server-side (ISR), not through a canvas component, so it exports only registerRedirectsConsole() and ships no UI bundle — nothing to register in the tenant/besigner. The minimal shape when a feature has console surface but no site component. - Logic (libs/plugins/logic) — console-only (AGL-395): variables + no-code functions and the reference-integrity audit. It also exports shared tooling — the where-used dialog and its fetch util, plus the variable/function cards — which the app\'s workflows surface and besigner ƒx button import from @aglyn/plugins-logic. Always-on (not release-flagged). - Contacts (libs/plugins/contacts) — console-only (AGL-395): the unified contacts list, segments, and profile drawer. A whole self-contained page relocated with just the layout wrapper + inline FeatureGate stripped (the shell supplies both); reads the contactsPerHost quota off the org prop. - Inbox (libs/plugins/inbox) — console-only (AGL-395): form-submissions reader, site members + leads, and the borrowed Orders and Campaigns tabs. Depends on @aglyn/plugins-commerce + @aglyn/plugins-email — a plugin can compose tabs from other plugins the same way the app did. - Marketplace (libs/plugins/marketplace) — console-only, multi-page (AGL-395): the plugin owns the hub page and its cards + useMarketplaceActions, but the listing/publisher detail pages stay as' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: '', anchor: '', text: '# Console extensions & site surfaces Task-ordered recipes; the deep semantics live in Building feature plugins and the API reference.' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: 'Add a console page', anchor: '#add-a-console-page', text: '1. Export a registerConsole() that calls registerConsoleExtension with a navItems entry carrying a lazy Component. 2. The shell serves it at /[hostId]/ , wires breadcrumbs/header, resolves the featureFlag entitlement, and passes ConsolePluginPageProps { hostId, entitled, org, permissions }. 3. Need data? Use @aglyn/tenant-feature-instance hooks (useFirestoreCollection, usePluginConfig, …) — never console-app hooks. 4. First-party: add the register fn to your plugins.config.json entry under console and re-run the manifest codegen (the scaffolder did both if you used it).' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: 'Add a widget to a shell zone', anchor: '#add-a-widget-to-a-shell-zone', text: 'Pick a zone from the catalog, then: Your component receives the zone\'s documented props. Multiple plugins can target one zone; the shell renders all of them.' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: 'Wrap every console page (providers)', anchor: '#wrap-every-console-page-providers', text: 'providers: [MyProvider] mounts around every console page once the registry is populated — the marketplace plugin\'s AI-assist provider is the reference. Providers receive the org billing doc as tenant.' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: 'Add a canvas component (Besigner + published sites)', anchor: '#add-a-canvas-component-besigner--published-sites', text: 'Use defineUiFeatureBundle on your site surface — components get schemas + presets and appear in the Besigner drawer. Component ids are persisted in screen documents; never rename them. The editor and the published site both suspend until your site surface registers, so the canvas never renders unregistered components.' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: 'Add a site runtime', anchor: '#add-a-site-runtime', text: 'A runtime renders on every published page of workspaces that enable your plugin — overlay engines, analytics beacons, experiment runners: Pair it with a server enricher (registerSitePageEnricher, /server) that writes the props slice your runtime reads back from page. Enricher errors are isolated — your slice drops, the page survives. Cross-plugin wiring belongs in bootstrap (), which runs after every plugin in the batch has registered.' },
  { path: '/developers/plugins/guides/console-and-site', title: 'Guide: console extensions & site surfaces', heading: 'Troubleshooting', anchor: '#troubleshooting', text: '- Nav item missing: the plugin isn\'t enabled/released for the workspace, or the register fn name in plugins.config.json drifted (the loader logs missing register fn). - Widget renders nowhere: check the slot name against the catalog — unknown slots render only where an app mounts a custom PluginWidgetSlot. - Canvas blank in the editor: your component registered on the console surface instead of site — the editor gates load site.' },
  { path: '/developers/plugins/guides/examples', title: 'Worked examples', heading: '', anchor: '', text: '# Worked examples The best examples are the shipping plugins — each one is the reference implementation of a pattern. Generated skeletons stay fresh by construction: node tools/scripts/create-plugin.mjs sample --surfaces console,tenantApi scaffolds a complete, test-passing plugin you can read and delete. First-party plugin libs are deliberately not duplicated as "example" libs — they would rot, and the scaffolder and the live plugins can\'t. The one checked-in example is the sandbox marketplace plugin below, which exists because the sandbox contract has no first-party equivalent to read. | Pattern | Read this | Why | | --- | --- | --- | | Console-only plugin | libs/plugins/redirects | The minimal shape: one nav item + page, server-side enforcement, no canvas bundle | | Full-stack feature | libs/plugins/commerce | Pages, widgets, canvas components, page resolvers, APIs, billing hooks — everything at once | | Site enricher + runtime pair | libs/plugins/marketing | Server enricher writes page props; the registered runtime reads them back | | Plugin→plugin composition | libs/plugins/inbox | Composes tabs from commerce + email — the dependency direction plugins are allowed | | Site canvas components | libs/plugins/bookings | Canvas component + console manager + APIs + a config schema (maxDaysAhead) and a scheduled job | | Custom field type | libs/plugins/marketplace (rating) | Pure-data type + client Input, registered from both surfaces | | Plugin permissions | libs/plugins/commerce (managePos) | Per-tier defaults riding every resolved role set | | Marketplace realm bundle | tools/plugin-loader/realm/demo (+ EXPLAINED.md) | The standalone track, narrated line by line | | Marketplace starter | tools/plugin-loader/realm/template | What you actually copy to begin | | Sandbox mar' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '', anchor: '', text: '# Build your first plugin Two tracks share the same registries. First-party plugins live in this repo under libs/plugins/ and load through the generated manifests; marketplace plugins are standalone bundles published to the marketplace. This walkthrough does marketplace end-to-end and notes the first-party deltas.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '1. Scaffold', anchor: '#1-scaffold', text: 'The marketplace starter gives you src/index.js (the entry contract), manifest.json, a build config that compiles your react / @aglyn/aglyn imports into host-ABI lookups, and a README that becomes your marketplace listing docs. The first-party scaffolder generates the whole Nx library, wires plugins.config.json, and prints the two manual follow-ups (catalog entry + release flag).' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '2. Write the entry', anchor: '#2-write-the-entry', text: 'Every registry in the API reference is available on host.aglyn; the zones catalog lists where widgets can render.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '3. Develop against a live workspace', anchor: '#3-develop-against-a-live-workspace', text: 'Start the console/tenant dev server with the dev-loop variable and refresh after each rebuild: The bundle loads unverified (localhost only; the whole path is compiled out of production builds). The browser console logs dev realm bundle loaded (UNVERIFIED): my-plugin. If a change doesn\'t stick, clear the Next dev cache (rm -rf apps/console/.next/cache) — inlined env values live in it.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '4. Verify', anchor: '#4-verify', text: 'The same checks the publish API enforces, run over the bundle\'s parse tree: entry exports, no leftover static imports, no eval/Function/computed access on a global, no import() it cannot resolve, size — and every network call diffed against your manifest\'s capabilities.network, which is why the manifest goes in too. It lists every area it checked, so you can tell a pass from a check that never ran, and prints the bundle\'s sha256 — the content pin every install verifies.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '5. Publish', anchor: '#5-publish', text: 'Publish from Marketplace → Publish (choose A plugin (upload a bundle)) or the API — the bundle plus manifest.json fields and your listing content (README, logo, screenshots, links, license, categories — see the publisher handbook). New listings enter the review queue as submitted; staff list (or verify ✅) them before they appear in browse. Publishing requires a marketplace profile, a Pro plan, and payouts onboarding for paid listings; there\'s a daily publish cap.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '6. Install, enable, load', anchor: '#6-install-enable-load', text: 'A workspace admin installs from the marketplace: the install pins your exact {version, sha256}, enables the plugin on the org switchboard, and it loads on the next visit — sandboxed by default, or into the app realm once staff have signed the version (trust: \'realm\'). Upgrades are explicit re-pins; your published artifacts are immutable, so nobody\'s pinned install can change underneath them.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: '7. Uninstall', anchor: '#7-uninstall', text: 'Marketplace → Installed → Uninstall, or the Uninstall button on the listing\'s own detail page (Uninstall org-wide for an org-scope install), removes the pin and the switchboard entry. Data your plugin created stays untouched — reinstalls pick up where they left off. Design for that: namespace your documents and tolerate finding old ones.' },
  { path: '/developers/plugins/guides/first-plugin', title: 'Build your first plugin', heading: 'Troubleshooting', anchor: '#troubleshooting', text: '- Nothing loads: check the browser console for the loader\'s reason — sha mismatch (stale artifact URL), missing/invalid signature (not realm-signed yet — expected for sandbox-tier), host ABI mismatch (rebuild against the current template), or the plugin isn\'t in org.enabledPlugins. - Blank widgets / hook errors: your bundle carries its own React. Realm bundles must import react only through the template\'s build config (host-ABI lookups) — run the verifier; leftover static imports fail it. - Publish 422: the response lists exactly which static check failed. - Works in dev, not after publish: the dev loop skips verification; the published path doesn\'t. Run the verifier locally first.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: '', anchor: '', text: '# Trusted realm bundles Marketplace plugins run sandboxed by default (cross-origin iframe, capability bridge). The realm tier is for plugins the platform has reviewed and signed: they load into the app realm and use every registry first-party plugins use. This guide is the operator + publisher view; the architecture is docs/PLUGINLOADING.md in the repo.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: 'Build against the host ABI', anchor: '#build-against-the-host-abi', text: 'Use the template\'s build config: your react, react/jsx-runtime, and @aglyn/aglyn imports compile to lookups on globalThis.AGLYNPLUGINHOST — the app injects its own singletons there, which is what keeps your components on the app\'s React and your registrations in the app\'s registries. Export register(host) (client surfaces) and, only if you truly need server handlers, registerApi(). Declare hostAbi in your manifest; a bundle built for another generation never loads.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: 'The chain that runs before a byte executes', anchor: '#the-chain-that-runs-before-a-byte-executes', text: '1. Content pin — the install doc\'s sha256 must match the fetched bytes (immutable content-addressed artifacts). 2. Platform signature — Ed25519 over the sha, granted by super staff after review; verification fails closed. 3. Kill switch — a revocations/{listingId} doc beats everything. 4. ABI check — declared hostAbi must equal the host\'s generation.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: 'Granting trust (staff)', anchor: '#granting-trust-staff', text: 'Admin → Plugin reviews has a Listed plugins — realm trust section: every listed and verified plugin with its recent versions, each showing a Realm-trusted or Sandboxed chip and a Latest marker, with per-version Grant realm trust and Revoke realm trust buttons. Trust is granted to a specific reviewed version, not to the listing — a newer version stays sandboxed until it is reviewed and granted in turn. Both actions are super-staff only and adminAudit\'d. The equivalent API is POST /api/admin/sign-plugin { listingId, version }, with { action: \'revoke\' } to revoke; a hard-kill still needs a revocation doc. Signing requires PLUGINTRUSTPRIVATEKEY on the console deployment — generate the pair with tools/scripts/generate-plugin-trust-key.mjs.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: 'Where realm bundles load', anchor: '#where-realm-bundles-load', text: '- Console: before the shell renders, from the org\'s trusted installs. - Published sites: post-hydration (additive — first paint never waits on a marketplace CDN). - Server (rare): only on deployments with PLUGINREMOTESERVER=enabled plus a per-deploy listingId@version allowlist; every load is audited.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: 'Key rotation', anchor: '#key-rotation', text: 'generate-plugin-trust-key.mjs → resign-realm-plugins.mjs (re-signs every granted version with the new key, --dry-run first) → deploy the new public keys → retire the old private key. Re-sign before the public-key swap so nothing stops loading mid-rotation.' },
  { path: '/developers/plugins/guides/realm-bundles', title: 'Guide: trusted realm bundles', heading: 'Troubleshooting', anchor: '#troubleshooting', text: '- Loads in dev loop, not from the marketplace: dev loop skips verification. Check the browser console for the loader\'s reason — usually "missing signature" (not signed yet) or "sha256 mismatch". - AGLYNPLUGINHOST is not set: your bundle executed outside a host surface — the console gate and site effect set the ABI before loading; don\'t import the bundle yourself. - Server bundle didn\'t register: the dispatcher logs which chain link failed (not realm-trusted, built for host ABI N, fetch, signature) and skips — check the deployment logs and the allowlist entry.' },
  { path: '/developers/plugins/guides/server-apis', title: 'Guide: server APIs, webhooks & jobs', heading: '', anchor: '', text: '# Server APIs, webhooks & jobs Everything here lives on your plugin\'s /server entry and runs inside the apps\' [...pluginApi] dispatchers.' },
  { path: '/developers/plugins/guides/server-apis', title: 'Guide: server APIs, webhooks & jobs', heading: 'An API route', anchor: '#an-api-route', text: '- Served at /api/my-plugin/ping on the app(s) whose manifest lists your register fn (tenantApi, consoleApi, or both). Declare apiPrefixes: ["my-plugin"] in plugins.config.json. - Gating is automatic: requests carrying a hostId (query or JSON body) 404 when the target workspace has your plugin disabled or its release flag is off. Handlers still self-check entitlements (checkEntitlement/checkQuota with the org doc) for plan gating. - Per-org settings: getPluginConfig(orgId, pluginId) returns your declared defaults merged with the workspace\'s overrides.' },
  { path: '/developers/plugins/guides/server-apis', title: 'Guide: server APIs, webhooks & jobs', heading: 'Webhooks with signature verification', anchor: '#webhooks-with-signature-verification', text: 'PluginApiRequest.rawBody carries the unparsed payload:' },
  { path: '/developers/plugins/guides/server-apis', title: 'Guide: server APIs, webhooks & jobs', heading: 'Platform billing events', anchor: '#platform-billing-events', text: 'Your handler receives the platform\'s Stripe events (with requestHost for callback URLs). Throwing propagates to a 500 and Stripe redelivers — write idempotent handlers.' },
  { path: '/developers/plugins/guides/server-apis', title: 'Guide: server APIs, webhooks & jobs', heading: 'Scheduled jobs', anchor: '#scheduled-jobs', text: 'The deployment\'s scheduler POSTs /api/plugins/run-jobs with the x-plugin-jobs-secret header (PLUGINJOBSSECRET); due jobs run error-isolated, and last-run marks persist across cold starts. Keep handlers bounded (limits, no unbounded scans) — they share the API process.' },
  { path: '/developers/plugins/guides/server-apis', title: 'Guide: server APIs, webhooks & jobs', heading: 'Troubleshooting', anchor: '#troubleshooting', text: '- 404 on your route: path prefix not in apiPrefixes, plugin disabled for the target workspace, or its release flag is off (staff bearer tokens bypass for preview). - Webhook signature failures: you parsed body instead of verifying rawBody. - Job never runs: PLUGINJOBSSECRET unset (route 501s) or the scheduler isn\'t POSTing; the route\'s response lists every registered job and what ran.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: '', anchor: '', text: '# Plugins & Marketplace Plugins extend Aglyn with new components and capabilities. You install them from the organization marketplace (Marketplace in the org navigation), configure them per site, and they run sandboxed so they can\'t compromise your site. The marketplace lives at the organization level rather than inside each site. Its own Navigation panel lists Browse All and Installed; publishers additionally get Upload / Publish, Publisher Profile, Listings, Payouts and Sales. Marketplace is now purely the market. Turning plugins on and off for the workspace moved out to its own Plugins section in the org navigation, next to Marketplace. Installed remains as a convenience for uninstalling something you just installed — every row links through to Plugins. :::info Plan availability Free to install marketplace plugins; some plugins and marketplace monetization features are paid.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'Install & upgrade', anchor: '#install--upgrade', text: '- Open Marketplace in the organization navigation and Browse the listings. Browse is a catalogue: cards link to the detail page, which is the only place an install happens, and a confirmation dialog names exactly where it will land before anything is written. - When you install a plugin, choose where it applies: All sites (organization-wide — including sites you add later) or Selected sites (a specific subset). Components, templates and layouts are site-scoped, so "All sites" installs them onto every current site and does not cover sites added later. - Installs are version-pinned, and you can upgrade deliberately. - Installed plugins appear as named entries in the Besigner drawer, alongside built-in components. - Manage everything from the marketplace\'s Installed tab: first-party plugin toggles (with release state), per-plugin configuration, plus every marketplace install with upgrade, uninstall, and share-with-organization actions. A listing\'s own detail page also carries Uninstall (or Uninstall org-wide) once you have it installed. - Rating a listing needs a verified email and an organization that actually installed it; commenting is open to any signed-in user. - Installing enables the plugin for the workspace automatically; uninstalling disables it once no site keeps its own pin. Uninstalling never deletes the data a plugin created — reinstall and it picks up where it left off.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'What the badges on a listing mean', anchor: '#what-the-badges-on-a-listing-mean', text: 'Two badges can appear on a listing, and they say different things. Read them as two separate claims, because that is what they are (AGL-1121). | Badge | What Aglyn is claiming | What it survives | | --- | --- | --- | | Verified publisher | A human at Aglyn confirmed who the publisher is, and that their listing describes what their code does. | A version bump. It is a claim about the publisher, not about any particular release. | | Reviewed | A human at Aglyn read these exact bytes — the version currently on offer — against a required checklist. | Nothing. It is re-earned per version, so a new release starts without it. | So a new release from a verified publisher shows Verified publisher but not Reviewed, and that is honest rather than a gap: we vouch for the person, and nobody has read this particular code yet. Neither badge is a security guarantee. Every plugin runs in the same sandbox with the same limits whether it is badged or not, and installability is identical — a listed plugin is installable by every workspace regardless. The badges tell you how much human attention this listing has had, not whether the code is safe. A listing with neither badge is not necessarily suspect; it may simply be new. It does mean nobody at Aglyn has looked at it, so read the publisher and the docs before installing.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'How plugins run', anchor: '#how-plugins-run', text: '- Each plugin loads into a sandboxed PluginFrame host runtime, isolated by origin. - A manifest + sandbox bridge protocol defines what a plugin can do. - A host-mediated network bridge lets plugins make network calls without direct access to your environment. - See Sandbox security model for what that isolation actually enforces — including the per-plugin network policy — if you\'re writing one. - Your workspace decides which plugins are enabled at all, and a site admin can narrow that further per site from the site\'s Admin → Plugins page. A plugin disabled for a site disappears from that site\'s navigation, editor, published pages, and API — other sites in the workspace are unaffected, and a site can never enable a plugin the workspace has switched off.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'Configure', anchor: '#configure', text: 'Plugins expose a settings field for per-plugin configuration, so the same plugin can behave differently on each site.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'Publish your own', anchor: '#publish-your-own', text: 'The publish + install pipeline lets developers ship plugins to the marketplace with version pinning. The marketplace marketplace also supports paid listings, Stripe Connect payouts, and a publisher ledger.' },
  { path: '/developers/plugins/overview', title: 'Plugins & Marketplace', heading: 'Related', anchor: '#related', text: '- The Besigner - Site templates & block library - Building feature plugins — the developer guide to every extension surface - Repo docs: docs/PLUGINLOADING.md (loading architecture and trust tiers) and docs/PLUGINPLATFORMGAPS.md (competitive analysis and the v2 roadmap)' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: '', anchor: '', text: '# Publish a plugin :::tip This page covers the mechanics; the complete marketplace guide — review process, listing authoring, versioning, payouts — is the Publisher handbook. Built something reusable? Publish it to the marketplace marketplace so other Aglyn users can install it — free or paid. :::info Plan availability Publishing is open to developers; paid listings use Stripe Connect for payouts.' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: 'The publish pipeline', anchor: '#the-publish-pipeline', text: 'Plugins go through a publish + install pipeline with version pinning, so installs are reproducible and upgrades are deliberate: 1. Package your plugin against the manifest + sandbox bridge protocol (see Plugins overview). 2. Verify locally: node tools/scripts/verify-plugin-bundle.mjs dist/plugin.bundle.mjs — the publish API enforces the same checks. 3. Publish a version to the marketplace: Marketplace → Publish → "A plugin (upload a bundle)" → Publish a plugin… — a page at / /marketplace/publish/plugin where you upload the bundle and its manifest.json, choose who can install it, and set the listing details, repository URL and price. What you type is kept as a local draft until you publish; the files are not, so re-choose them. You confirm a short pre-publish checklist — repository, license, data disclosure, network hosts, testing — which is recorded against that exact bundle and shown to the reviewer. Uploads publish sandboxed; staff review lists (and may sign) them. 4. Installers get that pinned version and choose when to upgrade — ship updates by bumping the manifest version and uploading again.' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: 'Private plugins', anchor: '#private-plugins', text: 'Not everything you build is for sale. When you upload a bundle, Who can install this offers: - Anyone — publish to the marketplace. The default. Listed for every workspace once a reviewer approves it. - Only this organization — private plugin. Never listed in the marketplace, for anyone, and installable only by your own sites. Private is a choice about audience, not about trust. A private plugin still executes on Aglyn infrastructure and still reaches the host ABI, so it goes through the identical pipeline: the same review queue, the same reviewer checklist, the same bundle verifier, and the same super-staff signature if it ever needs realm trust. It is not a way to ship unreviewed code. Private plugins are always free — nobody else can install them — and you reach yours from Marketplace → Listings, not from Browse. A private plugin can go public later from that same Listings tab. The bytes were already approved, so it needs no re-review; it does need what any marketplace listing needs first — a description, a README, and a license. Going back to private is always available.' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: 'Paid listings', anchor: '#paid-listings', text: 'You can list a plugin as paid: - Payments run through Stripe Connect. - Earnings are tracked in a publisher ledger.' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: 'Your publisher profile', anchor: '#your-publisher-profile', text: 'Your publisher profile is a storefront: its own page in the marketplace listing everything you\'ve published, reachable from the Publisher card on any of your listings and from the by @handle link on every browse card. Buyers who like one of your plugins use it to find the rest, so the handle, display name, and bio you set are worth the same care as a listing.' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: 'Tips', anchor: '#tips', text: '- Bump versions intentionally — installers stay on their pinned version until they upgrade. - Keep the manifest\'s declared capabilities minimal; the sandbox enforces them.' },
  { path: '/developers/plugins/publish-a-plugin', title: 'Publish a plugin', heading: 'Related', anchor: '#related', text: '- Plugins & marketplace' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: '', anchor: '', text: '# Publisher handbook Everything a marketplace publisher needs. The developer side (building the bundle) is the first-plugin guide; this is the marketplace side.' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Before your first publish', anchor: '#before-your-first-publish', text: '1. Publisher profile (Marketplace → Profile) — your handle and display name appear on every listing. Publishing is organization-owned: the listing belongs to your organization, not your personal account. 2. Publisher agreement (Marketplace → Profile) — accept it once, on behalf of the organization. See The publisher agreement. 3. Plan: publishing requires a Pro plan. 4. Payouts (paid listings only): complete Stripe Connect onboarding from Marketplace → Payouts. The platform fee is 20% (30% on free plans).' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'The publisher agreement', anchor: '#the-publisher-agreement', text: 'Your organization — not you personally — is the publishing party, so the organization accepts the Marketplace Publisher Agreement once, from Marketplace → Profile. Only an owner or admin can accept it, because only they can bind the organization, and we record who accepted it and when. You can read the agreement in full at aglyn.com/legal/marketplace-publisher-agreement, alongside the rest of the legal centre. The version in force is stated at the top of that page, and it is the same string the panel records against your acceptance. It is a different thing from the pre-publish checklist, and they are not interchangeable: | | Publisher agreement | Pre-publish checklist | | --- | --- | --- | | About | The relationship | The bytes in this bundle | | Scope | Your organization | One version | | Asked | Once, and again when the terms change | Every publish, including a republish of the same version number | The summary shown above the accept button is the part that tends to surprise people later — the license you grant us to host, verify and distribute; what you warrant about each version; that you cannot recall code already installed; that we can disable a version everywhere without notice if it looks dangerous; that review is a safety screen and not an endorsement; and that on paid listings we process the sale, pay your share into your own Stripe Connect account less a platform fee, and collect and remit sales tax — while refunds, chargebacks and support on your artifacts stay with you. Read the full agreement before accepting. If we change the agreement, publishing stops until someone who can bind your organization reads and accepts the new version. An older acceptance is never carried forward — that is the whole reason the agreement is versioned. Nothing already published' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Where to publish from', anchor: '#where-to-publish-from', text: 'Publishing lives at the organization level — Marketplace → Publish. Pick a source site, then what to publish: - A component — a reusable component from that site. - A layout — a published layout from that site. - A dataset schema — the field model of one of your organization\'s datasets. Records are never published — only the structure travels. - An email template — a transactional email you\'ve designed for that site (only emails that already have a saved design are offered). - This entire site — its published screens and theme, as an installable template. Dataset schemas are the one exception to the source-site picker: datasets belong to the organization rather than to a site, so the picker is hidden and the schema publishes from the org directly. The per-site shortcuts still exist for convenience — the Publish actions on a site\'s Components and Layouts pages, and Publish as template on the Setup page — and open the same listing form. ### What installing each type does Installing never changes a running site. What that means per type: | Type | Where it lands | Live immediately? | | --- | --- | --- | | Component | The site\'s components | Yes, once you place it | | Layout / Site template | The site\'s Templates library | No | | Plugin | An org or per-site version pin | Yes | | Dataset schema | A new, empty dataset in the org | Yes (it\'s new) | | Email template | A draft version of that email | No | Two details worth knowing before you publish one: - A dataset schema installs as a brand-new dataset every time; it never merges into an existing one, since a schema change over existing rows would reinterpret live data. reference fields are relinked to the installing organization\'s datasets by display name, and any that can\'t be matched are degraded to plain text — the installe' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Publishing a version', anchor: '#publishing-a-version', text: 'Run the local verifier first — the publish API enforces the same checks and rejects with the exact problem list: The verifier parses your bundle rather than reading it as text, so it sees what a source scan could not: property access computed at runtime on globalThis/window/document, the Function constructor reached through .constructor(), and import() with a specifier it cannot resolve. All of those are refused. Declare every origin you call. The verifier collects your fetch, XMLHttpRequest, WebSocket and sendBeacon calls and diffs them against capabilities.network in your manifest; an origin you call but do not declare fails the publish. This is the same list your plugin\'s CSP is built from, so an undeclared call would have been blocked at runtime anyway — failing here means you find out at publish time instead of in production. A URL your code only knows at runtime cannot be checked, so it is reported as a warning and a reviewer will ask about it. Calling through a local name does not change the answer: const f = fetch, const d = globalThis.fetch and const {fetch: h} = globalThis are all resolved back to fetch, and a URL kept in a constant — a plain string, a template, or a concatenation of them — is read rather than shrugged at. What is not read is a name that gets reassigned, shadowed by a parameter or declared twice; there the value at the call site would be a guess, so the call is reported as a URL known only at runtime. If you hand a URL to a helper the checker cannot follow, it says so rather than reporting no network calls — so declare the origins your plugin talks to and the row goes quiet on its own. Pass the manifest (as above, or leave it beside your bundle or one level up) or the network checks can only warn locally while the publish API still rejects. It' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Review: what happens after you publish', anchor: '#review-what-happens-after-you-publish', text: 'New plugin listings enter the queue as submitted and don\'t appear in public browse until staff list them. Reviewers see your listing content, declared capabilities, and a fresh static-verification run. Outcomes: - Listed — publicly browsable. - Verified publisher ✅ — a badge on you, not on any one release. See below. - Rejected — you\'re notified with the reason; fix and republish. - Realm trust (separate, rare): staff may additionally sign a version so it runs in the app realm instead of the sandbox — first-party-grade placement for plugins that earn it. ### The two badges, and what each one promises The marketplace shows two separate claims, because they answer different questions and conflating them would let one vouch for the other: | Badge | What it means | Scope | | --- | --- | --- | | Verified publisher | A human at Aglyn confirmed who you are and that your listing describes what your code does. | The publisher. It survives a version bump. | | Reviewed | A reviewer completed the checklist against these exact bytes ({version, sha256}). | That one version. | Publishing a new version clears the Reviewed badge and puts the release back in the queue — including on a listing whose publisher is already verified. That is deliberate: the badge is a statement about code someone read, so it cannot follow code nobody has. Your Verified publisher badge is unaffected by a version bump. Buyers see both, so a new release from a verified publisher reads honestly: we vouch for you, and we have not read this release yet. Until a version is Reviewed, its listing page carries the standard "review the publisher and docs before installing" note. Being a verified publisher does not remove it — the plugin still runs sandboxed either way. Speed the review up: a real README, a license, sane' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Private plugins', anchor: '#private-plugins', text: 'Choose Only this organization under Who can install this when you upload, and the listing becomes private: never browsable in the marketplace by anyone, and installable only by your own organization\'s sites. That last part is enforced when the install is requested, not by hiding the page — knowing a private listing\'s id gets a stranger nowhere. Private changes the audience, not the bar. Your bundle still runs on Aglyn infrastructure and still reaches the host ABI, so it goes through the same queue, the same reviewer checklist, the same static verifier, and the same super-staff signature if it ever needs realm trust. Staff see private submissions in the queue marked Private. Private plugins are always free, and you find yours under Marketplace → Listings rather than in Browse — View opens the same detail page you install from. Going public later takes no re-review: the bytes were already approved, and who may install them was never part of that approval. It does ask for what any marketplace listing needs first — a description, a README, and a license — via Make public on the Listings row. Going back to private is always available and takes effect immediately.' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Authoring your listing', anchor: '#authoring-your-listing', text: 'Your listing IS your storefront — it renders on the detail page every buyer sees. Editable at publish time or any time after, no republish needed: open Edit listing on your own listing\'s detail page (the whole page becomes the editor), or use the Edit action on Marketplace → Listings. | Field | Guidance | | --- | --- | | Name | The display name on every browse card and at the top of the detail page; ≤80 chars. A typo here is fixable without republishing — leaving it blank keeps the current name rather than clearing it. | | Description | The one-line summary under the name on browse cards; ≤500 chars. | | Body (About) | The main docs: what it does, setup, what it adds, data & permissions. Rich-text editor with headings, bold/italic, links, and inline images; ≤20k chars. | | Preview image | The hero shown on browse cards and at the top of the detail page — pick it from your media library. | | Logo | Square; pick from the media library or paste an https URL. | | Screenshots | Up to 6, from the media library or https URLs; the detail page shows a gallery with click-to-zoom. | | Categories | Up to 3 from the fixed taxonomy. | | License | Short label (e.g. MIT) — listings without one get flagged in review. | | Homepage / repository | Public links build trust; reviewers check them. The repository is asked for at publish and required — editing it here changes the listing, not what past versions declared. | Be explicit about data & permissions in the README: what your plugin reads/writes and every host in your manifest\'s network allowlist — unverified sandbox listings show buyers a risk disclaimer, and good docs are what overcomes it.' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Versioning & updates', anchor: '#versioning--updates', text: '### Shipping a new version Publish new version on your listing — the button on the listing\'s own detail page, or the action in the row menu on Marketplace → Listings. It opens the same publish page bound to that listing, so you upload the new bundle and manifest and write a changelog rather than describing a listing you already own; name, description, README, license, repository and price arrive filled in from the listing and are yours to edit. What the page tells you, because it is the part worth knowing: the version that installs today keeps installing until a reviewer approves the new one. Nobody is upgraded onto unreviewed code, and nothing you publish can change a version somebody already has. Two things it will stop you on: - A mismatched manifest id. An update is recognised by your publisher organization plus the manifest id — so a bundle carrying a different id would create a separate listing, not a new version. The page says so and refuses rather than letting you find out from a duplicate listing you cannot un-publish the bytes of. - The changelog confirmation. On an update the pre-publish checklist asks for it up front, because here we know it applies. Who can install it is fixed when the listing is created and a new version never changes it — change that from the listing itself. - Artifacts are immutable and installs pin {version, sha256} — you can never change the code a consumer runs; ship a new version instead. - Users update explicitly (an Update to vX action appears when your latestVersion passes their pin). Write a changelog every publish — it renders in the detail page\'s Version history card, where every published version is listed with its changelog, a Latest marker, and a Realm-trusted chip on versions that carry it. That card is what a cautious buye' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'How installs work (the buyer side)', anchor: '#how-installs-work-the-buyer-side', text: 'Browse is a catalogue — cards link to the detail page, which is the only place an install happens. The buyer picks targets (all sites, selected sites, or org-wide for plugins), confirms a dialog that names exactly where the install lands, and the pin is written: your exact {version, sha256} pinned to the site or org, the plugin enabled for the workspace, loaded on their next visit. Buyers can uninstall from the listing\'s own detail page (Uninstall, or Uninstall org-wide for an org-scope pin) as well as from Marketplace → Installed — removing the pin and disabling it. Data your plugin created stays, so reinstalls resume cleanly. Paid listings require purchase before install; you see sales in your publisher ledger. The detail page shows two install figures side by side: installs is the cumulative all-time total and only ever grows, while active counts the organizations and sites that currently hold a pin — it goes down when someone uninstalls. A big gap between the two is churn worth investigating. Every listing shows its artifact type as a chip — Plugin, Component, Site template, Layout, Dataset schema, or Email template — so buyers know what they\'re getting before they open it. Dataset schemas and email templates read "Added (v1) · add again" rather than "Installed", because adding one creates a new dataset or a new draft email each time; re-adding is a legitimate action, not a no-op. Ratings and comments: any signed-in user can comment on your listing; star ratings are reserved for verified-email accounts in an organization that actually installed it. The publishing organization can never rate or comment on its own listing.' },
  { path: '/developers/plugins/publishing/publisher-handbook', title: 'Publisher handbook', heading: 'Getting paid', anchor: '#getting-paid', text: 'One-time prices in whole USD (up to $1000). Purchases flow through the platform\'s Stripe; your share (80%, or 70% on free plans) pays out via your Connect account. The Marketplace → Sales tab tracks every sale.' },
  { path: '/developers/plugins/reference/extension-points', title: 'Extension-point catalog', heading: '', anchor: '', text: '# Extension-point catalog The surface matrix: what a plugin can extend, from which entry (barrel = client, /server = API process), and when it runs. | Extension point | Entry | Reaches | Runs | | --- | --- | --- | --- | | Canvas components (defineUiFeatureBundle) | barrel (site) | Besigner + published sites | Editor gates / SSR-suspended page load | | Console nav + pages (ConsoleExtension.navItems) | barrel (console) | Console host area | After the org resolves, before the shell paints | | Widgets (ConsoleExtension.widgets) | barrel (console) | Named console zones (dashboard, org, settings, admin, besigner) | With their host page | | Providers (ConsoleExtension.providers) | barrel (console) | Around every console page | Once the registry is populated | | Site runtimes (registerSiteRuntime) | barrel (site) | Every published page | Client render, reading enricher props | | Redirect resolvers / page resolvers / enrichers | /server | Tenant page pipeline | Per request, in that order; enricher errors isolated | | API routes (registerPluginApiRoute) | /server | /api/ on both apps | Per request behind the org + release gates | | Billing webhook handlers | /server | Platform Stripe events | Per event; errors → redelivery | | Config schemas (registerPluginConfigSchema) | both | Settings UI + typed reads | Declared at module scope | | Custom field types (registerCustomFieldType) | both | Dataset schema/record editors + validation | Declared at module scope | | Permissions (registerPluginPermissions) | both | Every resolved role set | Declared at module scope | | Scheduled jobs (registerPluginJob) | /server | The platform job beat | When due, via /api/plugins/run-jobs | | Install preset mappers | barrel | Besigner drawer presets | On install-doc render | | Realm bundles (register(' },
  { path: '/developers/plugins/reference/injection-zones', title: 'Injection zones', heading: '', anchor: '', text: '# Injection zones Register a widget with ConsoleExtension.widgets: [{ slot, widgetId, title?, Component }]; the shell renders it through PluginWidgetSlot. The guaranteed zones are the exported CONSOLEWIDGETSLOTS catalog — slot stays an open string so custom zones don\'t need a core release. | Zone | Where it renders | Props your widget receives | | --- | --- | --- | | hostActivity | Host dashboard + screen-view activity column | hostId, max?, viewAllHref? | | commerceGlance | Host dashboard commerce summary | hostId | | orgData | Organization → Data page body | orgId, org | | besignerFunctions | Besigner ƒx panel | hostId | | marketplaceListing | Marketplace listing detail body | hostId, listingId, permissions | | orgAddons | Plugins & add-ons hub, installs section | hostId (the acting site) | | dashboardFooter | Bottom of the host dashboard | hostId | | orgSettings | Organization → Settings, below the tabs | orgId, org | | hostSettings | Host setup page, below the built-in cards | hostId | | adminOrgDetail | Staff admin org detail page (staff-only) | orgId | Rules of thumb: widgets receive shell-resolved context as props and must not reach for console-app hooks; data access goes through @aglyn/tenant-feature-instance (useFirestoreCollection, useUser, usePluginConfig, …). A widget renders for a workspace only when its plugin is enabled and released — the shell never mounts widgets from unloaded plugins.' },
  { path: '/developers/plugins/reference/manifest-and-envs', title: 'Manifests, trust lifecycle & environment', heading: '', anchor: '', text: '# Manifests, trust lifecycle & environment' },
  { path: '/developers/plugins/reference/manifest-and-envs', title: 'Manifests, trust lifecycle & environment', heading: 'Plugin manifest (published with every version)', anchor: '#plugin-manifest-published-with-every-version', text: 'Validation is server-side (validatePluginManifest) — invalid manifests never publish. capabilities are enforced by the sandbox tier: the plugin origin stamps a CSP from network, the bridge drops undeclared props and events.' },
  { path: '/developers/plugins/reference/manifest-and-envs', title: 'Manifests, trust lifecycle & environment', heading: 'Listing & version documents', anchor: '#listing--version-documents', text: '- marketplaceListings/{listingId} — public: displayName, description, categories[] (fixed taxonomy), logoUrl, screenshots[], readme (markdown), homepageUrl, repositoryUrl, license, priceUsd, latestVersion, installCount (cumulative installs ever), activeInstalls (installs live right now — the detail page shows both, e.g. 41 installs · 12 active), reviewStatus. - marketplaceListings/{id}/pluginVersions/{version} — server-only: sha256, objectPath, manifest, changelog, trust?, signature?. The buyer-safe subset (version/changelog/trust/hostAbi/date) is exposed by GET /api/marketplace/listing-versions. - Installs pin {version, sha256} at hosts/{hostId}/installs/{listingId} (host tier) or orgs/{orgId}/installs/{listingId} (org tier). Artifacts are immutable content-addressed objects: artifacts/{listingId}/{version}/{sha256}.bundle.' },
  { path: '/developers/plugins/reference/manifest-and-envs', title: 'Manifests, trust lifecycle & environment', heading: 'Review & trust lifecycle', anchor: '#review--trust-lifecycle', text: '- listed/verified (or legacy/absent) plugin listings appear in browse; everything else is owner-and-staff-only. Verified adds the ✅ badge. - Realm trust is separate and orthogonal: a super-staff signature over a version\'s sha256 (POST /api/admin/sign-plugin) sets trust: \'realm\', letting that version load into the app realm. The revocations/{listingId} kill switch beats everything.' },
  { path: '/developers/plugins/reference/manifest-and-envs', title: 'Manifests, trust lifecycle & environment', heading: 'Environment variables', anchor: '#environment-variables', text: '| Variable | Runtime | Purpose | | --- | --- | --- | | NEXTPUBLICPLUGINORIGIN | client + server | Dedicated plugin origin: serves /load (sandbox) and /artifacts/... (realm fetches) | | PLUGINARTIFACTSBASE | server | Optional server-side artifacts base override | | PLUGINARTIFACTSBUCKET | console server | Isolated bucket the publish flow writes to | | NEXTPUBLICPLUGINTRUSTPUBLICKEY | client | Ed25519 public key (base64 raw); when set, client realm loads require valid signatures | | PLUGINTRUSTPUBLICKEY | server | Same key, server loaders (mandatory there) | | PLUGINTRUSTPRIVATEKEY | console server only | Signing key (base64 PKCS8 DER) for the staff sign-plugin route | | PLUGINREMOTESERVER | server | enabled turns on remote server bundles (default off everywhere) | | PLUGINREMOTESERVERBUNDLES | server | Per-deploy listingId@version allowlist | | PLUGINJOBSSECRET | tenant server | Shared secret the scheduler sends to /api/plugins/run-jobs | | NEXTPUBLICPLUGINDEVBUNDLES | client, dev only | Unverified localhost bundle loading for the authoring loop; dead code in production builds |' },
  { path: '/developers/plugins/reference/manifest-and-envs', title: 'Manifests, trust lifecycle & environment', heading: '`plugins.config.json` (first-party contributors)', anchor: '#pluginsconfigjson-first-party-contributors', text: 'The single source mapping plugin ids to packages, register entry points per surface (site, console, tenantApi, consoleApi), and apiPrefixes. node tools/scripts/generate-plugin-manifests.mjs turns it into the four generated loader manifests — the only files allowed to reference @aglyn/plugins- outside libs/plugins (an nx boundary rule enforces this). The scaffolder (tools/scripts/create-plugin.mjs) maintains it for you; the manual follow-ups are the FIRSTPARTYPLUGINS catalog entry and the release flag (registry + Remote Config template).' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: '', anchor: '', text: '# Plugin-manager API reference Everything a plugin registers goes through libs/aglyn/src/lib/plugin-manager, re-exported from @aglyn/aglyn (client + isomorphic) and @aglyn/aglyn/server (adds the server-only loaders). Hand-written by design: the surface is small and curated, and each entry needs semantics (ordering, caching, failure behavior) that generated signatures can\'t carry.' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Console extensions — `feature-plugins`', anchor: '#console-extensions--feature-plugins', text: '| API | What it does | | --- | --- | | registerConsoleExtension(extension) | Declares everything a plugin adds to the console shell. Idempotent by pluginId (re-registration replaces). | | listConsoleNavItems() / resolveConsolePluginPage(href) | How the shell renders nav + serves plugin pages under /[hostId]/[pluginSlug]. | | listConsoleWidgets(slot) | Widgets registered for a named zone — see Injection zones. | | listConsoleProviders() | App-level providers mounted around every console page. | | defineUiFeatureBundle(options, components) | Site/canvas component bundle; auto-depends on the base mui bundle. Component and bundle ids are persisted in screen docs — never rename. | | CONSOLEWIDGETSLOTS | The typed injection-zone catalog. | ConsoleExtension fields: pluginId, displayName, featureFlag? (plan-entitlement gate the shell applies — extensions cannot bypass plans), navItems? (a nav item with a Component becomes a full page and receives ConsolePluginPageProps { hostId, entitled, org?, permissions? }), dashboardCards?, settingsSections?, widgets?, providers?.' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Loading — `plugin-loader`', anchor: '#loading--plugin-loader', text: '| API | Semantics | | --- | --- | | createPluginLoader(manifest) | One loader per generated manifest; loads are cached per plugin, registrations once per plugin+surface. | | loader.ensure(ids, surfaces) | Loads + registers the given plugins\' surfaces. Returns a stable promise per (ids, surfaces) so React use() can suspend on it during SSR — the canvas never renders against an empty registry. Unknown ids are ignored (marketplace realm plugins load separately); alwaysOn entries activate regardless. | | loader.ensureAll(surfaces) | Every manifest plugin — the API dispatchers\' lazy-load-all. | | loader.pluginIdForApiPath(path) | Prefix-map fallback for the per-request org gate. | Lifecycle: all register fns in an ensure batch run first, then each module\'s optional bootstrap () export runs (manifest order, once per plugin+surface, failures logged not fatal) — the sanctioned place for cross-plugin wiring. Plugins loaded by a later ensure bootstrap in that batch, so read registries lazily rather than snapshotting.' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Server APIs — `api-plugins` (`/server` only)', anchor: '#server-apis--api-plugins-server-only', text: '| API | Semantics | | --- | --- | | registerPluginApiRoute(path, handler) | Registers an exact path under the [...pluginApi] dispatchers. Ownership is recorded at registration time for the per-request org gate — a disabled plugin\'s paths 404 for that workspace. | | PluginApiRequest | { method, query, body, headers, rawBody? } — rawBody carries the unparsed payload for Stripe/Svix signature verification. |' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Site pipeline — `site-runtime`, `site-page-hooks` (`/server` for hooks)', anchor: '#site-pipeline--site-runtime-site-page-hooks-server-for-hooks', text: '| API | Semantics | | --- | --- | | registerSiteRuntime({runtimeId, Component}) | Components rendered on every published page (overlay engines, experiment runners); they read back the props their server enricher wrote. | | registerSiteRedirectResolver(fn) | Runs before route resolution; first non-null redirect wins. | | registerSitePageResolver(fn) | Composes plugin-owned pages (commerce PDP/PLP). | | registerSitePageEnricher(fn) | Contributes page-prop slices; enricher errors are isolated — a broken plugin drops its slice, never the page. |' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Billing — `billing-webhook-hooks` (`/server`)', anchor: '#billing--billing-webhook-hooks-server', text: 'registerBillingWebhookHandler(eventTypePrefix, handler) — receives the platform Stripe events. Handler errors propagate to a 500 so Stripe redelivers; make handlers idempotent.' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Enablement, flags, config, fields, permissions, jobs', anchor: '#enablement-flags-config-fields-permissions-jobs', text: '| API | Semantics | | --- | --- | | resolveEnabledPlugins(org) | The org switchboard: absent field → all first-party; always-on unioned in; unknown (marketplace) ids kept. | | filterPluginsByReleaseFlags(ids, isFlagOn, {staffBypass}) | Subtracts release-flagged-off first-party plugins (AGL-422). | | registerPluginConfigSchema(schema) / mergePluginConfig / validatePluginConfigValues | Per-plugin settings: declared once, generic form + typed defaults-merged reads everywhere (AGL-428). | | registerCustomFieldType(fieldType) / validateCustomFieldValue | Dataset field types riding existing storage types (AGL-434). | | registerPluginPermissions(list) | Role-resolved permission keys with per-tier defaults (AGL-435). | | registerPluginJob(job) / runPluginJobs(due?) | Scheduled jobs run by the guarded /api/plugins/run-jobs route (AGL-435). | | registerPluginInstallPresetMapper(fn) | Maps marketplace install docs to besigner drawer presets. |' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Remote bundles — `realm-plugins` (isomorphic), `realm-server` (`/server`)', anchor: '#remote-bundles--realm-plugins-isomorphic-realm-server-server', text: '| API | Semantics | | --- | --- | | PLUGINHOSTABIVERSION / setRealmPluginHost(host) | The AGLYNPLUGINHOST ABI slot; the app composes it from its own React/jsxRuntime/registry singletons. | | verifyRealmBundle(bytes, install, publicKey?) | sha256 pin always; Ed25519 signature mandatory when a key is configured (fails closed). | | loadRealmPlugins(installs, {artifactsBase, publicKeyBase64}) | Fetch → verify → blob-URL import → register(host). Cached per listing@version; ABI mismatches refused; per-bundle failures logged and skipped. | | loadRemoteServerBundles(source) | Env-gated server tier (default OFF); returns what loaded so callers can audit. | | isCompatibleHostAbi(hostAbi?) | The ABI gate: undeclared = legacy (allowed with a warning). |' },
  { path: '/developers/plugins/reference/plugin-manager-api', title: 'Plugin-manager API reference', heading: 'Sandbox — `plugin-bridge`', anchor: '#sandbox--plugin-bridge', text: 'The versioned postMessage protocol between the host PluginFrame and a sandboxed bundle: parseGuestMessage (origin/source/schema-validated), filterPluginProps (manifest allowlist), message types ready/init/ props/resize/event/fetch-request/fetch-response/error. The bridge never evals or grafts anything from the frame — sized output and named events only; network goes through the host-mediated fetch (server-side allowlist re-check).' },
  { path: '/developers/plugins/reference/sandbox-security', title: 'Sandbox security model', heading: '', anchor: '', text: '# Sandbox security model Marketplace plugins run sandboxed by default: in an iframe on a separate origin, with a Content-Security-Policy built from your own manifest. This page is what that means in practice, because most of it only becomes visible when something you wrote doesn\'t work. The alternative tier — realm bundles, which run in the host realm — is covered in Realm bundles.' },
  { path: '/developers/plugins/reference/sandbox-security', title: 'Sandbox security model', heading: 'A separate origin', anchor: '#a-separate-origin', text: 'Sandbox iframes are served from plugins.aglyn.com, not from the console or the site. That\'s a different origin, so the browser itself — not our code — is what stops a plugin from touching the host page\'s DOM, cookies, or storage. Everything a sandboxed plugin does to the outside world goes through the bridge: declared props in, declared events out. Undeclared props are dropped before your code sees them, and undeclared events are dropped before the host does. The loader only allows framing from the console, .aglyn.app sites, and each site\'s verified custom domain — so your plugin renders on a customer\'s own domain exactly as it does on their aglyn.app address.' },
  { path: '/developers/plugins/reference/sandbox-security', title: 'Sandbox security model', heading: 'Per-manifest network policy', anchor: '#per-manifest-network-policy', text: 'This is the one that surprises people. The loader stamps a CSP whose connect-src is \'self\' plus exactly the origins you declared in your manifest\'s capabilities.network. A fetch to anywhere else is blocked by the browser. With that manifest, fetch(\'https://api.example.com/…\') works and fetch(\'https://api.other.com/…\') does not. :::warning The failure mode is a CSP error, not a 4xx A blocked request never reaches the network. You\'ll see a CSP violation in the browser console and a rejected promise — not an HTTP status. If a request "just fails" with no response, check your manifest\'s network list first. If the manifest lookup fails for any reason, the loader falls back to \'self\' — the strict end. It never fails open. ### When you can\'t declare the origin Declaring every origin up front doesn\'t fit every case — a URL the site owner configures, or an API that redirects across hosts. For those, use the host-mediated hostFetch escape hatch: the request is made by the host, subject to its own rules, and the response is handed back over the bridge. See Server APIs.' },
  { path: '/developers/plugins/reference/sandbox-security', title: 'Sandbox security model', heading: 'Pinned, immutable artifacts', anchor: '#pinned-immutable-artifacts', text: 'Bundles are streamed from a private bucket at /artifacts/{listing}/{version}/{sha}.bundle, and every consumer verifies the sha256 before running a byte of it. Installs pin {version, sha256}, so: - You can never change the code an existing install runs. Ship a new version. - A tampered artifact fails the hash check and doesn\'t execute. - "Update to vX" is always an explicit act by the person who installed it.' },
  { path: '/developers/plugins/reference/sandbox-security', title: 'Sandbox security model', heading: 'What this means when you build', anchor: '#what-this-means-when-you-build', text: '- Declare network honestly and minimally. It\'s both your allowlist and a disclosure buyers read — an over-broad list costs you trust in review. - Test in the sandbox, not just locally. A plugin that works against a dev server with no CSP will hit the policy the moment it\'s published. - Document data & permissions in your README. Unverified sandbox listings show buyers a risk disclaimer; clear docs are what overcomes it. - Don\'t reach for realm trust to dodge the CSP. Realm trust is granted by Aglyn staff for a specific reviewed version, not on request.' },
  { path: '/developers/plugins/reference/sandbox-security', title: 'Sandbox security model', heading: 'Related', anchor: '#related', text: '- Manifest & environments — the capabilities block. - Realm bundles — the trusted tier and how trust is granted. - Publisher handbook — review expectations.' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: '', anchor: '', text: '# Self-hosting Aglyn Aglyn is Apache-2.0 and the whole platform is public on GitHub. You can run it yourself with Docker on any infrastructure — a cloud VM, a VPS, or bare metal. :::note What self-hosting v1 means You run the same code Aglyn\'s cloud runs, pointed at your own Firebase project (Google account required — the free tier is fine to start) plus your own Stripe and Resend keys. A fully vendor-neutral backend that removes the Firebase dependency is a separate roadmap track.' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'The short version', anchor: '#the-short-version', text: '- Console (the management app) on http://localhost:4200 - Tenant runtime on http://localhost:4500 — a specific site is served at .localhost:4500; the bare port serves the demo tenant. :::caution Don\'t skip the rules deploy A stack that boots without the security rules deployed is a stack whose data is not protected the way the application assumes. The three scripts talk to Firebase\'s rules API directly using your service-account credentials — no firebase login needed. (cp .env.selfhost .env will overwrite an existing .env — back yours up first if you develop in the same checkout.) Put your own reverse proxy (Caddy, nginx, Traefik) in front: one hostname for the console, and your site hostnames routed to the tenant runtime.' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'The full runbook', anchor: '#the-full-runbook', text: 'The complete, always-current runbook lives in the repository: docs/SELFHOSTING.md. It covers: 1. Creating your Firebase project (Auth, Firestore, Storage, Realtime Database, and Remote Config) and minting a service account. 2. Deploying the repo\'s security rules to your project with the bundled scripts. 3. Filling in .env.selfhost — which values are baked into the client at image-build time versus read at runtime. 4. Reverse-proxy setup for the console and the tenant runtime.' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'Who runs this install', anchor: '#who-runs-this-install', text: 'Two values are not optional in the way the keys below are, because leaving them out changes what your users and third parties are told about who is responsible for your site: They name you on the public abuse intake (/api/report-abuse), the §512 counter-notice intake (/api/counter-notice), the lockdown 503, the media quarantine notice and the sanctions 451. These pages ship with the software and the first two are unauthenticated — a copyright holder or a browser vendor can reach them without an account. There is deliberately no fallback to Aglyn\'s addresses. Earlier builds hardcoded them, which meant a self-hosted deployment published a DMCA intake directing statutory notices to Aglyn — about content Aglyn does not host and cannot remove. Unset now renders an explicit "not configured" state instead. Because these are NEXTPUBLIC, they are compiled into the client bundles. Set them before docker compose build, not just before up. ### Your DMCA position is your own The counter-notice flow, the 10–14 business-day put-back clock and the repeat-infringer strike ledger all work on your install. Aglyn\'s designated agent registration does not extend to you: §512(c)(2) makes registering an agent with the U.S. Copyright Office a precondition of the safe harbour rather than a formality. So NEXTPUBLICOPERATORDMCAAGENT defaults to unset, unset means the product claims nothing, and NEXTPUBLICOPERATORDMCAAGENTREGISTERED must be exactly true before anything states a registration. Naming an agent never implies one.' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'Optional keys', anchor: '#optional-keys', text: 'The example env file carries the required Firebase blocks plus a handful of optional integrations. The related features degrade gracefully — a missing key disables its feature rather than breaking the stack: | Feature | Keys | | --- | --- | | Billing & commerce checkout | STRIPESECRETKEY, plus NEXTPUBLICSTRIPEPUBLISHABLEKEY, STRIPEWEBHOOKSECRET, and the STRIPEPRICE price ids if you want working plan checkout — the secret key alone is not enough | | Transactional & campaign email | RESENDAPIKEY, USAGEEMAILFROM | | AI assist | ANTHROPICAPIKEY | | Scheduled jobs (audit archival, erasure runs) | CRONSECRET — the job routes stay dormant without it |' },
  { path: '/developers/self-hosting', title: 'Self-hosting', heading: 'Honest limits', anchor: '#honest-limits', text: '| Area | Self-hosted behavior | | --- | --- | | Firebase | Required — Auth, Firestore, Storage, RTDB, and Remote Config run in your project. | | Custom-domain self-service | The in-console attach flow is Vercel-specific; self-hosters attach domains at their reverse proxy instead. | | Wildcard published-site domains | Host resolution for arbitrary public hostnames currently assumes the hosted platform — plan on per-site proxy rules rather than a single wildcard, and expect this area to improve. | | Stripe / Resend / AI assist | Optional keys (see above); the related features degrade gracefully when absent. | | Operator identity | Set NEXTPUBLICOPERATORNAME and NEXTPUBLICOPERATORSUPPORTEMAIL — the public abuse and §512 intakes name them, there is no Aglyn fallback, and unset renders "not configured". Baked in at image build time. | | DMCA designated agent | Not inherited from Aglyn. Register your own with the U.S. Copyright Office; the product asserts a registration only when you set NEXTPUBLICOPERATORDMCAAGENTREGISTERED=true. | | Legal documents | Signup still clickwraps your users to Aglyn LLC\'s Terms, hash-pinned to snapshots in the repository. NEXTPUBLICOPERATORLEGALORIGIN records your own legal origin but does not yet retarget the acceptance flow. | | Documentation citations | AI-assist citations deep-link to docs.aglyn.com unless NEXTPUBLICDOCSORIGIN names your own build. | | Updates | git pull && docker compose up --build, re-running the rules deploy when CHANGELOG.md records a rules change. Releases are v git tags; git describe --tags --match \'v\' tells you which one you are on. |' },
  { path: '/enterprise/overview', title: 'Enterprise overview', heading: '', anchor: '', text: '# Enterprise overview Enterprise is the only plan that is not self-serve. It is quoted rather than listed, and it is the plan the pages in this section describe. | | | | --- | --- | | Single sign-on | SAML SSO against your identity provider, optionally enforced so passwords stop working. | | Support commitments | A 24–48 hour first-response commitment measured in clock hours, and a named success manager. | | Availability & status | What we measure, what /status shows, and what we have not committed to. | | Security & compliance | The material a security review needs, including what we do not have. |' },
  { path: '/enterprise/overview', title: 'Enterprise overview', heading: 'What Enterprise does not change', anchor: '#what-enterprise-does-not-change', text: 'Worth saying plainly, because it is the usual assumption: - Quotas and features are entitlements, not plan names. An Enterprise workspace can have any combination of limits, and they are set per organization rather than implied by the tier. - The product is the same product. Enterprise is about how we contract, respond and authenticate — not a separate build.' },
  { path: '/enterprise/overview', title: 'Enterprise overview', heading: 'Getting Enterprise', anchor: '#getting-enterprise', text: 'Contact us. SSO in particular is provisioned on our side (see Single sign-on), so it is not something you can switch on from Organization → Settings the way a plan upgrade works.' },
  { path: '/enterprise/security-and-compliance', title: 'Security & compliance', heading: '', anchor: '', text: '# Security & compliance The full write-up lives on Trust & security. It is written for the security review that precedes an enterprise purchase, and it is kept as one page on purpose — a reviewer should be able to send a single link rather than assemble an answer from several.' },
  { path: '/enterprise/security-and-compliance', title: 'Security & compliance', heading: 'What it covers', anchor: '#what-it-covers', text: '- What we do not have, first rather than buried: no SOC 2 report and no audit in progress, no ISO 27001 / HIPAA / FedRAMP, no third-party penetration test, no bug bounty. - Authentication, including SSO, and how sessions work. - Data handling — where data lives, what is encrypted, and who can reach it. - Availability, and the fact that there is no committed uptime percentage (see Availability & status). - How to report a security issue.' },
  { path: '/enterprise/security-and-compliance', title: 'Security & compliance', heading: 'Why the gaps are listed first', anchor: '#why-the-gaps-are-listed-first', text: 'Because a reviewer needs them, and because a questionnaire surfaces them anyway — three weeks later, with more people in the thread. Leading with the absences is faster for both sides than leading with the controls. If a certification is a hard requirement for your purchase, raise it at the start. We would rather tell you early that we do not have it than discover it at contract stage.' },
  { path: '/enterprise/security-and-compliance', title: 'Security & compliance', heading: 'Reporting a vulnerability', anchor: '#reporting-a-vulnerability', text: 'Security reports are read even though there is no bug bounty. The reporting route is on Trust & security.' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: '', anchor: '', text: '# Single sign-on (SAML) SSO signs your team in against your own identity provider. It is an Enterprise feature, and once your organization is on Enterprise you set it up yourself in Organization → Settings → Single sign-on. There is no provisioning step on our side and nothing to wait for.' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: 'Setting it up', anchor: '#setting-it-up', text: '### 1. Verify your domain Add each email domain your team signs in with. We give you a DNS TXT record to publish: | Record | Value | | --- | --- | | aglyn-challenge.yourdomain.com | aglyn-domain-verification=… | Publish it at your DNS provider, then press Verify. DNS can take a few minutes to propagate; re-checking is safe and costs nothing. This step is not a formality. A verified domain is what tells us to send that domain\'s sign-ins to your identity provider. If anyone could claim a domain without proving they own it, they could point your domain at their IdP and intercept your team\'s logins. So nothing else works until a domain passes, and we re-check the record rather than taking your word for it. Public mailbox domains — gmail.com, outlook.com and the like — cannot be used. They are shared with millions of people outside your organization. ### 2. Connect your identity provider The settings page shows the two values your IdP asks for when you create the Aglyn application: - Reply / ACS URL - Entity ID / Audience Create the application in your IdP, then paste its details back: the entity ID, the sign-in URL (which must be https://), and the X.509 signing certificate. Saving creates your identity pool and its SAML provider. Saving does not switch anything on. Your configuration sits inactive until you turn it on, so a half-entered setup can never start routing sign-ins. ### 3. Turn it on Once at least one domain is verified and your provider is saved, Turn on publishes the routing for your verified domains and SSO goes live. Turning it off later stops the routing but keeps your identity pool and every account in it, so you can turn it back on without anyone losing their account.' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: 'How it works', anchor: '#how-it-works', text: 'Each SSO organization gets its own identity pool. Your users authenticate against your IdP, and their Aglyn accounts live in that pool rather than in the shared one. That isolation is the point — your directory governs who can sign in, and removing someone there removes their access here. Signing in goes through a dedicated route rather than the normal email/password form, so people arrive by way of your IdP.' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: 'Enforcement', anchor: '#enforcement', text: 'An organization can turn on SSO enforcement, which is a separate step from having SSO configured. - Configured, not enforced — SSO is available, and other sign-in methods still work. - Enforced — other sign-in methods are stripped from accounts in the pool. Passwords stop being an option, not merely a discouraged one. Enforcement is applied by a sweep over the pool. Rehearse it first — the settings page has a rehearsal that changes nothing and lists exactly which accounts would lose which sign-in methods. An account whose only way in is the method being removed is reported and skipped rather than orphaned. Enforcement cannot be undone by turning it off. We remove a linked credential; we do not keep a copy to put back. Anyone affected re-links for themselves.' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: 'Consequences worth knowing before you switch', anchor: '#consequences-worth-knowing-before-you-switch', text: 'Passwords cannot be set for SSO accounts. The console refuses rather than silently doing nothing — your IdP owns the credential. SSO users are in a separate pool. This is the isolation working, but it has practical effects the platform has to account for explicitly: an SSO user is not returned by ordinary account lookups unless the lookup searches every pool. Staff surfaces label these accounts with the pool they belong to, so "can\'t find them" and "they\'re an SSO account" are distinguishable. Social sign-in cannot be linked to an SSO account at all. Not automatically, and not by the user either — the option is not offered, and the account page says why. Your identity provider is the single gate you bought: you revoke there, you enforce MFA there, you offboard there. A personal Google account linked to a governed identity would be a way in that your directory can neither see nor revoke, so we do not allow one to be created. This holds whether or not you have turned enforcement on. Enforcement decides whether we remove sign-in methods that already exist; it was never a licence to keep handing out new ones in the meantime. Nothing about this can lock anyone out, because refusing to add a method never takes away a method someone already has. An account in your pool is also simply not the same identity as the same email address signing in with Google elsewhere, so the two never merge.' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: 'Testing it', anchor: '#testing-it', text: 'SSO redirects cannot be exercised from localhost — the flow fails with a missing-initial-state error before it reaches your IdP. Test on a deployed environment.' },
  { path: '/enterprise/sso', title: 'Single sign-on (SAML)', heading: 'Related', anchor: '#related', text: '- Signing in and sessions - Trust & security — the security posture behind an enterprise review' },
  { path: '/enterprise/support-tiers', title: 'Support commitments', heading: '', anchor: '', text: '# Support commitments Every plan gets the community forum. Private ticket support starts at Pro — Free and Starter pay for product, not for our time. The commitment below is a first response, not a resolution. It is what the Support tickets page shows you, and what the staff queue is ordered by. | Plan | Tier | First response | Named success manager | | --- | --- | --- | --- | | Free | Community | Forum only | — | | Starter | Community | Forum only | — | | Pro | Standard | 7–14 business days | — | | Business | Business | 4–6 business days | — | | Scale | Business | 4–6 business days | — | | Advanced | Business | 4–6 business days | — | | Agency | Priority | 1–3 business days | — | | Enterprise | Dedicated | 24–48 hours | Yes |' },
  { path: '/enterprise/support-tiers', title: 'Support commitments', heading: 'Why Enterprise is in hours, not business days', anchor: '#why-enterprise-is-in-hours-not-business-days', text: 'It is the point of the tier. 24–48 clock hours runs through a weekend; "1–3 business days" does not. Read as business hours the Enterprise window would be 3–6 business days, which would make it slower than Agency above and invert the ladder. There is a test asserting the ladder stays monotonic, so this cannot quietly regress into the wrong order.' },
  { path: '/enterprise/support-tiers', title: 'Support commitments', heading: 'What starts and stops the clock', anchor: '#what-starts-and-stops-the-clock', text: '- The clock starts when you open the ticket. - It stops on the first reply from the Aglyn team — write-once, so a later staff message does not reset or re-stamp it. - A reply from you does not stop it. If we have not answered yet, the commitment is still running.' },
  { path: '/enterprise/support-tiers', title: 'Support commitments', heading: 'Where to see it', anchor: '#where-to-see-it', text: 'Organization → Support → Support tickets, reached from Support in the org tabs or in your account menu. On a plan that carries tickets that is where Support opens; on Free and Starter it opens on the forum, with a link across. The page states your own commitment rather than a generic promise, so what you read there is what your plan actually carries. Your plan is per organization. If you belong to more than one, the commitment follows the workspace you are looking at — not your account.' },
  { path: '/enterprise/uptime-and-status', title: 'Availability & status', heading: '', anchor: '', text: '# Availability & status' },
  { path: '/enterprise/uptime-and-status', title: 'Availability & status', heading: 'The status page', anchor: '#the-status-page', text: 'status.aglyn.com checks the console and the published-site runtime live, when you load it. It shows whether each surface is responding right now. It does not show uptime history or an availability percentage — nothing stores historical samples yet, so a number there would be invented rather than measured.' },
  { path: '/enterprise/uptime-and-status', title: 'Availability & status', heading: 'There is no committed uptime percentage', anchor: '#there-is-no-committed-uptime-percentage', text: 'Stated plainly because procurement asks, and because a vague answer wastes everyone\'s time: > We have not published an uptime SLA. We measure availability and intend to commit to a number backed by that data — rather than one chosen to close a deal. Until there is enough history to stand behind, there is no percentage to quote, and we would rather say so than publish a figure we cannot evidence. If a committed availability figure is a hard procurement requirement today, that is worth raising early rather than late. See Trust & security for the same list from the reviewer\'s side.' },
  { path: '/enterprise/uptime-and-status', title: 'Availability & status', heading: 'Where the platform runs', anchor: '#where-the-platform-runs', text: 'Published sites and the console are served from a global edge network, with data in Google Cloud Firestore. A published page is served from cache and regenerated in the background, so a slow origin degrades to a stale page rather than an error.' },
  { path: '/enterprise/uptime-and-status', title: 'Availability & status', heading: 'Reporting an outage', anchor: '#reporting-an-outage', text: 'If something is down and /status disagrees, tell us — the status page checks reachability, which is not the same as everything working. Open a ticket from Organization → Support → Support tickets. Response is governed by your support commitment; Enterprise is 24–48 clock hours.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: '', anchor: '', text: '# Aglyn Assist :::caution Rolling out Aglyn Assist is being rolled out and may not be switched on for your workspace yet. Nothing needs configuring — the helper appears in the console as the rollout reaches you. Aglyn Assist is the chat helper in the bottom-right corner of every console page. Ask it how to do something — publish a screen, connect a domain, set up shipping, invite a teammate — and it answers from this documentation, linking the exact docs section and the console page where you do it.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'What it can do', anchor: '#what-it-can-do', text: '- Answer how-to questions about building sites, publishing, domains, commerce, bookings, workflows, datasets, team roles, and billing. - Link you to the source — every answer cites the docs pages it drew from, so you can read the full guide. - Guide you on the page you\'re on (Pro plans and up) — the assistant knows which console screen you\'re viewing and answers about that screen, rather than giving you a general answer you then have to translate. - Offer to take you to the right page (Pro plans and up) — when what you asked for starts somewhere else, it can show a card that opens that page for you. See Offers to open a page. Aglyn Assist answers and directs — it doesn\'t change anything in your workspace. It can\'t edit your site, publish, or update settings, so there\'s nothing it can do by accident; you stay in control of every change.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'Answers for beginners and developers', anchor: '#answers-for-beginners-and-developers', text: 'Every answer is written twice over, in one message. The main answer is in plain words: what to click, in the order you\'ll click it, with nothing assumed about what you already know. Underneath, when there\'s something technical worth adding — the URL of the page, the identifier in it, the field or API behind the screen — there\'s a collapsed Under the hood line. Open it if you want that detail; ignore it entirely if you don\'t. Nothing is hidden from you and nothing is explained at you.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'Offers to open a page', anchor: '#offers-to-open-a-page', text: 'Sometimes the thing you asked about starts on a different screen. When the assistant knows which one, it shows a small card offering to take you there — with the values to use, when it has worked them out from your question. The card only opens the page. It never fills in a form for you, never saves anything, and never makes a change on your behalf. You land on the normal screen, fill it in yourself, and press the button yourself — with all the usual permission checks in place. If you\'d rather stay where you are, choose No thanks and the card goes away. This is deliberate. An assistant that could change your site by misunderstanding you would be a worse assistant, so it doesn\'t have that ability at all — not a setting that\'s switched off, but a capability it was never given.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'Message limits', anchor: '#message-limits', text: '- Free workspaces get a limited number of assistant messages each day, with answers and docs links. - Pro and higher plans get generous limits, page-aware guidance, and the offers to open a page described above. When a free workspace reaches its daily limit, the assistant says so and the counter resets the next day (UTC).' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'Feedback', anchor: '#feedback', text: 'Every answer offers a thumbs-up / thumbs-down. Ratings tell us which answers — and which docs — need work, so rating answers directly improves the product.' },
  { path: '/getting-started/aglyn-assist', title: 'Aglyn Assist', heading: 'Privacy', anchor: '#privacy', text: 'Conversations with Aglyn Assist are stored with your workspace so we can improve answers and documentation. See the privacy policy for details on how this data is handled.' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: '', anchor: '', text: '# The console tour The console is where you manage a site. Here\'s what each part of the chrome does. 1. App bar — the Aglyn console wordmark, notifications, and your account menu. 2. Workspace switcher — jump between the organizations you belong to. 3. Site sections — every area of the selected site (Dashboard, Screens, Media, Content, …). 4. Site switcher — switch between the sites in your workspace. 5. Page body — the selected section\'s cards and tables.' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'The app bar', anchor: '#the-app-bar', text: '- Site switcher (left) — jump between the sites you belong to, search them by name with Find site…, or create a new one. - Breadcrumbs — show the current site\'s display name and where you are. - Screen switcher — a searchable dropdown for hopping between screens without leaving the editor: your recent screens by default, or type to find any screen or layout in the site by name. View all screens opens the full list. - Version dropdown (right, near your avatar) — pick or schedule a version to view. - Notifications — the bell shows an unread badge and drops down your 10 most recent notifications (form submissions, bookings, invoices, team changes), split across an Inbox tab (unread) and an Archive tab (already read). Mark all read clears the inbox, the gear opens your notification preferences, and View all opens the full paginated feed. - Account menu — your avatar opens it. The header shows your name and email, with a gear to Manage Account; below that are Manage Team, Billing, Support, Staff console (Aglyn staff only), and a Documentation link that opens this docs site in a new tab. It also holds the theme toggle (light / system / dark), an Upgrade plan button — shown only when your workspace has a higher plan to move to, and only to members who can open Billing — Sign out, and a footer naming your current workspace and plan.' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'In-context help', anchor: '#in-context-help', text: 'Look for the small ? icons throughout the console — next to page titles, card titles, form fields, table column headers, and the Besigner\'s style and attribute panels. Hover one for a one- or two-line explanation, and click it (or the Open documentation link in the tooltip) to jump straight to the matching section of these docs in a new tab.' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'Primary navigation', anchor: '#primary-navigation', text: 'The tabs across the top of a site are its sections. Some are always present; the rest are contributed by the plugins your workspace has enabled — so two sites, or the same site before and after you enable a plugin, can show different tabs. Don\'t be surprised by a tab strip that doesn\'t match a screenshot exactly. These four are where a new site\'s work happens: | Section | What\'s there | | --- | --- | | Dashboard | The site at a glance — analytics and recent-signup summaries, and the ten most recent activity entries. | | Screens | The screen hierarchy — create, reorder (drag-and-drop), and open screens. This is where you build; start at Publish your first screen. | | Media | The media library — folders, images, video, and files. | | Setup | Basic details, SEO, theme, custom domain, emails, and the full activity log. Each tab is deep-linkable — the ?tab= in the URL follows you, so you can bookmark or share the exact one. | Alongside them, and always present: Layouts and Components (the shared frames and reusable pieces screens are assembled from — see Screens & Layouts), Templates (saved starting points), Content (collections and blog entries), Users (the people who sign in to the site you\'re building, not your own team), and Analytics. Admin appears only if you\'re an owner or admin of the site; it holds per-site plugin settings and the danger zone. :::note Sections that come and go Tabs such as Data, Products, Logic, Workflows, Inbox, Bookings, Events, Redirects, Marketing and Marketplace are contributed by plugins and appear only where that plugin is enabled for your workspace (they\'re inserted after Analytics). If a section these docs describe isn\'t in your tab strip, that\'s usually why — enable the plugin under Organization → Plugins. Contacts is the exception: it\'s a' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'Editing vs. managing', anchor: '#editing-vs-managing', text: 'You can manage a screen (rename, schedule, view raw JSON) from its detail page without opening the editor. When you want to design it, open the Besigner.' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'A site\'s dashboard', anchor: '#a-sites-dashboard', text: 'Opening a site lands you on its dashboard. It\'s a place to glance at the site, not to edit it — every card is a summary with a link to the section that owns the detail: - Traffic — pageviews over a window you choose (14 days by default). View details opens Analytics. - Newest site users — the five most recent people who signed up on your site. View all opens Users. - Recent Activity — the ten most recent changes, each naming the thing that changed ("Saved the screen — Home") and linking straight to it. The full, paginated log lives under Setup → Activity. Plugins contribute the rest, so this list is a floor rather than an exact match for your own dashboard: Last campaign appears once you\'ve sent an email campaign, and Commerce where the commerce plugin is enabled and the site has products or orders. A brand-new site shows the same cards with empty states — "No pageviews recorded yet", "No activity yet" — which is what a first visit should look like. Two things people expect here and won\'t find: role management lives under Users, and the announcement bar and promotional popup live under Marketing.' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'Next', anchor: '#next', text: '- Publish your first screen' },
  { path: '/getting-started/console-tour', title: 'The console tour', heading: 'Workspace settings & notifications', anchor: '#workspace-settings--notifications', text: 'Organization-wide settings (name, workspace URL) live under Organization → Settings, which also holds Profile, API keys, Branding, Single sign-on, Ownership and Delete. Turning plugins on and off for the workspace is its own section, Organization → Plugins — Marketplace is for finding and installing new ones, not for administering what you already run: Your in-app notification feed — billing, publishing, workflow failures — lives under Notifications, with per-category mutes: ### Alerts on this device Below the category mutes, three switches control how a new notification reaches you in this browser: - Unread count in tab title — badges the browser tab, e.g. (3) Aglyn, so you can see new activity from another tab. On by default. - Sound — a short chime when a notification arrives. On by default on a browser you haven\'t set it on before; a device where you already turned it off keeps your choice. - Desktop notifications — a system notification, shown only while the Aglyn tab is in the background (in the foreground, the bell and chime already tell you). Off by default; switching it on asks your browser for permission. If you previously blocked notifications for the site, re-allow them in your browser settings first. These are per-device, not per-account: notification permission is granted per browser, so muting sound on your laptop leaves your other devices alone. The category mutes above are account-wide and apply everywhere. Send test alert plays the chime and, if you\'ve allowed them, fires a desktop notification — so you can confirm your setup works instead of discovering weeks later that you never heard a thing. The chime always plays, even with Sound switched off, so you can hear it before deciding. Aglyn asks you in-app before triggering your browser\'s own permission' },
  { path: '/getting-started/create-a-site', title: 'Create a site', heading: '', anchor: '', text: '# Create a site A site is one website you own in Aglyn — its screens, theme, data, domain, and settings. Everything you build lives under a site, and you can own several.' },
  { path: '/getting-started/create-a-site', title: 'Create a site', heading: 'Create your first site', anchor: '#create-your-first-site', text: '1. Sign in to the console. 2. Open the site switcher in the app bar (top-left) and choose Create site. 3. Give it a name. Aglyn generates a working subdomain immediately, so the site has a real address from the first moment — you can attach a custom domain later. The address resolves right away, but it has nothing to serve until you publish a screen at the site root, so a brand-new site answers its own URL with a not-found page. Starting from a starter template creates and publishes a home page for you; building by hand, that\'s your first screen. 4. You land on the new site\'s Setup page (titled Host Setup), with tabs for Basic details, SEO, Theme, Custom Domain, Emails, and Activity. To start building rather than configuring, use the Screens tab in the site navigation — see Publish your first screen. :::tip Name collisions Site names must be unique enough to generate a valid subdomain. If a name is taken, the console suggests an available variation.' },
  { path: '/getting-started/create-a-site', title: 'Create a site', heading: 'What a site contains', anchor: '#what-a-site-contains', text: '- Screens & layouts — the pages and the shared frames they render in. - Data — datasets, variables, functions, and workflows. - Media — images, video, and files, organized in folders. - Setup — theme, custom domain, SEO, and integrations under tabbed settings. The Site logo card (Details tab) sets your brand mark: it\'s shown on the live site\'s page-navigation loading overlay — a themed, blurred scrim with a progress bar. Without a logo, the loader shows your site name instead. - Billing — the plan and usage meters that gate features and quotas.' },
  { path: '/getting-started/create-a-site', title: 'Create a site', heading: 'Switching between sites', anchor: '#switching-between-sites', text: 'Use the site switcher in the app bar at any time. It lists your most recently used sites first; with more than a handful, type in the Find site… box to search every site you belong to by name, or choose View all sites. Your current site\'s display name appears in the breadcrumbs so you always know which site you\'re editing.' },
  { path: '/getting-started/create-a-site', title: 'Create a site', heading: 'Next', anchor: '#next', text: '- Take the console tour - Publish your first screen' },
  { path: '/getting-started/publish-your-first-screen', title: 'Publish your first screen', heading: '', anchor: '', text: '# Publish your first screen This walks through the core loop: create → design → publish. :::tip Publish from the editor You don\'t have to leave the Besigner to go live: the Publish button in the top-right of the editor publishes the version you\'re editing (and flips to Unpublish once the screen is live). Screens without a URL path yet are prompted to set one in Properties first.' },
  { path: '/getting-started/publish-your-first-screen', title: 'Publish your first screen', heading: '1. Create a screen', anchor: '#1-create-a-screen', text: '1. Go to Screens and choose New screen. 2. Set a title and a URL slug (e.g. about). Aglyn normalizes the slug and registers it in the site\'s routing map. 3. Optionally pick a parent screen — children inherit a nested URL path (/services/pricing).' },
  { path: '/getting-started/publish-your-first-screen', title: 'Publish your first screen', heading: '2. Design it in the Besigner', anchor: '#2-design-it-in-the-besigner', text: '1. Open the screen to launch the Besigner. 2. Drag components from the drawer onto the canvas. Rearrange them in the hierarchy panel or directly on the canvas. 3. Double-click text to edit it inline. Set component attributes in the inspector. 4. Bind a shared layout if you want a common header/footer.' },
  { path: '/getting-started/publish-your-first-screen', title: 'Publish your first screen', heading: '3. Preview and publish', anchor: '#3-preview-and-publish', text: '1. Use the artboard light/dark toggle to check both color schemes. 2. Save the canvas. Saving writes your working version — it isn\'t publishing. 3. Publish. The screen\'s slug is registered in the routing map and the page goes live on your site\'s domain. :::info Keeping more than one version is a Pro feature Every screen is created with one working version, and Save updates that version on every plan — the core loop above needs nothing extra. Keeping more than one — named snapshots you can reopen, publish to roll back to, or schedule — requires Pro or above, and scheduling a version requires Business or above. On Free and Starter the editor answers "Versioning requires a Pro plan — see Billing to upgrade" instead of opening the name dialog. See Versions & scheduled publishing. :::tip The Live button The Live button is environment-aware — in production it reflects your published saves so you can jump straight to the real page.' },
  { path: '/getting-started/publish-your-first-screen', title: 'Publish your first screen', heading: 'How fast changes go live', anchor: '#how-fast-changes-go-live', text: '- Publishing a screen refreshes its live page immediately — the very next visitor gets the new version, usually within seconds. - Publishing a layout or a reusable component refreshes every page that uses it the same way. When that fan-out is very large, the publish confirms that the remaining pages "update on their own within a minute" — and they do. - Saving is not publishing. A save writes your working version; the live site serves the published one. The one subtle case: if you edit the version that is currently live and press Save, the live site catches up on its own within about a minute — and because pages regenerate behind the scenes, you may need to refresh twice to see it. - Your site\'s sitemap.xml, robots.txt, and RSS feeds refresh within about five minutes (a publish refreshes the sitemap immediately).' },
  { path: '/getting-started/publish-your-first-screen', title: 'Publish your first screen', heading: 'Next', anchor: '#next', text: 'Explore the feature areas in the sidebar, or see What\'s New for the latest capabilities.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '', anchor: '', text: '# Build & publish a survey This walkthrough strings together datasets, the Besigner\'s form elements, and publishing into one loop: model the responses → design the survey → publish → collect. By the end you have a live survey page whose submissions land in a typed dataset you can filter, sort, and export. :::info Plan availability Forms and the inbox are available on every plan. Writing submissions into a dataset needs the data store, which unlocks on Starter and above.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '1. Create the dataset', anchor: '#1-create-the-dataset', text: 'Datasets belong to your organization, so every site can share them. Open the organization Data page (or any site\'s Data page — both edit the same data). 1. Choose Add dataset. In the New dataset dialog give it a Name (say Survey responses) and an optional comma-separated starting list of Fields (satisfaction, visit, topics, comments). Create it. 2. Select your new dataset in the Dataset dropdown and open Schema. The Schema dialog lists each field with its display name, generated field id, and a type chip. 3. Use Add field / Edit to type the fields properly: - satisfaction → type Integer (the star rating submits a number). - visit → type Text (one radio choice). - topics → type Text (ticked checkboxes arrive joined with , ). - comments → type Text. 4. Save schema. Each field\'s Display name is what you see in dialogs and table headers; the field id next to it (a slug generated once from the display name) is the stable key records store values under — the key {{item.fieldId}} bindings reference, and what a form field\'s Maps to schema field picker stores. Renaming the display name later never changes the id. :::tip Model first A clean schema now makes everything downstream typed: the record editor renders the right input per field, imports are validated, and quota-guarded writes reject junk. See the datasets deep-dive for the full type system.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '2. Add a screen for the survey', anchor: '#2-add-a-screen-for-the-survey', text: '1. Go to Screens and choose New screen. 2. Title it Survey and give it the slug survey — that becomes its public URL path (https://your-site/survey). 3. Open it in the Besigner.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '3. Insert a Form from the element picker', anchor: '#3-insert-a-form-from-the-element-picker', text: 'With the screen open, add the form: 1. In the Elements panel choose Add Element (or right-click a node and pick Add element). The Choose element picker opens, grouped by category. 2. Expand the Forms group. It contains the Form container, the Form Field element, and a ready-made Contact Form preset. 3. Insert a Form. Then, with the Form selected, add one Form Field child per question (the picker\'s Form Field preset drops a field with sensible defaults).' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '4. Configure the fields', anchor: '#4-configure-the-fields', text: 'Select each Form Field and set its properties in the inspector: | Property | What it does | | --- | --- | | Field name | The key the value is stored under in submissions (and in the inbox copy). | | Maps to schema field | Which of the dataset\'s schema fields this value is stored under. The dropdown lists the fields of the dataset chosen on the Form (see step 5) and stores the stable field id, so renaming the field later never breaks the mapping. Left on None, the value matches a dataset field by name instead. | | Label | The visible input label ("How satisfied are you?"). | | Placeholder | An optional grey hint inside the empty input ("you@company.com"). It is not a label — it disappears as soon as someone types, so always keep Label set. Radio, checkbox, and rating fields ignore it; a dropdown shows it until a choice is made. Clear it to remove the hint. | | Type | Text (default), Email, Multiline, Dropdown, Radio choice, Checkboxes, or Star rating. | | Options | Choices for dropdown, radio, and checkbox fields — one per line or comma-separated. Ignored by other types. | | Required? | Whether the field must be filled; a required checkbox group needs at least one box ticked. | :::tip Pick the dataset first "Maps to schema field" lists the fields of whichever dataset the Form is pointed at — set the Form\'s Write to dataset (step 5) before mapping the fields, or the dropdown reads No dataset selected on the form. For this survey: 1. satisfaction — Type Star rating, label "How satisfied are you?". The five stars submit a number (4). 2. visit — Type Radio choice, Options First time, Monthly, Weekly. 3. topics — Type Checkboxes, Options Products, Support, Pricing. Visitors can tick several; the submission joins them with , . 4. comments — Type Multiline for free-form feedbac' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '5. Point the form at the dataset', anchor: '#5-point-the-form-at-the-dataset', text: 'Select the Form container itself and fill its properties: - Form name — identifies the form in your submissions inbox (Visitor survey). - Write to dataset — pick Survey responses from the dropdown, which lists your organization\'s datasets by display name. The form stores the dataset\'s id, so renaming the dataset later never breaks the binding. Submissions append a record; the inbox always keeps its own copy either way. - Submit label — the button text (defaults to Send). - Success message — shown in place of the form after a successful submit. :::info Rename-safe by id Both pickers bind by stable id: the Form stores the dataset\'s document id and each field\'s "Maps to schema field" stores the model field id. Rename the dataset or its fields freely — records keep landing. Unmapped values still match schema fields by name (field name = field id); values that match nothing are dropped from the record (the inbox copy still has everything). Forms built before the pickers keep working through their stored dataset name — shown as Write to dataset (legacy name) until you pick the dataset above and clear it.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '6. Publish', anchor: '#6-publish', text: 'Click Publish in the Besigner\'s top-right (it flips to Unpublish once live). If the screen has no URL path yet you\'re prompted to set one first. The survey is now served at /survey on your site\'s domain.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: '7. Watch responses arrive', anchor: '#7-watch-responses-arrive', text: 'Every submission does three things: - appends a record to Survey responses — the Data page updates live; - files an inbox copy under the form\'s name (see Forms & lead capture); - fires the formSubmission automation event, so workflows and actions can react (send a thank-you alert, notify your team, write other datasets). On the Data page, use Filter (satisfaction >= 4) and Sort (satisfaction desc) over the loaded records, and export everything with the CSV / JSON buttons. :::tip Chart it Bind a container\'s Repeat over dataset to Survey responses and reference {{item.satisfaction}} inside it to render responses back onto a (members-only?) results screen. The deep-dive covers repeatables.' },
  { path: '/guides/build-and-publish-a-survey', title: 'Build & publish a survey', heading: 'Related', anchor: '#related', text: '- Datasets & schema deep-dive - Forms & lead capture - Publish your first screen - Workflows & actions' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '', anchor: '', text: '# Launch a coming-soon page while the rest of your site stays private You have a domain, a half-built site, and a launch date. You want visitors to land on something deliberate — "here\'s what\'s coming, tell me when it\'s ready" — while the forty pages behind it stay out of Google until you\'re happy with them. This walkthrough is the whole loop: build the page → make it home → hide the rest → collect signups → flip everything back on launch day. It\'s the same pattern Aglyn uses on its own site. :::info Plan availability Everything here works on Free: screens, forms, the inbox, per-screen visibility, and the site-wide search switch. Writing signups into a dataset (step 4) needs the data store, which unlocks on Starter and above — the inbox copy is always kept either way.' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '1. Build the coming-soon page', anchor: '#1-build-the-coming-soon-page', text: 'Create the screen first; you\'ll point your domain at it in step 2. 1. Go to Screens → New screen. Title it Coming soon. Give it any slug for now — coming-soon is fine — you\'ll change it to / in the next step. 2. Open it in the Besigner and put the essentials on it. A coming-soon page that only says "coming soon" wastes the visit. Aim for: - What\'s coming, and roughly when. One sentence and a month beats a countdown timer you\'ll have to move. - A notify-me form — see below. - How to reach a human. An email address or a contact link; people who arrive early are often the ones who most want to talk to you. - Links out — your documentation, your changelog, your social accounts, wherever you already post. These give an early visitor somewhere to go instead of bouncing. 3. Publish the screen. ### The notify-me form Add a Form from the element picker with a single Form Field of type Email, and set the Form\'s Success message to something that confirms the signup ("Thanks — we\'ll email you when we open"). The Forms & lead capture page covers the form elements and every field property in full; the only thing that matters here is that you give the field a Field name you\'ll recognise later, such as email.' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '2. Make it the home page', anchor: '#2-make-it-the-home-page', text: 'A screen\'s Slug decides the path it\'s served at, and the slug / means the home page. So swapping your home page is two slug edits. :::caution Change the slug, don\'t delete the screen Move your existing home page aside rather than deleting it. Its design, its content, and its version history are all worth keeping, and you\'ll want it back in step 5. 1. Open your current home screen (Sites → your site → Screens → click the row). In the Publishing card, change Slug from / to something you\'ll recognise — home works — and choose Update route. The screen stays published, just at /home now. 2. Open the Coming soon screen. Change its Slug to / and choose Update route (or Publish, if you haven\'t published it yet). 3. Load your site. The coming-soon page is now what visitors get. A screen can be the home page or have a parent, but not both — if the slug won\'t take, check that the screen sits at the top level of your screens list. :::caution Changing a slug does not create a redirect Aglyn rewrites its own routing map when you change a slug, so links within your site keep working. It does not leave a redirect behind at the old path — that URL simply stops resolving. If the old path was public and people have linked to it, create the rule yourself with the redirect manager (a paid feature) — see Create a redirect.' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '3. Keep everything else out of search', anchor: '#3-keep-everything-else-out-of-search', text: 'Your unfinished pages are still published and still reachable. Two controls decide whether search engines index them, and which one you want depends on how far along you are. ### While nothing is ready: the site-wide switch Go to Setup → SEO and turn on Discourage search engines from indexing this site. One switch, whole site: - robots.txt refuses every crawler (Disallow: /) and stops naming your sitemap - sitemap.xml is served empty - every page — including your coming-soon page — carries This is the right choice while the site is a building site. It also covers pages you haven\'t created yet, which per-screen visibility can\'t: a screen you publish next Tuesday is indexable by default, so a site hidden page-by-page slowly un-hides itself as it grows. While the switch is on, a warning banner follows you through the console on every page of that site. That\'s deliberate, and it\'s the answer to the most common support question this feature creates — see step 5. ### Once you\'re launching page by page: per-screen visibility When the site is mostly ready and you\'re releasing sections, turn the site-wide switch off and hide the stragglers individually. Open a screen (Screens → pick it) and use the Visibility dropdown in its Page Access card: | Visibility | Reachable by | In search | | --- | --- | --- | | Public | anyone | yes | | Unlisted | anyone with the link | no | | Password protected | anyone with the password | no | | Members only | signed-in members | no | Unlisted is the one you want for a finished-but-not-announced page: it stays live so you can share the link with a reviewer, and it\'s kept out of both search results and your sitemap. :::caution noindex is a request, not a lock Unlisted and the site-wide switch ask search engines not to list a page. Well-behaved crawle' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '4. Collect the signups', anchor: '#4-collect-the-signups', text: 'Every form submission is filed in your Inbox under the form\'s name, on every plan. That alone is enough to email people on launch day. To get a list you can actually query, point the form at a dataset: 1. Create a dataset on the organization Data page → Add dataset, called Launch signups, with a field for the address — email. 2. Back in the Besigner, select the Form container and set Write to dataset to Launch signups in the Attributes panel. 3. Select the email Form Field and set Maps to schema field to email. That mapping is what makes the record land, and it\'s worth doing explicitly. The picker stores the dataset field\'s stable Reference ID, so renaming the field later never breaks it. Left on None (match by field name), the value falls back to matching a dataset field whose Reference ID — the snakecase key beside each field in the Schema dialog, not its Display name — is identical to the form field\'s Field name. So a form field named email lands in a dataset field whose Reference ID is email with no mapping at all, while one named Your email silently doesn\'t. Values that match nothing are dropped from the record without failing the submission, and the same is true of a deleted dataset or an exceeded record quota — the append is best-effort by design, so a data-store problem never costs you a signup. The inbox copy always keeps everything, which is why it\'s the thing to check if a record looks wrong. The survey walkthrough covers datasets, schema types and the form pickers in much more depth.' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '5. Launch day: reverse every step', anchor: '#5-launch-day-reverse-every-step', text: 'Turning a site dark is easy to do and easy to forget. Here is the whole reversal — work down it, then verify with step 6. 1. Allow search engines again. Setup → SEO → turn Discourage search engines from indexing this site off. The console banner disappears, and robots.txt, the sitemap and the page meta all return within about a minute. 2. Set the hidden screens back to Public. The site-wide switch and per-screen visibility are independent — turning the switch off does not promote an Unlisted screen. Go through Screens and set each one\'s Visibility back to Public in its Page Access card. Anything you leave Unlisted stays out of search, silently and indefinitely. 3. Swap the home page back. Open Coming soon, change its Slug to something else (coming-soon) and Update route — or Unpublish it if you\'re done with it. Then open your real home screen and set its Slug back to /. 4. Verify — step 6. Don\'t skip it. Every step above is a setting that can be half applied, and the failure is silent. :::caution "Why is my site not on Google?" Nine times out of ten it\'s this feature, left on. Check, in order: the Setup → SEO switch, then each screen\'s Visibility. Then remember that re-indexing is the search engine\'s schedule, not yours — a site that was noindex for a month does not come back the afternoon you fix it. Allow days, and use Google Search Console to request indexing if you\'re in a hurry.' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: '6. Verify it actually worked', anchor: '#6-verify-it-actually-worked', text: 'Three things a crawler reads, and how to read them yourself. Run these against your real domain. robots.txt — visit https://your-site/robots.txt, or: Hidden looks like this — note that no sitemap is named: Visible looks like this: The page\'s robots meta — open the page, View source, and search for robots. Or: A hidden page returns . A visible page returns nothing at all — no robots meta means "index me", which is the default. The sitemap — visit https://your-site/sitemap.xml, or: That counts the URLs you\'re submitting to search engines. It should be 0 while the site-wide switch is on, and after launch it should match your public pages. Any page you expect to see and don\'t is a screen still set to Unlisted. :::tip Give it a few minutes These three files are cached for about five minutes. If a change hasn\'t shown up, wait a beat and re-run rather than changing another setting.' },
  { path: '/guides/coming-soon-launch', title: 'Launch a coming-soon page', heading: 'Related', anchor: '#related', text: '- SEO Toolkit — search engine visibility in full - Forms & lead capture - Build & publish a survey — datasets and form mapping - Site protection — when noindex isn\'t enough - Create a redirect' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '', anchor: '', text: '# Commerce end to end This walkthrough runs the whole selling loop: catalog → storefront → checkout → orders → subscriptions. It links into the commerce reference rather than repeating it — the goal here is the end-to-end path. :::info Plan availability Selling needs a paid plan (fees drop as you upgrade — see Billing & plans). Storefront subscriptions (including the subscribe side of "Both — buyer chooses") need Business and above.' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '1. Connect payments', anchor: '#1-connect-payments', text: 'Aglyn sells from your own Stripe account via Stripe Connect. On the Products hub, the payments card walks you through Express onboarding; checkout stays disabled ("This site has not enabled payments yet") until Stripe reports charges enabled. Aglyn adds its per-sale platform fee automatically per your plan.' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '2. Create products', anchor: '#2-create-products', text: 'On the site\'s Products page (Catalog tab), choose Add product. The editor dialog covers everything the catalog reference describes: - Basics — Name, Slug (/products/{slug}), Type (Physical / Digital / Service), Status (Draft / Active / Archived), description, tags, categories, media. - Options & variants — up to 3 options expand into a variants matrix with per-variant Price, Compare-at, SKU, Barcode, Stock, and Weight. Blank stock = untracked; 0 shows sold out. - Billing — how buyers pay: - One-time purchase (default) — a normal order. - Monthly subscription / Yearly subscription — the product page prices per interval and the buy button becomes Subscribe. - Both — buyer chooses — the product page shows a one-time vs subscribe toggle (defaulting to one-time); pick the Interval the subscribe side bills at. The buyer\'s choice is validated server-side against the product. - Any subscription mode reveals Free trial (days) — the trial precedes the first charge. - Digital delivery (digital products) — attach files from the media library, optionally versioned, with a per-order Download limit. Buyers always download the current files; uploading a new version re-delivers. Set the product\'s Status to Active — drafts are invisible to visitors.' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '3. Design the storefront', anchor: '#3-design-the-storefront', text: 'Open a screen in the Besigner and add blocks from the Commerce group of the element picker: - Product grid — a responsive catalog grid. Its Show property scopes it to all products, a collection, a category, or a tag; set Columns, Sort, a cap, and optional visitor-facing filter chips. Cards link to /products/{slug}. - Product detail — gallery, variant picker, price (with sale badge, trial caption, and /mo·/yr when subscribing), Add to cart, and the buy button (Buy now / Subscribe, or the one-time-vs-subscribe toggle for "Both" products). Leave its Product slug blank on a template screen so it follows the URL. The Product page preset drops the whole commerce-standard page in one go: a Shop / {{product.name}} breadcrumb, the detail block, a You may also like strip, and product reviews. - Cart — two presets: a Cart button (app-bar icon with an item-count badge and a slide-out drawer — the badge updates live as blocks add to the cart) and a Cart page (inline, with coupon and gift-card fields). Both end in a Checkout button. ### Catalog search, filters, and sort The Product grid carries a toggle per storefront catalog control, so a bare strip on the home page and a full shop page are the same block: - Search box — a debounced search field above the grid; matches product names, descriptions, and tags. - Category chips — one chip per product category (plus All), built from the categories you manage in the Products hub. Visitors tap to filter. - Sort select — newest, name, price low→high, price high→low, right-aligned above the grid. - Type filter — physical / digital / services chips, useful for mixed catalogs. - Price filter — a two-thumb price range slider, automatically bounded by the lowest and highest prices among the products currently showing (variant-priced products cou' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '4. What checkout does', anchor: '#4-what-checkout-does', text: 'Both buy buttons and the cart\'s Checkout redirect to Stripe-hosted Checkout, then back to your site with a success/cancelled marker: ### Paying without leaving your site There is a second checkout that keeps the shopper on your own pages: instead of sending them to checkout.stripe.com, the card form opens in place, below the Buy or Checkout button, styled with your site\'s theme. Leaving the store mid-purchase is one of the most common places a cart gets abandoned, so this exists to remove that step. Rolling out. In-page checkout is off by default and is switched on per workspace by Aglyn staff (release flag In-page checkout). Until it is on for your workspace, checkout behaves exactly as described above — the redirect is what your shoppers see. Nothing else about a sale changes when it is on, and that is deliberate: - The price, tax, shipping and any coupon are computed by the same code. The in-page form is the same Stripe Checkout Session as the redirect, just drawn by us instead of by Stripe — so the two cannot quote different totals. - Your order is still created by Stripe\'s webhook, never by the browser. If a shopper pays and immediately closes the tab, the order, the stock decrement, the receipt and the gift-card or licence-key steps all still happen. If they pay and then refresh the page, none of it happens twice. - A declined card stays on the form. The basket, address and payment method the shopper already entered are kept, with the decline shown beside them, so they can try another card without starting over. Cards that ask for a bank verification step (3-D Secure) show that challenge in place. - Abandoned in-page checkouts are still recoverable and still feed the abandoned-cart emails, the same as an abandoned redirect. A shopper who cancels the in-page form i' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '5. Run orders from the console', anchor: '#5-run-orders-from-the-console', text: 'The Products hub\'s Orders tab lists every sale with product, period, status, and channel filters plus Export CSV and Draft order (build an order by hand and send a payment link). Export CSV writes the orders currently shown — the filters apply — as orders.csv, one row per order: date, product, amountUsd, feeUsd, customerEmail, coupon, orderId, status, channel, refundedUsd, netUsd. amountUsd is the gross charge, so subtract refundedUsd (or read netUsd) when reconciling against a Stripe payout. Orders with several line items name the first and count the rest, e.g. Blue Mug +2 more. Open an order for the detail dialog — customer, line items, totals, timeline, and internal notes: - Fulfill… — enter a carrier and tracking number; the order moves to fulfilled and the buyer\'s account page shows the tracking. Mark delivered closes the loop, and Packing slip prints one. - Refund — confirms "Refund this order?", then refunds the buyer through Stripe (full or partial) and reverses the platform fee. Site-admin role only. - Cancel order — for orders that shouldn\'t proceed (does not auto-refund). Statuses move through a guarded machine: pending → paid → fulfilled → delivered, with cancel/refund exits — see the orders reference.' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: '6. Subscriptions & the Stripe portal', anchor: '#6-subscriptions--the-stripe-portal', text: 'Active subscriptions are recorded per site and surface in two places: - Buyers manage their own — the Customer account block\'s Subscriptions section has a Manage button that opens the Stripe Billing Portal (update card, cancel, see invoices). - You see each member\'s subscriptions in the member drawer on the site\'s Users page — what they subscribed to, the amount and interval, and the renewal date — and managers get a New subscriber notification carrying the amount on each signup, then a Subscription renewed notification carrying the amount on every cycle after it. What a subscription puts in Orders depends on the product\'s Type: - A physical subscription creates one order per paid cycle — the first charge included — on the Subscription channel, so every box has something to fulfill, pack and label against, and recurring revenue shows up in the Orders tab, the analytics card and the orders CSV alongside one-time sales. Each cycle\'s order also decrements the variant\'s stock (if tracked) and can trigger the low-stock alert. - A digital or service subscription is not an order, by design: it does not appear in Orders, in the analytics card or in the orders CSV, and it does not decrement stock — there is nothing to ship. Either way, what the subscriber pays is recorded on the subscription itself — each paid invoice, its period and its amount included, so a renewal is a record you hold rather than one only Stripe holds. The amount shown follows the latest cycle, so a price change, a tax change or a trial converting to a paid cycle is reflected rather than frozen at what the first charge was. Stripe keeps its own copy of every invoice, reachable from the Billing Portal. An active subscription is also what members-only content can check for paid gating.' },
  { path: '/guides/commerce-end-to-end', title: 'Commerce end to end', heading: 'Related', anchor: '#related', text: '- Commerce reference - Product catalog - POS & reservations - Member accounts' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: '', anchor: '', text: '# Datasets & schema deep-dive This guide goes one level below the datasets overview: how the typed model actually works, what the limits are, and every path data takes in and out of a dataset.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Display names vs field ids', anchor: '#display-names-vs-field-ids', text: 'A dataset field has two names, and the distinction matters everywhere: - The display name is what you type in the schema dialog and what table headers and record editors show. Rename it freely. - The reference id is the stable key. It auto-fills from the display name when you create the field (Visit frequency → visitfrequency), and the schema dialog lets you edit it right there to set your own — for example a short, code-friendly key that differs from the label. Once the field is created the id is fixed and never changes. Records store values keyed by reference id — it\'s the key you use in {{item.referenceid}} bindings and what a form field\'s Maps to schema field picker stores. The schema dialog shows both — each field row reads Display name · fieldId. The Reference ID input sits directly under Display name in the field editor; it follows the name as you type until you edit it, then keeps your value. The dataset itself likewise has a Singular name and a Plural name; the plural is the dataset\'s display name — the label its entry shows in "Write to dataset" and repeatable pickers (which store the dataset\'s id underneath, so renames never break the bindings).' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Naming & describing fields', anchor: '#naming--describing-fields', text: 'Open the schema dialog and Edit a field to change how it presents: - Display name — rename it freely, any time. The field id underneath never changes, so {{item.fieldId}} bindings, form field mappings, and stored records are all unaffected by a rename. - Description — a free-form note on what the field is for. When set, it follows the field around the console: - the schema dialog\'s field list shows it under the Display name · fieldId line, - the records table shows it as a tooltip on the column header, - the record editor shows it as the input\'s helper text (a validation error takes its place while present). Both are trimmed on save, and a blank description is dropped rather than stored. Descriptions are console-facing documentation only — they never render on the published site.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'The typed model', anchor: '#the-typed-model', text: 'A dataset\'s model is a map of field definitions plus a display order. Each field definition carries its type, whether it\'s Required, an optional Description and Default value, validation (regex pattern, min/max length, an enum of Options), and — for reference fields — the target dataset and delete behavior. The types you can author: | Type | Holds | | --- | --- | | Text | Strings; optionally pattern-, length-, or enum-constrained | | Boolean | true / false | | Integer | Whole numbers | | Number | Floating-point numbers | | Date & time | Timestamps | | Coordinates | Latitude / longitude pairs | | List | Ordered arrays | | Reference | A link to a record in another dataset — see relations | Plugins can register custom field types, which appear in the type picker suffixed with the plugin id. Records are validated and coerced against the model on every server-side write. :::info Legacy datasets Datasets created before typed models (a flat comma-separated field list) still work: the runtime derives an effective model where every column is an optional text field whose id equals the column name. Open the schema dialog and re-type the fields to upgrade — ids are preserved. Reference fields configure what happens when a referenced document is deleted: Clear the reference (default) or Block the delete. Tick Allow multiple for many-to-many relations.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Record quotas per plan', anchor: '#record-quotas-per-plan', text: 'Dataset counts and records per dataset are entitlements of your organization\'s plan: | Plan | Datasets | Records per dataset | | --- | --- | --- | | Free | — (no data store) | — | | Starter | 3 | 1,000 | | Pro | 15 | 10,000 | | Business | 100 | 100,000 | | Advanced | 500 | 1,000,000 | - Creating datasets on Free is rejected with "Datasets require a Starter plan or higher." - Hitting the record cap surfaces "Record limit reached — see Billing to upgrade" in the console, and imports that would overflow are refused with the exact slot math. - Form submissions never fail on quota — if the dataset is full the record write is skipped silently, but the inbox copy is always kept. - Add-ons raise the dataset count beyond the base allowance, up to a hard per-plan ceiling.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Import & export', anchor: '#import--export', text: 'The Data page round-trips CSV and JSON: - Export — the CSV and JSON toolbar buttons download the loaded records with one column per model field. - Import — the Import records dialog takes pasted CSV (with a header row) or a JSON array. Columns match by field id first, then case-insensitively by display name; rows are validated against the model on the way in. - Upsert — pick a Match on field (upsert) key (say, an email field) and matching rows update records in place instead of appending duplicates. Only genuinely new rows count against the record quota. See import & export for round-trip tips.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Repeatables', anchor: '#repeatables', text: 'Containers (like a Stack) have a Repeat over dataset property. Set it and the container\'s children become an item template, rendered once per record on the published site: 1. Select the container and set Repeat over dataset to your dataset (stored by id, so renames never break it). 2. Inside the children, reference record values with {{item.fieldId}} — e.g. {{item.name}}, {{item.price}}. 3. Reference fields support one hop: {{item.author.name}} resolves the referenced record\'s field. 4. Optionally set a Repeat limit, a Repeat filter (price , >=, <, <=, contains), and a Repeat sort (price desc). The canvas doesn\'t expand rows while designing — it shows a repeat notice on the container ("children render once per record on the live site") so you design a single template. Up to 100 records render per repeatable.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Everything that writes records', anchor: '#everything-that-writes-records', text: '| Writer | How it behaves | | --- | --- | | Console — Add record / record editor | Typed inputs per field; validated and quota-checked. | | Console — Import records | Bulk CSV/JSON with validation, upsert, and quota math. | | Forms — the Form element\'s Write to dataset | Appends on each submission. The dataset is bound by id (a dropdown; legacy forms still match by name) and each form field can map to a schema field by id via Maps to schema field, with name-matching as the fallback — so renames never lose data. Best-effort (quota-full submissions keep only the inbox copy). See the survey guide. | | Automations — the Write to a dataset step | Appends a record from a workflow/action run. | | Automations — the Update a dataset record step | Updates a matching record (by email) or appends when none matches. | Automation steps live in the Do list of an action — see workflows & actions.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Deleting a dataset', anchor: '#deleting-a-dataset', text: 'Delete removes the dataset and every record in it, permanently — the confirmation tells you how many documents go with it. There is no undo and no retention window, so export first (CSV or JSON) if you might want the rows back. Deleting a single record from the table leaves the dataset itself alone. The same applies to the two other things that hold records inside them: deleting an email list takes its enrolled subscribers, and deleting a collection takes the content entries published under it.' },
  { path: '/guides/datasets-and-schema', title: 'Datasets & schema deep-dive', heading: 'Related', anchor: '#related', text: '- Build & publish a survey - Datasets overview - Build a data model - Relations - Bindings, variables & functions' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: '', anchor: '', text: '# Build a mega menu with hover interactions A mega menu is the wide, multi-column panel that drops down from a nav item on big marketing sites. In this walkthrough you\'ll add one to your header, fill it with columns of links, and wire it to open on hover — all in the Besigner, without writing any CSS or JavaScript. You can see the finished result on our demo site: hover Explore in the header of northwind-coffee.aglyn.app and a three-column panel (Coffee / Learn / Get in touch) drops open. :::info Plan availability Every plan, including Free. A mega menu and its open/close behavior are basic interactions — pure in-page choreography with no server cost, so they\'re never gated. Only the powerful automation steps (analytics, overlays, custom JS, server actions) require Pro+. See interactions.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: 'What you\'ll build', anchor: '#what-youll-build', text: '- A Mega Menu nav item with a wide panel. - Three columns of screen links inside the panel. - A hover interaction so the panel opens when a visitor points at the nav item — and closes itself when they move away. Put the menu in your layout (not a single screen) so it shows on every page. Open your Main Layout in the Besigner to follow along; if you don\'t have a layout yet, see Screens & layouts.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: '1. Insert the Mega Menu', anchor: '#1-insert-the-mega-menu', text: '1. In the Besigner, select your header\'s nav bar (the App Bar or its Toolbar) so the new element lands inside it. 2. Open Add Element and expand the Navigation group. 3. Insert Mega Menu. It arrives as a nav item labelled Menu with a starter panel of three link columns. On the canvas the menu shows just its trigger — that\'s how it renders on the live site until a visitor interacts. Select the Mega Menu (or anything inside it) and the panel expands in place so you can edit its contents; click elsewhere and it collapses again. :::tip Set the label With the Mega Menu selected, set its Label in the inspector (for the demo it\'s Explore). Use the Panel width attribute to choose Fit content, Wide (720px), or Full width. The label renders in the case you type it, so it sits beside plain nav links without shouting. If you want it uppercase, set Text transform in Styles → Typography on the Mega Menu itself and the trigger follows.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: '2. Build the columns', anchor: '#2-build-the-columns', text: 'The panel is an ordinary canvas slot, so you compose it like any other section: 1. The starter preset gives you three Stacks side by side — one per column. Select a column and set a heading (e.g. Coffee, Learn, Get in touch). 2. Inside each column, drop Screen Link elements from the Navigation group and point each at a screen. Screen links store the screen id, not the URL, so renaming or re-slugging a page never breaks the menu. 3. Add as many columns, links, images, or promo cards as you like — a mega menu panel takes any content. :::tip Menu links should render as links A Screen Link ships as a button by default, which is right for a call to action but wrong for navigation: it picks up button typography and the theme\'s uppercase transform, and it announces itself as a button to screen readers. Set Render as to Text link on the links inside a menu panel, a footer, or a body paragraph. The button-only attributes (Variant, Size, Full width) disappear when you do, because a link ignores them.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: '3. Make it open on hover', anchor: '#3-make-it-open-on-hover', text: 'Out of the box, clicking the nav item already toggles the panel — no setup. To add the classic hover behavior: 1. Select the Mega Menu element itself. 2. In the inspector, open Add interaction. 3. Set the Trigger to When hovered. 4. Add the action Open a menu. Leave the target empty — it defaults to the element you\'re editing. 5. Leave Frequency on Every time (the default) so the menu keeps working on every hover, not just once. 6. Save. The interaction is enabled immediately and appears in the element\'s Interactions list with edit, enable/disable, and remove controls. That\'s the whole wiring. A menu opened by hover closes itself when the pointer leaves the nav item and its panel, with a short grace period so the pointer can travel between the two — you don\'t need a separate When hover ends interaction. :::tip Pick the target by clicking Any interaction that targets an element (open a menu, show/hide, open a drawer) lets you pick the target by clicking it on the canvas and confirming — no CSS selectors to write. A "define a custom selector" option is there as a secondary escape hatch. ### Prefer primitives? Insert the Dropdown Panel preset If you\'d rather build the same pattern from plain elements — a Stack wrapper, a Button trigger, and an absolutely-positioned panel you style freely — insert Dropdown Panel from the Navigation group instead. It arrives with the whole hover choreography already wired as ordinary interactions: show on hover (with Close on Esc and Close on outside click) and hide on hover leave with a 250ms grace delay. Edit or delete them on the wrapper\'s Interactions list like anything you authored yourself. The menus & navigation reference covers when to reach for the preset versus the Mega Menu element.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: '4. Add a mobile drawer (optional)', anchor: '#4-add-a-mobile-drawer-optional', text: 'A wide hover panel is a desktop pattern. For small screens, pair it with a slide-in drawer: 1. Insert Mobile Nav (Navigation group) into your toolbar. You get a Menu Button (hidden on desktop), an inline link row (hidden on mobile), and a Drawer already wired to the button — clicking the button toggles the drawer with zero configuration. 2. Swap the drawer\'s placeholder links for your screens, and design the drawer panel however you like — it\'s a normal canvas slot. 3. Under Styles → Visibility, confirm the mega menu\'s nav cluster is hidden on mobile and the menu button is hidden on desktop. See menus & navigation for the full element reference.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: '5. Test and publish', anchor: '#5-test-and-publish', text: '1. Use Test in the interaction dialog to confirm the open/close behavior against the canvas. 2. Open Preview and hover the nav item — the panel opens and closes exactly as it will on the published site, without publishing anything. 3. Toggle the artboard device preview and light/dark scheme to check the panel at different sizes. 4. Click Publish. Open your live site and hover the nav item — the panel drops open, and moving the pointer away closes it.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: 'How it works under the hood', anchor: '#how-it-works-under-the-hood', text: 'You never touch selectors or state, but here\'s the model: - Every menu and drawer renders closed on the live site and listens on a small command bus keyed by its node id. - An Open a menu step dispatches an open command to that bus; the menu element receives it and expands. Click-toggle, the hover interaction, and any other element that opens the menu all speak the same bus, so they compose without conflicting. - Hover-opened menus track the pointer and dispatch their own close when it leaves — which is why you only author the open. Because it\'s all in-page DOM choreography, it runs on every plan and is never metered.' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: 'Troubleshooting', anchor: '#troubleshooting', text: '- The panel is always open in the editor. That\'s expected — selecting the menu or its contents expands it as an overlay under the nav item so you can edit it. It renders closed on the published site. Click empty canvas to collapse it, or open Preview to see it behave as published. - Hover does nothing on the live site. Confirm the interaction\'s Trigger is When hovered, the action is Open a menu, and the interaction is enabled (green switch on the Interactions list). Confirm you published after adding it. - The menu opens but won\'t close. Make sure you used Open a menu (which auto-closes on pointer leave), not Show an element (which needs a matching When hover ends → Hide interaction).' },
  { path: '/guides/mega-menu-with-interactions', title: 'Build a mega menu with hover interactions', heading: 'Related', anchor: '#related', text: '- Menus & navigation - Interactions & custom HTML - The Besigner - Screens & layouts' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: '', anchor: '', text: '# Member accounts Visitors can become members of your published site — sign up, sign in, see their orders, and unlock members-only screens. This walkthrough covers the visitor side (built-in auth pages and the account block) and the console side (the Users page and the member drawer). :::info Plan availability Member signups and the account block work wherever commerce does; gating screens to members needs the content-gating feature (Business and above) — see Members-only areas. :::note Members are not console users Site members are your site\'s audience, separate from the console teammates you invite to collaborate. Members sign in on your published site only, with a per-site session — they never see the console.' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: '1. The built-in sign-in and sign-up pages', anchor: '#1-the-built-in-sign-in-and-sign-up-pages', text: 'Every published site serves two ready-made routes — no design work needed: - /signup — "Create your account": name, email, and password (8 characters minimum). Submitting creates the member, signs them straight in, and returns them to your home page. - /signin — "Welcome back": email and password. The two pages cross-link ("New here? Create an account" / "Already a member? Sign in"). New members automatically flow into your Contacts CRM and appear as leads; memberSignUp and memberSignIn automation events fire so you can trigger welcome actions. :::note Passwords Member sessions are per-site, cookie-based, and last 30 days. There is currently no self-service password reset for members — if a member is locked out, they can sign up support via your site\'s contact channels.' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: '2. Design an account page', anchor: '#2-design-an-account-page', text: 'For a richer home for members, add the Customer account block (found in the Commerce group of the element picker) to a screen — conventionally at the slug account, which is where commerce gates point anonymous visitors: - Signed out, the block shows sign-in / create-account tabs in place, with your configurable Signed-out heading above. - Signed in, it renders the member\'s profile with Sign out, plus sections for Orders (with status chips and tracking), Subscriptions (each with a Manage button that opens the Stripe Billing Portal), Downloads (digital purchases and license keys), and Addresses. Give the account page the same chrome as the rest of your site by binding a shared layout: in the screen\'s Properties, pick one under Shared layout — the appbar/footer are then maintained once for every bound screen (see screens & layouts).' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: '3. Gate screens to members', anchor: '#3-gate-screens-to-members', text: 'To restrict a screen: open its version view, and in the Page Access card set Visibility to Members only, then publish. Anonymous visitors get a "This page is for members" prompt with sign-in / create-account links instead of the content (or your designed 401 error screen if you\'ve assigned one). The screen\'s content is never in the anonymous page source — members fetch it with their session after sign-in. For one-off protection without accounts, use a per-screen password instead.' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: '4. Manage members from the console', anchor: '#4-manage-members-from-the-console', text: 'The site\'s Users page has two cards: Site users (your members — this guide) and Users (console collaborators). The Site users card is searchable and paged, newest first, with Email, Name, Joined, and Status columns. Click a member to open the member drawer: - Profile — email, display name, and join date, with a Suspended chip when applicable. - Lifetime purchases — charged order totals minus refunds (pending and cancelled orders excluded). - Orders — the member\'s payment history, newest first: order number, status, total, date, any refunded amount, and the Stripe payment reference. Needs the editor or admin role on the site. - Subscriptions — each with its renewal date and status chip. - Addresses — the member\'s saved addresses. ### Suspend & reactivate The drawer\'s action button flips between Suspend member and Reactivate member, each behind a confirmation: - Suspend — the member can no longer sign in on the published site (they see an "account suspended" message), and their account page signs out on its next load. Orders, subscriptions, and history are all kept. - Reactivate — restores access with the member\'s existing password. Both actions are recorded in the site\'s activity log. ### Password help The drawer\'s Password section gets a member back into their account. This is their sign-in for this site only — it has nothing to do with any Aglyn console account the same person might also have. - Send password reset email — emails the member a link to the site\'s /recover page. The link works once and expires after an hour, and their current password keeps working until they use it. This is the option to reach for. Capped at a few sends per hour to the same member, so a stuck retry loop can\'t flood their inbox. - Set a password directly — replaces the member\'s password w' },
  { path: '/guides/member-accounts', title: 'Member accounts', heading: 'Related', anchor: '#related', text: '- Members-only areas - Commerce end to end - Contacts CRM - Site protection & error screens' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: '', anchor: '', text: '# Run an agency workspace If you build sites for other people — an agency, a freelancer with a roster, an internal team serving several brands — Aglyn is designed to be one workspace holding many sites, rather than one account per client. This page is the whole shape of that setup, in the order you\'d actually do it. It\'s written for someone who has built one Aglyn site already. If you haven\'t, do Build your first site first — this page assumes you know what a screen and the besigner are.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'The mental model, first', anchor: '#the-model', text: 'Three words, and getting them straight up front saves a lot of confusion later: | Term | What it is | For an agency | | --- | --- | --- | | Organization | The billing and identity boundary. Owns the plan, the invoice, the members, the shared library. | You. One organization for your agency. | | Site (or host) | One published website with its own screens, domain, media and store. | One per client project. | | Workspace | What the console calls your organization when you\'re working in it. | Same thing as organization — you\'ll see both words. | The consequence that matters: your plan\'s limits are per organization, and your access controls are per site. You buy 25 sites once; you decide separately who can touch which one. :::tip One organization or one per client? Use one organization when the sites are yours to run: you hold the domains, you bill the client for a service, you\'re the one on call. That\'s the normal agency shape, and it\'s what the Agency plan is priced for. Use a separate organization per client when the client ultimately owns the account and you\'re only building it — they hold the card, the domain, and the risk. You then join their organization as a member and can leave cleanly. The awkward middle — building in your workspace and later moving the site to theirs — is the one thing that isn\'t self-serve, so decide before you start. Ask support if you\'re not sure which side a project falls on.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 1 — Pick the plan by site count, not by features', anchor: '#step-1-plan', text: 'For agencies the binding limit is almost always how many sites you can publish, not which features you get. Check the site allowance on the plan table and pick from there. Two things that change the arithmetic: - Extra sites are an add-on, so you don\'t have to jump a whole tier for one more client. They\'re cheaper per site on higher plans. - The platform fee on client storefront sales falls to 0% on higher plans. If your clients sell, that fee can dominate the subscription price — do that sum before choosing. :::warning Upgrades are instant, downgrades are not An upgrade applies immediately and prorates. A downgrade waits until the end of the period you already paid for, and $0 is due on the day you choose it. Plan seasonal capacity accordingly: dropping a tier in January doesn\'t reduce a January invoice. When each change takes effect.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 2 — Build your house style once', anchor: '#step-2-templates', text: 'The single biggest saving in agency work is not rebuilding the same footer. 1. Build one site properly — nav, footer, contact page, legal pages, theme. 2. Save it as a template from the site\'s settings. See Save a template. 3. Start every new client from that template instead of from blank. Two more things worth doing once: - Reusable components for the pieces you\'ll place on many screens within a site. Edit the component, every instance updates. - The organization media library for assets shared across clients — your own logo, stock photography you\'ve licensed, icon sets. Files there are available to every site in the workspace, so you upload once. :::tip Keep client assets in the client\'s site library The organization library is shared across every site. Client logos and photography belong in that site\'s library, not the shared one — otherwise the next project\'s media picker is full of the last client\'s brand.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 3 — Decide who can touch what', anchor: '#step-3-access', text: 'Aglyn has two shapes of teammate, and the distinction is the one agency-specific thing worth learning properly: | | Workspace manager | Site collaborator | | --- | --- | --- | | Sees | Every site in the organization | Only the sites you grant | | Costs | A manager seat | A collaborator seat on each site they can reach | | Use for | Your own staff | Contractors, and the client | Give clients collaborator access, not manager access. A manager can see every other client\'s site, their content and their form submissions. That is usually a contractual problem, and it\'s not undone by anyone being careful. Steps: 1. Organization → Team to add your own staff as managers. 2. On each site, use its members card to invite that project\'s collaborators. 3. Use custom roles if you want something narrower than the built-ins — a client who may edit content but not publish, for example. Seats are metered and enforced per plan, and both kinds are available as add-ons if you outgrow the included count. Invited people don\'t consume a seat until they accept. Full detail: Teams, roles & membership.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 4 — Domains and handover', anchor: '#step-4-domains', text: 'Each site gets a free .aglyn.app subdomain immediately, which is what you build and demo on. Connect the real domain at launch. The handover question is who owns the DNS, and it\'s worth settling in writing at the start of a project rather than at 5pm on launch day: - You hold the registrar — fastest to launch, and you can fix things. It also means you\'re the one a client has to ask to leave, which some clients dislike and some contracts forbid. - The client holds the registrar — slower (you\'ll be sending them records to paste), cleaner to hand over, and the honest default for most work. Either way the records are the same, and the site\'s setup page shows them. See Connect a domain.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 5 — Back up before you hand over', anchor: '#step-5-backups', text: 'Every site exports a full backup from its own settings. Take one: - before any large redesign, so "put it back how it was" is a real option; - at handover, and give the client a copy — it is theirs, and having it makes the relationship easier to end well; - before deleting anything. Deleting a site is immediate and permanent, with no hold period — unlike deleting an organization, which has one. There is no undo and we keep no copy. Take one from the site\'s Setup → Backup & restore. Datasets export separately to CSV from Content → Data, so a full handover is usually both.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 6 — Billing, and what to tell clients', anchor: '#step-6-billing', text: 'The invoice is yours, at the organization level. Aglyn doesn\'t bill your clients and doesn\'t split an invoice per site. However you charge them — retainer, per site, marked-up hosting — is between you and them. Two things that are per site, and are the ones clients ask about: - Storefront platform fees come out of that site\'s own sales. - Usage meters (page views, storage, form submissions, emails) roll up to your organization total. A single client having a very good month can move your invoice, so watch the usage figures on the billing page rather than being surprised. Sales tax is added on top of your plan price where applicable, calculated from your workspace\'s billing address — see Sales tax.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Step 7 — Automate the repetitive part', anchor: '#step-7-automate', text: 'Once you\'re running several sites, the console stops being the fastest way to do routine things. The REST API reads across your organization with one key: - Sites — enumerate every site and its domain, which is the basis of any status dashboard you build. - Form submissions — pull every client\'s leads into one place, or into their CRM. - Orders and Products — for clients who sell. - Media — audit alt text across every site, or find what\'s filling your storage quota. Start with Your first API call, which walks through creating a key and making a request from scratch. :::tip One key per purpose Create a separate key for each integration, scoped to the least it needs. A key that only reads form submissions can\'t be turned into a data breach across every client\'s store, and revoking one doesn\'t take the others down.' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'A checklist you can reuse per project', anchor: '#checklist', text: '- [ ] Site created from your house template - [ ] Client added as a site collaborator, not a manager - [ ] Theme, logo, favicon set from the client\'s brand - [ ] Legal pages present (privacy, terms, cookie banner if needed) - [ ] Custom domain connected and verified - [ ] SEO basics: titles, descriptions, social image, sitemap reachable - [ ] Analytics visible to the client - [ ] Backup taken and a copy given to the client - [ ] Who holds the registrar, written down somewhere you\'ll find it' },
  { path: '/guides/run-an-agency-workspace', title: 'Run an agency workspace', heading: 'Related', anchor: '#related', text: '- Teams, roles & membership - Site templates - Add-ons - Your first API call' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: '', anchor: '', text: '# Your first API call By the end of this page you\'ll have made a real request to your own data and handled the errors properly. It assumes nothing — if you\'ve never used an API before, start at the top and follow along; if you have, skip to Step 3 and then read the API reference instead of the rest of this. Everything here uses curl, which is already installed on macOS and Linux and ships with Windows 10 and later. There\'s a JavaScript version of each step underneath. :::info What you need - An organization on a plan that includes API access (Business or Advanced). - Permission to manage the organization — only owners and admins can create keys. - A terminal.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Step 1 — Create an API key', anchor: '#step-1-create-a-key', text: '1. Open the console and switch to the organization you want to use. 2. Go to Organization → Settings, and find the API keys card. 3. Choose Create API key. 4. Give it a name that says what it\'s for — zapier-orders-sync, not key 1. The name is what you\'ll be looking at in six months deciding whether it\'s safe to revoke. 5. Select its scopes. A scope is one permission. Grant the fewest that do the job: for this walkthrough, tick Datasets — read. 6. Choose Create. Copy the key now. It\'s shown exactly once. Aglyn stores only a hash of it and genuinely cannot show it to you again — if you lose it, the fix is to revoke it and make a new one, which costs you nothing but a minute. A key looks like this: :::danger Treat it like a password The key carries your organization\'s access, not your personal login. Anyone holding it can do everything its scopes allow. - Never commit it to git. Put it in an environment variable or a secrets manager. - Never put it in a web page, a mobile app, or anything a browser downloads — a key in client-side JavaScript is a public key. - Use one key per integration, so you can revoke one without breaking the others. Store it in your shell for the rest of this page:' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Step 2 — Check that the key works', anchor: '#step-2-check-the-key', text: 'Before writing anything real, confirm the key is valid and see what it can do: That\'s the whole handshake. Authorization: Bearer is how every request authenticates — there is no login step, no token exchange, no session. If you get something else, jump to errors. :::tip Do this at startup in real code GET /v1/me is the cheapest way to fail fast with a clear message. An integration that checks its key on boot tells you "the key is wrong" at deploy time instead of "undefined is not a function" at 3am.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Step 3 — Your first request', anchor: '#step-3-your-first-request', text: 'List your organization\'s datasets: Three things to notice, because they\'re the same on every list endpoint: - data holds the results. Always an array, even with one result. - hasmore tells you whether there\'s another page. This is the only reliable end-of-list signal — see step 5. - object on each item names its type. Handy when you\'re logging. Now read records out of one of those datasets, using its id: Your data lives in values, keyed by field id — which is not the same as the display name you see in the console. Email address in the console is email here. The dataset\'s fields array tells you the mapping. ### In JavaScript Read the error body before throwing. error.type is a stable machine-readable string; error.message is a sentence for a human. Branch on type, log message.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Step 4 — Write something', anchor: '#step-4-write-something', text: 'Writes need a write scope. Go back to the console, create a second key with Datasets — write, or add the scope when you create the key. Scopes have no hierarchy: datasets:write does not include datasets:read. A key that writes a record and then reads it back needs both, ticked separately. A new record returns 201. ### About that Idempotency-Key {#idempotency} It\'s the header that makes retrying safe, and it is worth understanding on day one rather than after your first duplicate. The problem it solves: you POST, the record is created, and then your connection drops before the response reaches you. You have no idea whether it worked. Retrying might create a second record; not retrying might lose the first. With an Idempotency-Key, retrying is simply correct. Send the same key and: - if the original succeeded, you get 200 with the original record — not a duplicate; - if the original failed, the key is released, so a retry genuinely re-runs; - if the original is still running, you get 409 conflict — wait and retry. 201 means created, 200 means replayed. That\'s how you tell them apart. Use a fresh UUID per logical operation — one key per record you intend to create, generated before the first attempt and reused across every retry of that attempt. Keys never expire, so a key really is single-use forever. The full rules, including how it behaves on DELETE, are in Conventions → Idempotency.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Step 5 — Page through everything', anchor: '#step-5-page-through-everything', text: 'Lists come back in pages. To get everything, follow the cursor: :::warning Two things that will bite you 1. A short page is not the last page. Some endpoints filter rows out after reading a page, so data.length can be less than limit while hasmore is still true. A loop written as while (page.data.length === limit) stops early and looks like it worked. Loop on the cursor. 2. Page 1 is not "the newest 25". Every list is ordered by id, not by date. There is no sort parameter and no filter on created. Paging start to finish gives you every item exactly once — that\'s what a full sync needs — but "give me today\'s records" is not a request this API can answer. Page everything and compare created yourself, or store the ids you\'ve already handled.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'The four errors you will hit', anchor: '#the-four-errors-you-will-hit', text: 'Every error has the same shape, and type is the field to branch on: | You see | It means | Do this | | --- | --- | --- | | 401 unauthorized | Key missing, mistyped, or revoked. | Check the header is Authorization: Bearer aglynsk…. A common cause is a shell variable that didn\'t expand — echo $AGLYNAPIKEY. | | 403 insufficientscope | The key is fine; it lacks a permission. code names the exact scope. | Create a key with that scope. You can\'t add a scope to an existing key. | | 403 planrequired | The organization\'s plan doesn\'t include API access — or, on commerce endpoints, doesn\'t include commerce (code: "commerce"). | Not transient. Don\'t retry — alert a human. | | 429 ratelimited | Over 120 requests/minute for this key. | Back off. Retry-After says for how long, and every response carries the remaining budget in its headers. | Retry 429 and 500. Never retry 401, 403, or 400 — nothing about them will change on the second attempt, and a loop that retries them turns a config mistake into a rate-limit ban.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Where to go next', anchor: '#where-to-go-next', text: '- API reference — every resource, every field, every error. - Conventions — pagination, ordering, errors, idempotency, in one place. Worth reading once, end to end. - Rate limits & usage — the 120/minute limit and how monthly usage bills. - Webhooks — for reacting to events, don\'t poll. Polling a list endpoint on a timer is the most common way to hit the rate limit. If you\'re syncing a store, Orders and Products each carry a recipes section with the whole loop written out.' },
  { path: '/guides/your-first-api-call', title: 'Your first API call', heading: 'Related', anchor: '#related', text: '- Datasets & schema deep-dive — field ids, the typed model, quotas. - Billing & plans — which plans include the API.' },
  { path: '/marketing-and-automation/ai-assist/copy-assist', title: 'Copy assist', heading: '', anchor: '', text: '# Copy assist Copy assist drafts and rewrites text without leaving the Besigner. :::info Plan availability Paid / env-gated (runs through a managed Claude route).' },
  { path: '/marketing-and-automation/ai-assist/copy-assist', title: 'Copy assist', heading: 'Use it', anchor: '#use-it', text: '1. Select a text-capable element (a headline, body text, a button label). 2. Invoke copy assist on that text prop. 3. Generate fresh copy or rewrite what\'s there, then accept the result. It works on any canvas text prop, and blog entries can be drafted with AI too.' },
  { path: '/marketing-and-automation/ai-assist/copy-assist', title: 'Copy assist', heading: 'Tips', anchor: '#tips', text: '- Give it context in your prompt — the audience, tone, and goal — for better copy. - Treat output as a first draft; edit inline afterward with inline text editing.' },
  { path: '/marketing-and-automation/ai-assist/copy-assist', title: 'Copy assist', heading: 'Related', anchor: '#related', text: '- AI Generate Section - AI Assist overview' },
  { path: '/marketing-and-automation/ai-assist/generate-section', title: 'AI Generate Section', heading: '', anchor: '', text: '# AI Generate Section Where copy assist writes text, AI Generate Section builds structure — a whole section of components — directly on the canvas. :::info Plan availability Paid / env-gated.' },
  { path: '/marketing-and-automation/ai-assist/generate-section', title: 'AI Generate Section', heading: 'Use it', anchor: '#use-it', text: '1. Describe the section you want (e.g. "a three-column features row with icons and short blurbs"). 2. Run AI Generate Section. 3. Aglyn adds a constrained subtree of real components to the canvas, which you then refine like anything else. The output is constrained to valid components and placement, so it drops into your design cleanly.' },
  { path: '/marketing-and-automation/ai-assist/generate-section', title: 'AI Generate Section', heading: 'Tips', anchor: '#tips', text: '- Generate a rough section, then adjust with drag-and-drop and inline text editing. - Combine with the section & block library for a mix of generated and pre-built blocks.' },
  { path: '/marketing-and-automation/ai-assist/generate-section', title: 'AI Generate Section', heading: 'Related', anchor: '#related', text: '- Copy assist - The Besigner' },
  { path: '/marketing-and-automation/ai-assist/overview', title: 'AI Assist', heading: '', anchor: '', text: '# AI Assist Aglyn\'s AI assist helps you write and build faster, right inside the editor. :::info Plan availability Paid / env-gated. AI features run through a managed Claude route.' },
  { path: '/marketing-and-automation/ai-assist/overview', title: 'AI Assist', heading: 'Copy assist', anchor: '#copy-assist', text: 'Generate or rewrite text for any canvas text prop — headlines, body copy, button labels — without leaving the Besigner. Blog entries can be drafted with AI too.' },
  { path: '/marketing-and-automation/ai-assist/overview', title: 'AI Assist', heading: 'AI Generate Section', anchor: '#ai-generate-section', text: 'AI Generate Section creates a constrained subtree of components directly on the canvas from a prompt, giving you a real starting layout you can then refine. :::note More detailed how-tos coming Prompting tips and examples are on the way.' },
  { path: '/marketing-and-automation/ai-assist/overview', title: 'AI Assist', heading: 'Related', anchor: '#related', text: '- The Besigner - Templates, blocks & content' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: '', anchor: '', text: '# Cookie consent If your site uses Google Analytics, Aglyn manages visitor consent for you. The control is real, not decoration: whenever a visitor\'s recorded state does not grant analytics, the Google Analytics script never loads — it is not loaded and then suppressed.' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'How it works', anchor: '#how-it-works', text: 'Consent UI appears only on sites that use a consent-gated feature — today, a configured Google Analytics ID. A site with no analytics has nothing to consent to, so its visitors never see anything. Your site\'s consent mode (Site setup → SEO → Cookie consent) decides how visitors are handled: - Geo-conditional (recommended, and the behavior when you have never touched the setting): visitors in prior-consent regions — the EU/EEA, the UK, and any visitor whose region cannot be determined — see a consent banner first, and analytics loads only after they allow it. Visitors everywhere else (for example the US) are tracked from their first visit with no banner; their state is recorded as implied consent, and the persistent Privacy choices control lets them opt out at any time. - Opt-in everywhere: every visitor, everywhere, sees the prior-consent banner. The banner offers Allow, Decline, and Preferences side by side — no dark patterns, and declining is one click, same as allowing. Built-in Aglyn analytics are unaffected by all of this: the pageview beacon is cookieless and stores no visitor identifier, so it needs no consent.' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'What needs consent', anchor: '#what-needs-consent', text: 'Consent-gated — held back unless the visitor\'s recorded state grants analytics: - Google Analytics (your configured measurement ID), including the overlay and experiment events Aglyn mirrors into it. - Cross-visit A/B test identity: without an analytics grant, experiment variant assignment is remembered only for the visit (sessionStorage) instead of across visits. Always on (strictly necessary) — these keep working regardless of the choice, because the site cannot function without them: - Shopping cart and member sign-in cookies. - Popup and announcement "don\'t show this again" stamps (stored locally, never transmitted). - The stored consent state itself.' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'Privacy choices — the persistent control', anchor: '#privacy-choices--the-persistent-control', text: 'Whenever consent management is active, every page of your site shows a small Privacy choices control. Visitors use it to change their state in either direction at any time — opt out after being tracked by default, or allow analytics after declining. In geo-conditional mode this control is the only opt-out surface visitors in implied-consent regions see, which is why it is shown by the platform on every page rather than depending on your template. You can also link any element (a footer link, for example) to #aglyn-consent — clicking it opens the same preferences panel.' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'Global Privacy Control', anchor: '#global-privacy-control', text: 'Browsers can send the Global Privacy Control (GPC) signal. Aglyn honors it as an automatic opt-out: a visitor sending GPC is never tracked by default, in either mode, and their state is recorded as a GPC opt-out. If they explicitly allow analytics in Privacy choices, that specific choice takes precedence over the blanket signal.' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'Previewing what visitors see', anchor: '#previewing-what-visitors-see', text: 'You configure from one country; your visitors come from many. In any screen\'s Preview, use the Consent preview picker (top right) to view your site as-if-from the EU, the US, an unknown region, or a GPC-sending browser — the real banner, driven by the real rules, with nothing saved. On a published page you can append ?aglynConsent=ask to any URL to see the prior-consent banner as an EU visitor would (this override can only ever show more consent UI, never less, so it is safe to share).' },
  { path: '/marketing-and-automation/analytics/cookie-consent', title: 'Cookie consent', heading: 'Turn the banner off', anchor: '#turn-the-banner-off', text: 'The switch at the top of the Cookie consent card turns the whole tool off. That means Google Analytics loads for every visitor without being asked — do this only if you run your own consent solution, and remember you remain responsible for the consent your visitors\' jurisdictions require.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: '', anchor: '', text: '# Analytics Aglyn tracks how your site is doing out of the box — pageviews, referrers, devices, and per-screen traffic — so you don\'t need a third-party tool to see the basics. :::info Plan availability Free dashboard traffic panel. Per-screen traffic and the screenAnalytics entitlement are Pro+.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Pageview tracking', anchor: '#pageview-tracking', text: 'A lightweight pageview beacon records visits into daily counters. The site dashboard shows a traffic panel summarizing your site\'s activity. Tracking is cookieless — no visitor IDs, no fingerprinting.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Visitors (approximate)', anchor: '#visitors-approximate', text: 'Alongside raw pageviews, the traffic panel shows an approximate visitor count. It is deliberately imprecise so it can stay cookieless: each browser tab counts once per day, so a visitor using two tabs — or returning on another day — counts again. Nothing links one day\'s visits to the next.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Insights', anchor: '#insights', text: 'Dig into traffic with insights: top referrers, device breakdowns, and selectable date ranges.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Campaign tracking (UTM)', anchor: '#campaign-tracking-utm', text: 'Links tagged with utmsource, utmmedium, and utmcampaign are broken down on the analytics page, so you can see which newsletters, ads, or campaigns actually bring visitors. Tag your links as you would for any analytics tool; Aglyn records the labels from the URL — nothing about the visitor.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Per-screen traffic', anchor: '#per-screen-traffic', text: 'Pro+ sites get a per-screen traffic panel on each screen\'s view page, with pageviews attributed to the screen and broken down by referrer and device — and a Screens table on the site\'s analytics page comparing pageview share across all your screens over a selectable window. Plan cards surface analytics as an upsell for lower tiers.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Google Analytics', anchor: '#google-analytics', text: 'Prefer your own tooling? Add a Google Analytics ID and Aglyn injects it alongside the built-in tracking.' },
  { path: '/marketing-and-automation/analytics/overview', title: 'Analytics', heading: 'Related', anchor: '#related', text: '- SEO toolkit - Billing & plans' },
  { path: '/marketing-and-automation/email-campaigns/designed-emails', title: 'Designed emails', heading: '', anchor: '', text: '# Designed emails Design campaign emails in the besigner — the same editor you use for pages — with an email-safe block set. There is no separate email editor to learn.' },
  { path: '/marketing-and-automation/email-campaigns/designed-emails', title: 'Designed emails', heading: 'Create a template', anchor: '#create-a-template', text: 'On Marketing → Email, click New email template. That creates an email document and opens it in the besigner with the email blocks: - Email section — the 600px container with background and padding. - Email text — heading/subheading/body/caption styles; supports merge tokens. - Email rich text — formatted HTML (sanitized like the custom HTML block). - Email image, Email button, Email divider, Email spacer — the essentials, rendered in email-client-safe markup. - Email product — pick a product by id; its current name, price, and image fill in at send time (renames never break it). - Email custom HTML — raw table markup for advanced layouts, sanitized.' },
  { path: '/marketing-and-automation/email-campaigns/designed-emails', title: 'Designed emails', heading: 'Styling email blocks', anchor: '#styling-email-blocks', text: 'The styles panel works on email blocks exactly as on page elements — your edits (fonts, colors, spacing) apply on top of each block\'s email-safe defaults. Because email clients run no JavaScript, the attributes panel does not offer the Interactions section while an email document is open — use links (Email button, image links) for anything clickable.' },
  { path: '/marketing-and-automation/email-campaigns/designed-emails', title: 'Designed emails', heading: 'Merge tokens', anchor: '#merge-tokens', text: 'Use these anywhere in text, rich text, or button links: | Token | Fills with | | --- | --- | | {{contact.firstName}} | Recipient\'s first name | | {{contact.name}} | Full name | | {{contact.email}} | Email address | | {{site.url}} | Your site\'s base URL | | {{unsubscribeUrl}} | Signed unsubscribe link | Unknown tokens stay visible in the output so a typo shows up in your test send instead of silently rendering blank.' },
  { path: '/marketing-and-automation/email-campaigns/designed-emails', title: 'Designed emails', heading: 'Send it', anchor: '#send-it', text: 'In the campaign composer, pick your template under Email design (stored by id — renaming the template never breaks scheduled sends). The plain-text message field disappears; the render pipeline produces inline-styled table HTML plus a plain-text alternative per recipient. - Send test to me delivers a proof to your own address without recording a campaign. - Scheduling and A/B experiments work exactly as with plain campaigns.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: '', anchor: '', text: '# Email Campaigns Email campaigns let you reach the people in your contacts CRM. Build an audience, compose a send, and Aglyn handles delivery, caps, and unsubscribes. :::info Plan availability Paid, with tiered send caps — how many emails you can send per period depends on your plan.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: 'Send a campaign', anchor: '#send-a-campaign', text: '1. Build an audience — leads, site members, segments, or an email list. 2. Compose the campaign from the Marketing page. 3. Send — subject to your plan\'s send cap. ### Personalize with merge tags Use {{name}}, {{firstName}}, or {{email}} anywhere in the subject or body — they resolve per recipient at send time from the audience\'s stored details. Add a fallback with a pipe for recipients without a stored name: Hi {{firstName|there}}!. ### Schedule a send Pick a Send at time in the composer and the button becomes Schedule campaign. Scheduled campaigns appear in history with a Scheduled chip and a Cancel action until the send time; they deliver through the same caps, suppression list, and merge tags as an immediate send.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: 'Email lists', anchor: '#email-lists', text: 'Lists are static audiences shared across your organization\'s sites. Create them on the Marketing page, then grow them with the "Enroll in a list" automation step (e.g. on form completion) or popup email capture. Target any list from the campaign composer.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: 'Experiments', anchor: '#experiments', text: 'Business plans can A/B test screens, sections, and emails from the Experiments card on the Marketing page: weighted variants, deterministic visitor assignment, a conversion goal, and per-variant exposure/conversion rates with a pick-the-winner flow. Two ways to finish a test without watching it: - End date — past it, visitors get the default and stats stop accruing until you pick a winner. - Auto-declare winner — opt in with a minimum exposure count per variant and a confidence level (90/95/99%); once a challenger clears the bar (or every challenger confidently loses to the control), the experiment completes itself and serves the winner. Auto-completed tests carry a chip in the results dialog. - Screens & sections — variants pin a screen version; visitors are split deterministically and the winning version serves to everyone once you pick it. Start a section test straight from the Besigner\'s Interactions panel. - Emails — variants override the campaign\'s subject and/or body. Attach a running email experiment in the campaign composer; each recipient deterministically receives one variant (re-sends reach the same variant), sends count as exposures, and once a winner is picked every later send uses the winning copy.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: 'Opens & clicks', anchor: '#opens--clicks', text: 'With the Resend webhook configured, campaign history shows opens and clicks per campaign, and clicks on A/B sends count as that variant\'s conversions — so the experiment results table fills in by itself.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: 'Compliance', anchor: '#compliance', text: '- Every send includes an unsubscribe link. - Unsubscribes are honored automatically so you stay compliant.' },
  { path: '/marketing-and-automation/email-campaigns/overview', title: 'Email Campaigns', heading: 'Related', anchor: '#related', text: '- Contacts CRM - Forms & lead capture - Marketing overlays (email capture popups)' },
  { path: '/marketing-and-automation/marketing-overlays/overview', title: 'Marketing Overlays', heading: '', anchor: '', text: '# Marketing Overlays Marketing overlays are the announcement bars and popups that sit on top of your site to promote offers and capture emails — without touching your page designs. Manage them from your site\'s Marketing page. :::info Plan availability Paid, gated by the marketingOverlays entitlement.' },
  { path: '/marketing-and-automation/marketing-overlays/overview', title: 'Marketing Overlays', heading: 'Announcement bar', anchor: '#announcement-bar', text: 'A site-wide announcement bar shows a message across every page — ideal for sales, notices, or launches. It\'s controlled centrally and gated by the marketing-overlays entitlement.' },
  { path: '/marketing-and-automation/marketing-overlays/overview', title: 'Marketing Overlays', heading: 'Promotional popups', anchor: '#promotional-popups', text: 'Popups give you more control: - Triggers — show on load, on scroll, on exit intent, and similar. - Frequency capping — don\'t nag returning visitors. - Scheduling — run a popup only during a campaign window. ### Popup v2 The latest popup adds: - Email capture — collect emails straight into your contacts and campaigns. - Overlay metrics — impressions and conversions for each overlay. - A media picker so popups can use images from your media library.' },
  { path: '/marketing-and-automation/marketing-overlays/overview', title: 'Marketing Overlays', heading: 'Multiple overlays, scheduling & page targeting', anchor: '#multiple-overlays-scheduling--page-targeting', text: 'The Marketing page manages any number of bars and popups, each with: - A schedule window (show from / show until) — run a bar only during a sale. - Page targeting — comma-separated paths, with /blog/ matching a whole section, plus a "never show on" exclude list. - An enable switch and a status chip (Live / Scheduled / Off). When several overlays match a page, the first bar and the first popup (by order) show. The single announcement bar and popup on the same page remain as your always-on default surfaces; configured overlays take priority over them.' },
  { path: '/marketing-and-automation/marketing-overlays/overview', title: 'Marketing Overlays', heading: 'Engagement stats', anchor: '#engagement-stats', text: 'Each overlay tracks its own lifetime views, clicks, and dismissals, shown in the Engagement column of the overlays table — so you can tell whether a bar earns its screen space. Dismissals persist per visitor: a closed bar stays closed until you edit its text. With Google Analytics connected, the same events also land in your own GA property as aglynoverlay events (with the overlay id and action), so you can segment sessions by overlay engagement.' },
  { path: '/marketing-and-automation/marketing-overlays/overview', title: 'Marketing Overlays', heading: 'Related', anchor: '#related', text: '- Email campaigns - Contacts CRM - Billing & plans' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: '', anchor: '', text: '# Actions builder When you just need "when X happens, do Y", the actions builder is faster than a full workflow. It maps one event to one action. :::info Plan availability Basic interactions are on every plan (including Free): menu and drawer open/close, show/hide an element, toggle a CSS class, sticky nav, navigation, and site alerts — pure in-page effects with no server cost and no metering. The automations engine — server-side steps, custom JS, analytics events, and Marketing overlays — is Pro+, with metered runs. You build both in the same place; steps that need a higher plan are labelled in the editor.' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'Create an action', anchor: '#create-an-action', text: '1. Open the actions builder from Workflows. 2. Choose the event (the trigger). 3. Choose the steps to run in response. 4. Save. That\'s it — no multi-step logic to manage. Reach for a workflow when you need several steps, branching, or composition.' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'Triggers', anchor: '#triggers', text: 'Beyond server events (form submissions, page views, sign-ins, leads, bookings), actions can fire on visitor behavior in the page: - Scroll depth — the visitor scrolls past a percentage. - Scroll to / element visible — a CSS-selected element enters the viewport. - Element click — a CSS-selected element is clicked. - Exit intent — the pointer leaves toward the top of the window. - Time on page — a dwell-time threshold passes. - Page visit — the page loads. Page triggers can be limited to certain paths (/pricing, /blog/), and a Frequency setting controls re-fires: every matching pageview, once per session, once per visitor, or with a cooldown (a minimum number of minutes between fires for the same browser). ### Only run when a field matches Every action can carry a condition over the event\'s payload — for form submissions, that\'s the submitted field values. Pick an operator in the "Only run when" select: - A field is not empty — e.g. the subscribe checkbox was ticked. - A field equals… — an exact match (trimmed, case-insensitive), e.g. plan equals Pro. - A field contains… — a partial match, handy for checkbox groups that submit all ticked options joined with , (e.g. topics contains Pricing). When the condition isn\'t met the action is simply skipped — it doesn\'t count as a metered run. Conditions are the no-code sibling of the free-text Filter expression; use whichever reads better (both must pass when both are set). Example — grow an email list from a signup form: add a Checkboxes field named subscribe with a single option Yes, keep me posted to your form. Then create an action on formSubmission with the condition "A field is not empty" → subscribe and one step: Enroll in a list, picking your audience. Visitors who tick the box join the list; everyone else just submits the' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'Steps', anchor: '#steps', text: 'Steps run in order and mix in-page effects with server-side work: - Basic in-page effects (all plans): open/close/toggle a menu or drawer, show/hide or toggle an element, add/remove/toggle a CSS class, make the navigation sticky, redirect, show a site alert. These are pure DOM choreography — they run everywhere and are never metered. - Advanced in-page effects (Pro+): show a popup or bar from your Marketing overlays, show custom HTML, track an analytics event, and run custom JS (Business). - On the server (Pro+): run a workflow, write to or update a dataset, send a webhook (Business), send an email, notify site admins, enroll the contact in a list, assign a campaign, fire a custom event to chain more actions. On plans without the automations entitlement, an automation that mixes tiers still runs its basic in-page steps — the Pro+ steps are simply skipped until you upgrade. Every reference (workflow, dataset, webhook, overlay, list, campaign) is picked from a list and stored by id — renaming things never breaks an automation. Deleting can, though, so the Logic page\'s Reference health card audits every automation, workflow, and computed-variable reference and lists any that point at something that no longer exists.' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'Interactions from the Besigner', anchor: '#interactions-from-the-besigner', text: 'Select any element in the Besigner and use the Interactions section of the attributes panel to attach a when clicked, when hovered, or when scrolled into view trigger to that exact element — no CSS selectors to write. Pairing a when hovered trigger with an open menu or open drawer step is how you build hover-to-reveal navigation, and — like all basic in-page effects — it works on every plan. The interaction is created disabled with a placeholder step; finish and enable it on the Workflows page. The same panel lists the element\'s existing interactions with an enable switch and a remove button — so you can pause or retire one without leaving the canvas — and offers "A/B test this section", which creates a draft section experiment for the element.' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'When to use which', anchor: '#when-to-use-which', text: '| Use the actions builder | Use a workflow | | --- | --- | | One event → one action | Several ordered steps | | Simple, no branching | Composes functions/variables | | Fastest to set up | More control |' },
  { path: '/marketing-and-automation/workflows-and-actions/actions-builder', title: 'Actions builder', heading: 'Related', anchor: '#related', text: '- Build a workflow - Webhooks' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: '', anchor: '', text: '# Build a workflow A workflow is a sequence of steps that runs automatically when something happens on your site. This guide builds one end to end. :::info Plan availability Pro+. Workflow runs are metered per tier.' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: '1. Open the workflows page', anchor: '#1-open-the-workflows-page', text: 'In the console, go to Data → Workflows and choose New workflow. Give it a name that describes the outcome (e.g. "Welcome new member").' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: '2. Choose a trigger', anchor: '#2-choose-a-trigger', text: 'Pick the site event that starts the workflow — for example a form submission, a new member, or an order. The event\'s data is available to every step that follows.' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: '3. Add steps', anchor: '#3-add-steps', text: 'Add steps in order. Steps run through a pure step runner, so each step is predictable and repeatable. You can: - Reference variables and functions inside steps. - Compose an existing workflow inside a function or variable, and vice versa — workflows are composable.' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: '4. Save and test', anchor: '#4-save-and-test', text: 'Save the workflow. When the trigger fires, the workflow runs and each run counts toward your tier\'s metered allowance. Each workflow row has a Runs log: every execution with its outcome (failed runs show in red with the error) and how long it took — so a misbehaving workflow is diagnosed from the console, not from visitor reports.' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: 'Tips', anchor: '#tips', text: '- Keep steps small and named — a workflow reads like a checklist. - Watch your metered run count on the billing usage meters if a workflow runs on a high-frequency event.' },
  { path: '/marketing-and-automation/workflows-and-actions/build-a-workflow', title: 'Build a workflow', heading: 'Related', anchor: '#related', text: '- Actions builder - Webhooks - Bindings, variables & functions' },
  { path: '/marketing-and-automation/workflows-and-actions/overview', title: 'Workflows, Actions & Webhooks', heading: '', anchor: '', text: '# Workflows, Actions & Webhooks Automate what happens on your site. Workflows run multi-step logic when something happens; the actions builder maps an event to an action; webhooks connect Aglyn to outside systems. :::info Plan availability Basic in-page interactions (menu/drawer open-close, show/hide, class toggles, sticky nav, navigation, site alerts) are on every plan and never metered. The automations engine — server-side steps, analytics, overlays, and custom JS — is Pro+ with metered runs per tier. Webhooks are Business.' },
  { path: '/marketing-and-automation/workflows-and-actions/overview', title: 'Workflows, Actions & Webhooks', heading: 'Workflows', anchor: '#workflows', text: '- Build workflows on the workflows page with a pure step runner. - Trigger them from site events, and compose functions and variables inside them. - Runs are metered per tier.' },
  { path: '/marketing-and-automation/workflows-and-actions/overview', title: 'Workflows, Actions & Webhooks', heading: 'Actions builder', anchor: '#actions-builder', text: 'The actions builder turns an event into an action — event → action automation without code. Basic in-page effects (menus, drawers, show/hide, navigation) run on every plan; the server-side and advanced steps are Pro+ with metered runs.' },
  { path: '/marketing-and-automation/workflows-and-actions/overview', title: 'Workflows, Actions & Webhooks', heading: 'Webhooks', anchor: '#webhooks', text: 'Outbound and inbound webhooks let Aglyn notify other systems and receive events from them. Webhooks are a Business-tier feature. :::note More detailed how-tos coming Recipes for common automations (notify on form submit, sync orders, etc.) are on the way.' },
  { path: '/marketing-and-automation/workflows-and-actions/overview', title: 'Workflows, Actions & Webhooks', heading: 'Related', anchor: '#related', text: '- Bindings, variables & functions - Billing & plans' },
  { path: '/marketing-and-automation/workflows-and-actions/webhooks', title: 'Webhooks', heading: '', anchor: '', text: '# Webhooks Webhooks connect Aglyn to the outside world. Outbound webhooks notify another system when something happens on your site; inbound webhooks let another system trigger something in Aglyn. :::info Plan availability Business. Webhooks are a Business-tier feature.' },
  { path: '/marketing-and-automation/workflows-and-actions/webhooks', title: 'Webhooks', heading: 'Outbound webhooks', anchor: '#outbound-webhooks', text: 'Send an HTTP request to a URL you control when a site event fires — for example, post to a Slack endpoint or your own API when an order is placed. 1. Add an outbound webhook and paste the destination URL. 2. Choose the event that should fire it. 3. Save. Aglyn calls your URL with the event payload each time it fires.' },
  { path: '/marketing-and-automation/workflows-and-actions/webhooks', title: 'Webhooks', heading: 'Inbound webhooks', anchor: '#inbound-webhooks', text: 'Expose an endpoint that external systems can call to trigger Aglyn — for example to kick off a workflow from a third-party tool.' },
  { path: '/marketing-and-automation/workflows-and-actions/webhooks', title: 'Webhooks', heading: 'Tips', anchor: '#tips', text: '- Pair an outbound webhook with a workflow when you need to transform data before sending it. - Treat webhook URLs as secrets — anyone with the inbound URL can trigger it.' },
  { path: '/marketing-and-automation/workflows-and-actions/webhooks', title: 'Webhooks', heading: 'Related', anchor: '#related', text: '- Build a workflow - Actions builder' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: '', anchor: '', text: '# Add-ons Add-ons let you buy more of a specific thing without jumping a whole plan tier. They bill as extra line items on your existing subscription, prorate onto your current billing period, and take effect immediately. Manage them on Billing → Add-ons (requires the billing.manage permission and an active plan subscription — add-ons ride your plan\'s subscription, so Free workspaces pick a plan first).' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: 'What you can add', anchor: '#what-you-can-add', text: '| Add-on | What it does | Starter | Pro | Business | Scale | Advanced | Agency | | Manager seats | Workspace manager seats beyond the included count | $5/mo | $4/mo | $3/mo | $2/mo | $2/mo | $2/mo | | Collaborator seats | Per-site collaborator (teammate) seats beyond the included count | $3/mo | $2/mo | $1/mo | $1/mo | $1/mo | $1/mo | | Extra datasets | Additional shared datasets across the workspace | $2/mo | $2/mo | $1/mo | $1/mo | $1/mo | $1/mo | | Extra sites | Publish more sites than your plan includes | $10/mo | $8/mo | $5/mo | $5/mo | $4/mo | $3/mo | | POS registers | One extra point-of-sale register, assigned to one site | $89/mo | $89/mo | $89/mo | $89/mo | $89/mo | $89/mo | | Event Calendar | The event manager + calendar elements, workspace-wide | $9/mo | $9/mo | $9/mo | $9/mo | $9/mo | $9/mo | - Prices are per unit per month. On annual billing, add-ons bill yearly alongside your plan (12× the monthly price) — a subscription has one billing interval. - POS registers also require a plan with POS (Pro and above), and each one is assigned to a specific site — see Assigning register seats. - Event Calendar is a single workspace-wide toggle, not a per-site charge — see Events calendar.' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: 'Assigning register seats', anchor: '#assigning-register-seats', text: 'Unlike every other add-on, a POS register seat is bought once for your workspace and then assigned to one site. Buying a seat does not raise the register limit everywhere — it adds one register\'s worth of capacity that you place where you need it. Your plan already gives every site a register allowance on its own (Pro 1, Business 2, Advanced 5). A seat is added on top of that, for the one site you assign it to. To assign one, go to Billing → POS register seats, directly under Plan add-ons. The card shows how many seats you\'ve purchased, how many are assigned, and how many are unassigned, then lets you add or remove seats per site. - Seats are reassignable. Moving a seat between sites is immediate and costs nothing — you\'re not buying or cancelling anything, just relocating capacity. - Taking a seat off a busy site doesn\'t delete anything. If the site is running more registers than it can after the move, the extra ones stay set up but stop taking sales until you assign seats back or remove them. The console warns you before the move, with the number affected. - Deleting a site returns its seats to the pool automatically, in the same action that removes the site. There\'s nothing to reclaim by hand. - You need the Manage billing permission to move seats, the same permission that buys them. If every purchased seat is already assigned and a site needs another register, either move a seat off a site that isn\'t using it, or buy another seat under Plan add-ons.' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: 'How changes bill', anchor: '#how-changes-bill', text: '- Adding or removing units shows a prorated preview of today\'s charge before you confirm, and takes effect immediately. - Removing an add-on credits the unused time onto your next invoice. :::note Add-ons are not on the plan-switch schedule Add-on changes are always immediate and always prorated, in both directions. Plan switches are not: since Aglyn moved to end-of-cycle downgrades, a plan downgrade waits for your period end and charges $0 today, while only a plan upgrade is immediate and prorated. Removing an add-on still credits you today. See when each change takes effect. - Hard caps: seat and dataset add-ons stop at your plan\'s maximum (for example, Starter tops out at 5 workspace managers). Past the cap, the answer is a plan upgrade — the Billing page tells you when you\'re there.' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: 'Plan switches and cancellation', anchor: '#plan-switches-and-cancellation', text: '- Switching plans keeps your add-on quantities and re-prices them at the new plan\'s rates. If the new plan doesn\'t sell one of your add-ons, it\'s removed and the switch confirmation says so. On an upgrade this happens today, in the same prorated update as the plan change. On a downgrade it happens on the effective date along with the plan — your add-ons keep running, at your current plan\'s rates, for the rest of the period you already paid for. - Canceling (or a subscription that dies after failed payments) ends your add-ons with the plan — they bill on that subscription, so entitlement enforcement stops counting them at the same moment the plan downgrades to Free.' },
  { path: '/workspace-and-billing/billing-and-plans/add-ons', title: 'Add-ons', heading: 'Related', anchor: '#related', text: '- Billing & plans overview - Downgrading, canceling & your data - Teams, roles & membership' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: '', anchor: '', text: '# Downgrading, canceling & your data Changing to a lower plan, canceling, or deleting are three different things with three different effects. The short version: downgrading and canceling never delete anything — only deletion does, and deletion is deliberate and reversible within a hold window.' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: 'When each change takes effect', anchor: '#when-changes-take-effect', text: 'Plan changes are deliberately asymmetric, and knowing which direction you\'re going tells you what you\'ll be charged today: | You\'re doing | When it takes effect | Charged today | | --- | --- | --- | | Upgrading to a higher plan | Immediately | A prorated amount for the rest of the current period | | Downgrading to a lower paid plan | At the end of your current billing period | Nothing | | Canceling | At the end of your current billing period | Nothing | | Adding or removing an add-on | Immediately | Prorated | The reason downgrades wait is simple: you already paid for the current period, so you keep everything you paid for until it runs out. There is no proration credit on a downgrade because there is nothing to credit — nothing changes today.' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: 'Downgrading to a lower plan', anchor: '#downgrading-to-a-lower-plan', text: 'A downgrade changes your entitlements — which features you can use and how much — but it does not remove anything you\'ve already created, and it does not take effect the moment you click. ### The pending-downgrade window {#pending-downgrade} When you switch to a lower paid plan: 1. Confirm the switch. The dialog states the effective date and that $0 is due today. 2. Your current plan keeps running to the end of the period you already paid for. Every feature of the higher plan stays on the whole time. 3. A chip appears on the Current plan card — "moves to \\{plan\\} on \\{date\\}" — so the scheduled change is visible every time you open Billing, not just in the confirmation you clicked past. 4. On the effective date the plan changes and the lower price starts. ### Changing your mind {#keep-my-current-plan} While a downgrade is pending, the Current plan card shows Keep my current plan. Clicking it cancels the scheduled change, and the plan you\'re on simply continues at its normal price. You can also do this by switching to any higher plan — an upgrade cancels the pending downgrade and then applies immediately, in that order. Canceling your subscription while a downgrade is pending also drops the schedule, so the two never collide: you cancel from the plan you\'re on, not from the one you were scheduled to land on. ### What changes when the downgrade lands {#what-changes-on-a-downgrade} Nothing is deleted. Every site, file, dataset, product, and team member you have keeps existing. What changes: - You can\'t create more past the new limit. If Pro includes 3 sites and you have 5, all 5 keep working — but you can\'t add a 6th until you\'re back under the limit or upgrade again. The same applies to datasets, team seats, products, POS registers, and storage. - Paid features you no lon' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: 'Canceling your subscription', anchor: '#canceling-your-subscription', text: '- Cancel any time. Your subscription runs to the end of the paid period — a chip on the Billing page shows the end date, and you can resume before it hits. - When the period ends, your organization resolves to the Free plan. This is the same as a downgrade: nothing is deleted, over-limit resources persist, and paid features turn off. - A failed payment doesn\'t cancel you immediately — during Stripe\'s retry window your access continues (a past-due banner shows), and entitlements only drop to Free if the subscription actually lapses. ### What the Cancel button actually opens {#the-cancel-dialog} Cancel subscription doesn\'t cancel on the first click. It opens a short dialog with up to four steps. We\'d rather tell you what\'s in it here than have it surprise you: 1. "Why are you leaving?" — one choice from a fixed list (too expensive, missing features, not using it enough, switching to something else, technical problems, just pausing, something else) plus an optional comment box. This is the only required step, and the comment is genuinely optional. 2. A downsell, if a smaller paid plan would still fit you. It names the plan and its price. No thanks, continue moves on. 3. A winback discount, if you haven\'t used one before. It states the exact percentage and the exact number of months it lasts, because a discount whose end date you can\'t see isn\'t an offer. No thanks, continue moves on. 4. The confirmation. This step also lists anything you\'ll be over the Free plan\'s limits on once the cancel lands — extra sites, datasets, seats — so the consequence is visible at the moment you decide, not afterwards. Things worth knowing about the offers: - Every step has a visible way past it. There is no step you can only leave by staying. Keep my plan on the last step closes the dialog an' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: 'Deleting a single site', anchor: '#deleting-a-single-site', text: 'To remove just one site (not the whole organization), open the site\'s Admin → Danger zone and use Delete site. A site admin types the site name to confirm, and it\'s deleted immediately — its screens, media, and settings are permanently removed and its address stops resolving. Unlike an organization deletion there\'s no hold, so export a backup first (Setup → Backup & restore) if you might want it back. Your other sites and the organization are unaffected.' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: 'Deleting your organization', anchor: '#deleting-your-organization', text: 'Deletion is separate from canceling and is the only thing that removes your data. It\'s intentional and reversible for a short window: 1. Request deletion — an owner starts it from the organization settings; you confirm by typing the organization name. Export anything you want to keep before you start (Setup → Backup & restore) — the hold is the window for it, and nothing is kept for you afterwards. 2. A hold period follows the request. During the hold nothing is deleted and you can cancel the request to fully restore. 3. After the hold, the organization — its sites, files, datasets, and account records — is permanently erased. This step is irreversible, and we keep no copy of the erased data. What we retain is an internal record that the erasure happened: which organization, when it was requested, and how many sites, members and credentials were removed. Deletion covers your organization\'s sites and their stored files and data. If you own an organization that still has other members, transfer or remove them first — a shared organization isn\'t deleted out from under its members. :::info GDPR / right to erasure You can request erasure of your personal data at any time. Deletion permanently removes your records and leaves us with no copy of them — only a record that the erasure was carried out, which is itself kept for a limited period. Export anything you need during the hold. Contact support if you need an erasure completed outside the self-serve flow.' },
  { path: '/workspace-and-billing/billing-and-plans/downgrading-and-canceling', title: 'Downgrading, canceling & your data', heading: 'Related', anchor: '#related', text: '- Billing & Plans - Teams, roles & membership' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: '', anchor: '', text: '# Billing & Plans Your plan determines which features you can use and how much of each. Aglyn checks entitlements (can you use a feature) and quotas (how much) throughout the product, and shows usage meters so you always know where you stand. :::info Plan availability Every site has a plan. Free, Starter, Pro, Business, Scale, Advanced, and Agency unlock progressively more, and Enterprise sits above them all.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Tiers & entitlements', anchor: '#tiers--entitlements', text: '| Plan | Billed annually | Month-to-month | Commerce | | Free | $0 | $0 | Build & publish only — no selling | | Starter | $16/mo | $25/mo | Sell up to 100 products; 2% fee on physical, 5% on digital sales | | Pro | $39/mo | $56/mo | 2,500 products, 0% physical / 3% digital fees, POS, abandoned-cart recovery, reviews, dropshipping | | Business | $99/mo | $139/mo | 10,000 products, 0% / 2% fees, subscriptions & paywalls, gift cards | | Scale | $179/mo | $249/mo | 25,000 products, 0% / 1% fees, 15 sites | | Advanced | $299/mo | $399/mo | Unlimited products, 0% / 0% fees, high-volume commerce & API | | Agency | $649/mo | $799/mo | 100 sites under one organization, white-label | | Enterprise | Custom | Custom | Unlimited everything, SSO, white-label, 0% fees | Transaction fees are Aglyn platform fees on storefront sales, separate from Stripe\'s payment-processing fees. Upgrading is the way to reduce them. ### Enterprise Enterprise is the one tier you cannot buy from the Billing page. It has no list price — the plan, term, and invoicing are agreed with us, and we provision the organization directly. On top of everything in Agency it lifts every quota to unlimited and adds SAML / OIDC single sign-on, so your team signs in through your own identity provider. To start a conversation, use the Contact sales button on the Enterprise card at the bottom of your Billing page. Once your organization is on Enterprise, plan changes go through us rather than the self-serve upgrade and downgrade buttons. #### Single sign-on and enforcement Your people sign in through your identity provider. While SSO is on but not enforced, any sign-in method someone already had — a password, a linked Google account — keeps working, so nobody is locked out during rollout. New ones cannot be added: an accoun' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Usage meters', anchor: '#usage-meters', text: '- The billing page shows meters for every quota — storage, bandwidth, datasets, seats, sends, and more — with redesigned plan cards. - A usage-cap banner appears site-wide at 80% and 100% of a quota, with an upgrade link. - Org admins also get an in-app notification when email sends, dataset count, or data storage crosses 80% or 100% — once per threshold per month, so nobody has to be watching the console to find out. - The monthly email allowance caps campaign sends. Transactional mail — password resets, invites, order confirmations, booking reminders and workflow notifications — is counted toward your usage but is never blocked by the cap, at any plan. Going over shows up as an overage on the usage rollup rather than as mail your customers never receive. - Usage is rolled up with a cost-plus estimate for metered features.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Storage overage', anchor: '#storage-overage', text: 'Each site includes a fixed amount of storage. On a paid plan, going past it is not a wall: - Uploads keep working. You are never stopped from adding files because you reached your included storage. - The extra storage is billed on your monthly invoice, at about $0.034 per GB per month — our cost plus 30%, the same rate shown in Billing → Storage cap. - We tell you before it happens. You get an alert as you approach your included storage and another when you cross it, so the invoice is never the first you hear of it. See usage meters. ### If you would rather uploads stopped Set a monthly storage cap in Billing → Storage cap. This is optional and off unless you choose it. Once a month\'s storage overage would pass the amount you set, new uploads are refused and you are never billed above that number. You can change or remove the cap at any time, including while you are over your included allowance. Nothing is ever deleted — a cap only affects new uploads, and removing one takes effect immediately. :::info Free plans are never billed for storage On the Free plan there is no storage overage at all. Your included storage is a fixed cap: uploads stop there, nothing is metered, and no amount of usage produces a charge — so there is nothing to cap and nothing to configure. Enterprise storage is unlimited, so it has no overage either. :::tip No surprise bills Two things prevent one, and they work in different ways. The alerts at 80% and 100% of your allowance mean nobody first learns about overage from an invoice. The optional cap means anyone who wants a hard ceiling can have one, at a number they choose.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Usage budget', anchor: '#usage-budget', text: 'A usage budget is a monthly amount you choose, plus the percentages of it you want to hear about — the same shape as a Google Cloud billing budget. Set it in Billing → Monthly usage budget. - It warns, it never limits. Passing a budget sends a notification and an email. Nothing stops, no upload is refused, and your bill is unaffected. If you want usage to actually stop, that is the storage cap above — a different control, deliberately kept separate. - You choose the alert points. The default is 50%, 90% and 100%; you can set your own, including percentages above 100 so a runaway month keeps speaking. Up to six. - One alert per percentage per month. Crossing 50% tells you once, not once an hour. Climbing to the next percentage alerts again, and every percentage resets when the month does. - Both channels. Alerts arrive in the console notification menu and by email to your workspace owners and admins, so you do not have to be signed in to find out. - The figure is the invoice\'s own. Budget alerts quote the same metered total the billing page shows and the invoice charges — totalled once a day, so the first days of a month may show no total yet. Changing the amount clears the alert history for the month, so a budget you lower starts warning you against the new number straight away.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Seats', anchor: '#seats', text: '- Team seats (workspace-wide) and per-site collaborator seats are metered and enforced per tier — seats cover the people who build and manage your sites. - Buy paid seat add-ons to grow your team beyond the included seats — self-serve from Billing → Add-ons, alongside extra sites, datasets, POS registers, and the Event Calendar. - Site member accounts are not seats: visitors who sign up to your published site are unlimited on every plan.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Audience (contacts)', anchor: '#audience-contacts', text: ':::caution Rolling out The Contacts page in the console isn\'t available yet. Contacts are still captured from your sites and readable over the REST API, and the Free band below still applies — but while the page is unavailable, paid audience overage is not billed. The rates below are what will apply once Contacts opens. Your contacts CRM — form fills, member sign-ups, buyers, and bookings unified into one people list — is priced as an audience band, not a hard cap: - Each tier includes a band: Free 100, Starter 1,000, Pro 10,000, Business 100,000, Scale 500,000, Advanced 1,000,000 contacts. Agency and Enterprise are unlimited. - On paid tiers, growing past the band never blocks or drops anything — extra contacts are metered overage on your monthly invoice: $1.00 (Starter), $0.75 (Pro), $0.50 (Business), $0.40 (Scale), or $0.25 (Advanced) per extra 1,000 contacts per month. Upgrading a tier is always cheaper than sustained overage. - On Free, the band is a hard limit: new visitors past 100 keep their member accounts and orders, but no CRM record is kept. The count of missed sign-ups is recorded and will be shown on the contacts page once it opens.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Organization data', anchor: '#organization-data', text: '- Datasets are organization-scoped: counts and storage meter against your organization, not individual sites. - Each paid tier includes a number of datasets and an included data storage size (Starter 1 GB, Pro 5 GB, Business 25 GB, Scale 50 GB, Advanced 100 GB, Agency 500 GB). - Extra datasets are a monthly add-on ($2/mo on Starter and Pro, $1/mo on Business); storage beyond the included size is metered overage at $0.25 per GB-month on your monthly invoice.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'API access', anchor: '#api-access', text: 'The customer REST API is a Business tier and above feature — mint scoped API keys and call the versioned /v1 endpoints from anywhere. Requests are metered per organization: | Plan | Included requests / month | Overage | | Business | 100,000 | $0.50 per additional 1,000 | | Scale | 300,000 | $0.35 per additional 1,000 | | Advanced | 1,000,000 | $0.20 per additional 1,000 | | Agency | 5,000,000 | $0.15 per additional 1,000 | | Enterprise | Unlimited | — | - Requests past the included quota keep working and bill as metered overage on your monthly invoice — never a hard wall mid-integration. - The billing page shows an API requests meter, and the usage-cap banner warns at 80% and 100% of the included quota. - Only requests that pass authentication and the rate limit are counted — rejected calls (bad key, wrong plan, rate-limited) are never billed.' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Payments', anchor: '#payments', text: 'Billing runs through Stripe. Paid features (commerce, bookings, campaigns) share the same Stripe integration. ### Sales tax {#sales-tax} Plan prices are quoted before tax. Where Aglyn has a tax collection obligation, sales tax is added on top at checkout and on every renewal, and appears as its own line on the invoice. - Tax is calculated from the billing address on your workspace, not from your card\'s country and not from your personal address. It is computed automatically at the moment each invoice is created, so moving your workspace changes the tax on your next invoice rather than re-rating past ones. - A workspace with no billing address cannot have tax calculated at all, which is why the address can be replaced but not emptied — see the address bullets below. - Adding a business tax ID (VAT, ABN, EIN and the like) at checkout or in the Billing Portal puts it on the invoice. That\'s what makes an invoice usable for reclaiming tax or handing to an accountant, and in some jurisdictions it changes who accounts for the tax. - Every invoice states the tax separately from the amount charged, so the figure you reclaim is never one you have to back out of a total yourself. Invoice PDFs and receipts are on the Billing page\'s Billing history table. - Marketplace plugin purchases are taxed the same way, and Aglyn collects and remits that tax as the marketplace provider — the plugin\'s publisher does not charge you tax separately, and you should not receive two tax charges for one plugin purchase. If you ever do, that\'s a bug worth reporting. Sales tax on your own storefront\'s sales to your customers is a separate thing, configured by you — see Shipping &amp; taxes. ### Platform fees Storefront sales carry a declining platform fee on top of Stripe\'s processing fee — higher tiers' },
  { path: '/workspace-and-billing/billing-and-plans/overview', title: 'Billing & Plans', heading: 'Related', anchor: '#related', text: '- Add-ons - Teams, roles & membership - Analytics' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: '', anchor: '', text: '# Manage Account Manage Account is your personal account page, separate from your workspace and its team roster. Open it from the account menu (your avatar, top right) — click your name in the menu header, or the gear icon beside it. Everything here is yours alone: changing it follows you into every workspace you belong to. Workspace-level things — the team roster, roles, billing — live under Organization → Team and Billing instead. The page is four tabs.' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: 'Account', anchor: '#account', text: 'Your email and how you sign in. The email field is read-only, with a Email verified or Email unverified chip beside it. Your email comes from the provider you sign in with, so it changes there, not here. ### Sign-in methods Below the email, every method linked to your account is listed: - Google — shows the connected Google address and a Disconnect button. - Email & password — carries a Required chip. Password sign-in is permanent: it\'s the method that always works, so it can\'t be disconnected. If Google isn\'t linked yet, a Continue with Google button connects it. Linking both means you can sign in either way with one account — the same profile, the same workspaces, no duplicate account. You can never remove your last sign-in method; the attempt is refused rather than locking you out. Closing the Google popup mid-flow simply cancels — nothing changes. :::note If your organization uses single sign-on Accounts that sign in through a company identity provider cannot link Google or any other method — the option is shown as unavailable, with the reason. That is deliberate, not a limitation we intend to lift. Single sign-on exists so your organization\'s identity provider is the only gate: they revoke access there, require MFA there, and offboard people there. A linked personal Google account would be a way in that your IT administrators cannot see or revoke, which is the thing SSO is bought to prevent. If your organization turns on SSO enforcement later, sign-in methods that were linked before are removed at that point, and any active sessions using them end. Your account is never left with no way in: if removing a method would orphan an account, it is skipped and reported to your administrators instead.' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: 'Profile image', anchor: '#profile-image', text: 'Your avatar, shown in the account menu, on the workspace team roster, and beside your activity. Pick an image from the organization\'s media library or paste an https image URL. Leave it empty and Aglyn falls back to the photo your sign-in provider gave us, and then to your initials, drawn by Aglyn. Nothing about you is sent to an outside avatar service to work out what to show. The preview beside the field shows exactly what everyone else sees.' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: 'Basic info', anchor: '#basic-info', text: 'Your first and last name. Saving also updates the display name your teammates see — the Team page, activity entries, and comments all pick it up. Both are prefilled from however you signed up: the name you typed on the sign-up form, or the one your Google account or company identity provider sent us. Editing them here wins permanently — signing in again never re-applies the provider\'s version over your own. If your company signs you in through its own identity provider and these are blank, that provider is not sending a name; type one here. ### Contact details Phone number, organization name, and your address. Your phone number is stored in international format — type it however you like, including (512) 555-0123, and it is saved as +15125550123. Include the country code for anywhere outside the US and Canada, since a bare national number cannot be matched to a country without guessing. Country is the two-letter code (US, GB, DE). Stripe Tax cannot compute anything from a spelled-out country name, which is why the field insists. :::note Who can see this Your address and phone live on your personal account, visible only to you and to Aglyn staff. They are not copied onto your organization\'s member list — that list is readable by every member of the organization and by site collaborators, which is appropriate for a name and not for a home address. This is separate from the billing address on an invoice, which is collected at checkout and belongs to the organization rather than to you.' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: 'Security', anchor: '#security', text: 'Change your password. This tab appears only if your account has a password. A Google-only account has no password to change — connect Email & password from the Account tab first, and the Security tab appears.' },
  { path: '/workspace-and-billing/manage-account', title: 'Manage Account', heading: 'Related', anchor: '#related', text: '- Signing in & sessions - Teams, roles & membership - Notifications' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: '', anchor: '', text: '# Signing In & Sessions Sign in to the console with email & password or Google. A few behaviors are worth knowing about, especially if you work across devices or multiple organization workspaces.' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Google sign-in', anchor: '#google-sign-in', text: '- On desktop, Google sign-in opens a popup window and returns you to the console when it completes. - On mobile browsers, the console uses a full-page redirect instead: you\'re taken to Google, sign in there, and land back on the console already authenticated. (Mobile browsers can\'t reliably hand a popup\'s result back to the opening page.)' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Sign-in methods', anchor: '#sign-in-methods', text: 'You can link both methods to one account, and then sign in either way — same profile, same workspaces, no duplicate account. Manage them under Manage Account → Account: - Continue with Google links Google to an account that signed up with a password. - Disconnect unlinks Google again. - Email & password is marked Required and can\'t be disconnected — it\'s the method that always works. Your last remaining sign-in method can never be removed, so there\'s no way to lock yourself out. Single sign-on accounts are the exception. If your company signs you in through its own identity provider, no other method can be linked — see Manage Account for why, and for what happens to methods linked before your organization enabled enforcement.' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Resetting your password', anchor: '#resetting-your-password', text: 'Forgot your password? From the sign-in screen, choose Account recovery and enter your email. We email you a secure reset link, then walk you through the rest: 1. Request — enter your email on the account recovery screen and submit. We always show the same "check your email" confirmation, whether or not an account exists for that address (so the screen can\'t be used to probe who has an account). 2. Email — open the message and follow the reset link. Links expire after a short while and can only be used once. 3. Choose a new password — the link opens the reset screen, which confirms whose account it\'s for and asks for a new password (entered twice). Password rules match the sign-up screen. 4. Done — once saved, head back to the sign-in screen and sign in with your new password. If a link has expired or was already used, the reset screen offers to send a fresh one. If you signed up with Google and have never set a password, there\'s nothing to reset — connect Email & password from Manage Account first. :::note Self-hosting Aglyn composes and sends the reset and verification emails itself, through your configured mail provider — you do not need to set a Firebase action URL, and the Firebase email templates are not used at all. Firebase still mints the one-time code; only the message and the link\'s host are Aglyn\'s, and the link is built from your own console origin. What you do still need: the console domain listed under Authentication → Settings → Authorized domains, and a working mail provider. If mail is unconfigured, account recovery still returns its usual "check your email" screen — deliberately, so the screen can\'t be used to probe who has an account — but no message goes out. Check your server logs for [auth/send-password-reset] email is not configured.' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'One session across workspaces', anchor: '#one-session-across-workspaces', text: 'Signing in on the main console signs you in to every {org} workspace subdomain too — the session is shared at the parent domain, so hopping between workspaces never re-prompts for credentials. Signing out anywhere retires the shared session everywhere.' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Automatic sign-out after inactivity', anchor: '#automatic-sign-out-after-inactivity', text: 'For security, an idle console session expires after 1 hour of no activity (in any open tab, on any of your workspace subdomains). When that happens you\'re returned to the sign-in screen, and the page you were on is preserved — after signing back in you resume exactly where you left off. Activity means any interaction: pointer movement, typing, scrolling, or touching. Active work in one tab keeps your other tabs alive too. Inactivity is the only thing that ends a session early: a background tab losing its own authentication (a laptop waking from sleep, a suspended tab, a network blip) recovers silently from the shared session instead of signing you out everywhere. Only an explicit sign-out — yours, or a staff-initiated revocation — retires the shared session. :::note Self-hosting The idle window is configurable via the NEXTPUBLICAUTHIDLETIMEOUTMINUTES environment variable (default 60; set 0 to disable).' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Downloading your data', anchor: '#downloading-your-data', text: 'Manage Account → Close account → Download my data gives you a machine-readable JSON copy of everything we hold about you: your profile and contact details, your workspace memberships, your passkeys, your public publisher handle, and the support messages you wrote. It is the same file we would send if you asked us in writing. It is deliberately scoped to you. A workspace is shared, so your colleagues\' details are not in it — a support thread you took part in contributes only the messages you wrote yourself, not the replies. To take a whole workspace with you, use the workspace export below instead. It never contains a secret. API keys, webhook secrets, password hashes and payment links are listed as present rather than reproduced, so the file tells you what exists without becoming something you can lose. An API key\'s identifier is withheld too, because that identifier is derived from the key itself. The file opens with a coverage section naming every place we looked and what was done with each — including the two things that are deliberately not included, and why. If something you expected is missing, that section is where to check first. ### Downloading a whole workspace Owners and admins can export an entire workspace from Settings → Delete → Download workspace data: its sites and their content, datasets, contacts, orders, form submissions, members, support threads, custom domains and billing identifiers. Do this before deleting a workspace. Deletion keeps no copy, and the 7-day hold is the window in which this export is still possible. :::note What survives a deletion Sales-tax records for transactions on your storefront are kept after an erasure, because tax law requires it. They are included in the export — it is the one place you can see what remains.' },
  { path: '/workspace-and-billing/signing-in-and-sessions', title: 'Signing In & Sessions', heading: 'Closing your account', anchor: '#closing-your-account', text: 'Manage Account → Close account permanently deletes your personal account. It removes your profile and contact details, your avatar, your notifications, and your sign-in, and takes you off every workspace roster you\'re on. This cannot be undone, and support cannot restore it. Workspaces are never deleted by closing an account. A workspace outlives the person who created it, and deleting one as a side effect of someone closing their personal account would take its sites and data with it. So if you are the sole owner of a workspace, closing your account is refused until you hand that workspace over — the message names each one, along with whether it has an active subscription and how many other members it has. Transfer ownership from Team → Permissions, then come back here. Being a member, editor, admin or site collaborator is never a blocker; only sole ownership is. You\'ll be asked to confirm twice: once by proving it\'s you (your password, or a fresh sign-in through your provider), and once by typing DELETE. Both are required, and the confirmation of identity has to be recent — starting the flow and leaving it open for an hour will ask you again. :::note Single sign-on If your organization uses SSO, your account also exists in your identity provider\'s directory. Closing it here removes you from Aglyn; it does not touch your account with your identity provider, and an administrator there may be able to provision you again.' },
  { path: '/workspace-and-billing/support-and-community', title: 'Support & community', heading: '', anchor: '', text: '# Support & community Two ways to get help, each with its own page under Support: private support tickets with the Aglyn team, and a community forum shared with other Aglyn builders. Open Support from Organization → Support, or from Support in your account menu. It lands on whichever channel your plan makes primary — the forum on Free and Starter, tickets from Pro upward — and each page links to the other, so you always have both. :::note If you were invited to a single site Support isn\'t part of a site collaborator\'s console. A ticket is a conversation between the organization and Aglyn — it isn\'t scoped to one site, and the thread is readable by the organization\'s team — so the console doesn\'t offer it to someone whose access stops at a single site. Raise anything you run into with whoever invited you. They can open a ticket, and because tickets belong to the organization rather than to the person who filed them, any of their teammates can carry the thread on. :::info Plan availability The community forum is on every plan, including Free. Private support tickets start on Pro — Free and Starter are forum-only tiers. Each plan with tickets carries a first-response target, shown on the Support tickets page itself: | Plan | Tier | First response | | --- | --- | --- | | Free · Starter | Community | Forum only — no ticket channel | | Pro | Standard | 7–14 business days | | Business · Scale · Advanced | Business | 4–6 business days | | Agency | Priority | 1–3 business days | | Enterprise | Dedicated | 24–48 hours, plus a named success manager | Enterprise is measured in clock hours rather than business days, so a ticket opened on Friday is still answered over the weekend. The target is the upper bound of the range, measured to our first reply — not to resolution. See Billing' },
  { path: '/workspace-and-billing/support-and-community', title: 'Support & community', heading: 'Support tickets', anchor: '#support-tickets', text: 'At Organization → Support → Support tickets. A ticket is a private conversation between your organization and Aglyn staff. Anyone in the organization can open one and follow the thread. On Free and Starter this page explains where ticket support starts and points you at the forum instead — it never offers a New ticket button the server would refuse. 1. Choose New ticket. 2. Give it a Subject (up to 150 characters) and describe what\'s going on in the message body (up to 5,000 characters). 3. Submit. The ticket appears in your list marked open, and Aglyn staff are notified immediately. Open a ticket from the list to read the thread and reply. Each message shows who sent it, so a staff reply is always distinguishable from your own. ### Ticket status - open — with you or with Aglyn; new replies from either side keep it open. - closed — resolved. Either side can close a ticket, and replying to a closed ticket reopens it automatically — you never need to file a duplicate to follow up on something you thought was finished. Tickets belong to the organization, not to the person who opened them, so a teammate can pick up a thread while you\'re away. They stay in the list after closing as a record of what was asked and answered. ### What to include Support answers faster with the specifics: the site and screen involved, what you expected versus what happened, and the exact error text if there is one. If it\'s about billing, say which plan and which invoice.' },
  { path: '/workspace-and-billing/support-and-community', title: 'Support & community', heading: 'Community forum', anchor: '#community-forum', text: 'At Organization → Support → Community forum, and the page Free and Starter workspaces land on. The forum is for questions other builders can answer, and for sharing what you\'ve made. Threads are visible to everyone with forum access across all organizations — so don\'t post anything private (account details, customer data, keys). That\'s what a support ticket is for. Threads are organized into four categories: | Category | For | | --- | --- | | General | Anything that doesn\'t fit the others. | | Building | How-to questions about designing and shipping sites. | | Showcase | Show the site you built. | | Feedback | Product feedback and feature requests. | Filter the list by category, open a thread to read and reply, or start your own with a title and body (5,000 characters). Your display name and avatar are shown as the author.' },
  { path: '/workspace-and-billing/support-and-community', title: 'Support & community', heading: 'Related', anchor: '#related', text: '- Billing & plans - Manage Account' },
  { path: '/workspace-and-billing/teams-and-roles/custom-roles', title: 'Custom roles & permissions', heading: '', anchor: '', text: '# Custom roles & permissions Control what each teammate can do with roles — named permission sets — plus optional per-member overrides. :::info Plan availability Paid.' },
  { path: '/workspace-and-billing/teams-and-roles/custom-roles', title: 'Custom roles & permissions', heading: 'Create a custom role', anchor: '#create-a-custom-role', text: '1. On the organization Team page, find the Custom roles card and choose New role. 2. Give it a name and set each permission to granted, denied, or inherit (inherit falls back to the member\'s org role default). 3. Save, then assign it to members from the roster\'s Custom role column. The permission catalog covers organization settings, the activity log, billing (view and manage separately), member management, site creation and deletion, data, marketing, marketplace publishing, and plugin installs. Permissions are enforced everywhere — across the console\'s APIs and every surface — so a role reliably limits what a member can see and do. Members without billing or settings permissions don\'t see those tabs at all.' },
  { path: '/workspace-and-billing/teams-and-roles/custom-roles', title: 'Custom roles & permissions', heading: 'Effective permissions', anchor: '#effective-permissions', text: 'Not sure what someone can actually do? Every member row has a Permissions viewer that resolves their org role defaults, custom role, and per-member overrides into the final yes/no grant list.' },
  { path: '/workspace-and-billing/teams-and-roles/custom-roles', title: 'Custom roles & permissions', heading: 'Per-member overrides', anchor: '#per-member-overrides', text: 'Need one person to have slightly more (or less) than their role? Apply a per-member override on top of the role instead of creating a whole new role for one exception.' },
  { path: '/workspace-and-billing/teams-and-roles/custom-roles', title: 'Custom roles & permissions', heading: 'Tips', anchor: '#tips', text: '- Model roles around jobs ("Editor", "Marketer"), not individuals. - Use overrides sparingly — too many overrides make access hard to reason about.' },
  { path: '/workspace-and-billing/teams-and-roles/custom-roles', title: 'Custom roles & permissions', heading: 'Related', anchor: '#related', text: '- Invite teammates - Members-only areas' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: '', anchor: '', text: '# Invite teammates Bring collaborators into a site so they can build and manage alongside you. :::info Plan availability Paid. Team seats are metered per tier; buy seat add-ons to grow. See Billing & plans.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'Invite someone', anchor: '#invite-someone', text: '1. Open the organization\'s Team page and choose Add or invite. 2. Enter their email and assign a role. 3. What happens next depends on whether they already have an Aglyn account: already on Aglyn — they join right away and see the workspace on their next visit; new to Aglyn — we email them an invite to accept. ### Pending invites Invites that haven\'t been accepted are listed with Resend (send the email again, for the address that lost it in a spam folder) and Revoke. A revoked invite\'s link stops working immediately. ### Who gets told - The person you invited gets the invite email. The confirmation you see says whether one actually went out — "email sent" versus "they\'ll see it when they sign in" — so a workspace with email delivery unavailable never leaves you assuming a message was delivered. - Your workspace\'s owner and admins get an in-app notification when an invite is created and again when it is accepted, so whoever sent it finds out it was taken up without re-checking the Team page. Both appear under Team & access in the notification bell, and can be muted there like any other category.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'Accepting an invite', anchor: '#accepting-an-invite', text: 'If you\'re the one being invited, sign up or sign in with the address the invite was sent to — usually via Google, if that\'s the address. You land on the Workspaces page, which leads with "You\'ve been invited" and an accept banner. Accept there and the workspace opens. If that invite is your only workspace, the page also offers Create my own site instead — accepting isn\'t your only option. If you already belong to other workspaces, the invite banner appears above your usual workspace picker.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'How team members act', anchor: '#how-team-members-act', text: 'Team members act in the owner\'s organization, not their own — so their changes apply to your site, and permissions are enforced across the console\'s APIs and surfaces. Seat limits are enforced per tier; if you\'re at your limit, add a seat add-on before inviting more.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'You are a site collaborator\'s support channel', anchor: '#you-are-a-site-collaborators-support-channel', text: 'Someone you invite to a single site gets a console scoped to that site, which leaves out the organization pages — including Support. That is deliberate: a support ticket is a conversation between the whole organization and Aglyn, readable by your team, not a per-site channel. The practical consequence is that a site collaborator who hits a problem comes to you. Open a ticket on their behalf if it needs Aglyn — include the site and the exact error, as Support & community describes, since you will be relaying rather than reproducing. Someone invited to the whole organization keeps Support unchanged.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'Help a teammate who is locked out', anchor: '#help-a-teammate-who-is-locked-out', text: 'Open the member from the Team page and use the Password card. It has two options, and the first is almost always the right one. Send password reset email emails the member a link to choose their own password. Their current password keeps working until they use the link, and nobody else ever sees the new one. This works for every member. A few sends per hour to the same person is the cap — it\'s their inbox, and a reset link is good for an hour anyway. Set a password directly replaces the member\'s password with one you choose. Use it only when the member cannot receive email at all — you then have to pass the new password to them over a channel you trust. When you do: - they are signed out on every device, and - they are emailed to say an administrator changed their password. ### Why you can\'t always set a password An Aglyn login is personal, not per-organization. One person has one account no matter how many organizations they work with, so setting someone\'s password can hand you the keys to workspaces that have nothing to do with yours. The Set a password directly option is therefore unavailable — with the reason shown in its place — when the member: - also belongs to another organization, - is the organization owner (use Settings → Transfer ownership instead), - is an Aglyn staff account, or - is you (change your own password in your account settings). In every one of those cases, Send password reset email still works. The link goes to the member\'s own inbox, so it is safe regardless of what else their account can reach. Both actions are recorded in the organization\'s activity log, along with who performed them. The password itself is never written to the log.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'Activity log', anchor: '#activity-log', text: 'The organization\'s Team page shows a Recent Activity feed — renames, workspace URL changes, ownership transfers, members added/removed or re-roled, and invites sent, revoked, or accepted — each with who did it and when. Visible to any member of the organization. Entries name the thing that changed and link straight to it, so "Saved the screen — Home" takes you to that screen. Entries recorded before this shipped show a plain description instead of a link.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'Tips', anchor: '#tips', text: '- Start people on a least-privilege role and widen it with per-member overrides only where needed. - Removing a member frees their seat.' },
  { path: '/workspace-and-billing/teams-and-roles/invite-teammates', title: 'Invite teammates', heading: 'Related', anchor: '#related', text: '- Custom roles - Members-only areas - Billing & plans' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: '', anchor: '', text: '# Members-only areas Beyond your team, your site visitors can become members — and you can restrict certain screens to signed-in members only. :::info Plan availability Business and above. Members-only screens, gated video, and the content paywall need the content-gating feature; on lower plans (or if a subscription lapses) gated content is not served.' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: 'Let visitors sign up', anchor: '#let-visitors-sign-up', text: 'Enable site membership so visitors can sign in / sign up to your site. New members flow into your Contacts CRM automatically.' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: 'Sign-in, sign-up, and recovery pages', anchor: '#sign-in-sign-up-and-recovery-pages', text: 'Every site serves three membership routes out of the box: - /signin — email + password sign-in - /signup — create an account - /recover — forgotten-password recovery By default these render simple built-in forms styled with your site theme. To make them fully yours, design them in the besigner like any other screen: 1. Create a screen and drop in the matching block from the Members group of the element picker — Member sign-in, Member sign-up, or Password recovery. Add anything else you like around it: your logo, imagery, copy. 2. Open Setup → Basic details → Sign-in & sign-up pages and assign the screen to its route. Assigned screens render through the normal pipeline — your theme, shared layout, and all — and are kept out of search results. Clearing a slot falls back to the built-in form. :::tip Send members back where they came from The sign-in and sign-up blocks honor a continue query parameter (e.g. /signin?continue=/members/welcome), so links from gated pages can return the visitor to the page they wanted. Only same-site paths are followed. ### Forgotten passwords Members who forget their password can request a reset from the Forgot password? link on the sign-in form (or by visiting /recover directly): 1. The member enters their account email. The response is always the same, so the form can\'t be used to check whether an address has an account. 2. If the address belongs to a member, they receive an email with a reset link to your site. The link works once and expires after one hour — and completing a reset invalidates any other outstanding links. 3. The member sets a new password and signs in with it. Suspended members don\'t receive reset emails.' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: 'Gate a screen', anchor: '#gate-a-screen', text: '1. Open the screen you want to protect. 2. Mark it members-only. 3. Publish. Only signed-in members can now view it; everyone else is prompted to sign in.' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: 'Manage your members', anchor: '#manage-your-members', text: 'The site\'s Users page lists everyone who signed up on your published site — searchable and paged, newest first. Click a member to open their detail drawer: - Profile — email, display name, join date, and saved addresses. - Order history — the member\'s payment records, newest first: order number, status, total, and date, plus the Stripe payment reference and any refunded amount. Order history is visible to site admins and editors. - Subscriptions — active and past storefront subscriptions with their renewal date. - Lifetime purchases — everything the member actually paid: charged order totals minus refunds (pending and cancelled orders don\'t count). ### Suspend or reactivate a member From the drawer you can suspend a member (with a confirmation). A suspended member: - can no longer sign in on your published site — they see a clear "account suspended" message; - is signed out the next time their account page loads; - keeps all orders, subscriptions, and history — nothing is deleted. Reactivate restores access with the member\'s existing password. The member list shows each account\'s Active/Suspended status at a glance.' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: 'Tips', anchor: '#tips', text: '- Combine members-only screens with email campaigns to nurture your member base. - For one-off protection without accounts, use a per-screen password instead.' },
  { path: '/workspace-and-billing/teams-and-roles/members-only', title: 'Members-only areas', heading: 'Related', anchor: '#related', text: '- Invite teammates - Contacts CRM - Site protection & error pages' },
  { path: '/workspace-and-billing/teams-and-roles/overview', title: 'Teams, Roles & Membership', heading: '', anchor: '', text: '# Teams, Roles & Membership Aglyn has two kinds of people: your team (who build and manage the site) and site members (visitors who sign up to your site). Both are permission-aware. :::info Plan availability Paid. Seats are metered per tier; see Billing & plans.' },
  { path: '/workspace-and-billing/teams-and-roles/overview', title: 'Teams, Roles & Membership', heading: 'Team roles', anchor: '#team-roles', text: '- Invite teammates to a site and assign roles. - Create custom roles with unique permission sets. - Apply per-member overrides on top of a role. - Permissions are enforced across the console\'s APIs and surfaces, and team members act in the owner\'s organization, not their own.' },
  { path: '/workspace-and-billing/teams-and-roles/overview', title: 'Teams, Roles & Membership', heading: 'Organizations', anchor: '#organizations', text: 'Aglyn is built around organization workspaces: an organization subscribes once, owns multiple websites, and shares media, plugins, dynamic data and billing across them. You can belong to several organizations with a different role in each (owner, admin, editor, viewer), and editors/viewers can be limited to specific sites. Each organization gets a Slack-style workspace address (your-org.aglyn.com). Every account operates inside an organization — solo accounts simply get a personal workspace automatically. The team features above keep working unchanged. ### Three kinds of user The Team table labels every row with its type, because the type — not the role — decides which seat it uses. The same editor role is one or the other depending on whether their reach is the whole organization or a list of sites: | Type | Reach | Seat | | Team manager | The whole organization | One of your team seats (managersPerOrg) | | Site collaborator | Only the site(s) they\'re granted | A collaborator seat on each site they can reach — never a team seat | | Site member | A published site, as a visitor with an account | None. Free and unlimited on every plan | Pending invites carry the same label, so you can tell a pending manager from a pending collaborator before it\'s accepted. ### What a site collaborator sees Someone invited to a specific site rather than the whole organization gets a console scoped to that site: they land on it when they sign in, and the organization pages — Team, Media, Data, Plugins, Marketplace, Billing, Settings — aren\'t part of their console at all. With access to more than one site, they get the sites list to choose from. Organization-wide members see everything as before. Support is one of those organization pages, so a site collaborator raises problems with whoever ' },
  { path: '/workspace-and-billing/teams-and-roles/overview', title: 'Teams, Roles & Membership', heading: 'Site membership', anchor: '#site-membership', text: '- Visitors can sign in / sign up to your site. - Member accounts are unlimited on every plan — including Free. Signups are never metered, capped, or charged per account. - Gate screens as members-only so only signed-in members can view them. - New members flow into your contacts CRM.' },
  { path: '/workspace-and-billing/teams-and-roles/overview', title: 'Teams, Roles & Membership', heading: 'Seats', anchor: '#seats', text: 'Seats cover your team only: organization seats (workspace-wide) and per-site collaborator seats (teammates limited to one site). Both are metered and enforced; buy seat add-ons to grow. Site member accounts — visitors who sign up to your published site — are not seats and are never capped. See Billing & plans. :::tip How-tos - Invite teammates - Custom roles & permissions - Members-only areas' },
  { path: '/workspace-and-billing/teams-and-roles/overview', title: 'Teams, Roles & Membership', heading: 'Related', anchor: '#related', text: '- Billing & plans - Staff console (Aglyn staff only)' },
]
